  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused ||
        state == AppLifecycleState.inactive ||
        state == AppLifecycleState.detached) {
      final nextLoc = _getNextLocation();
      if (nextLoc != null) {
        _triggerLiveActivityNotification(nextLoc);
      }
    }
  }

  Future<void> _triggerLiveActivityNotification(
    Map<String, dynamic>? nextLoc,
  ) async {
    if (nextLoc == null) return;

    final prefs = await SharedPreferences.getInstance();
    final bool notifEnabled = prefs.getBool('notif_enabled') ?? true;
    if (!notifEnabled) {
      return;
    }

    final currentItinId = (_itineraryData['id'] is num)
        ? (_itineraryData['id'] as num).toInt()
        : int.tryParse(_itineraryData['id']?.toString() ?? '') ?? 0;

    if (currentItinId > 0) {
      await prefs.setInt('primary_itinerary_id', currentItinId);
    }
    final place = nextLoc['place'] ?? {};
    final String name = place['name'] ?? 'Điểm đến tiếp theo';
    final String rawAddress = place['address'] ?? '';
    final String? startTime = nextLoc['startTime'];
    final String? endTime = nextLoc['endTime'];

    String cleanAddr = StringUtils.cleanAddress(rawAddress)
        .replaceAll(RegExp(r'\b\d{5,6}\b'), '')
        .replaceAll(RegExp(r'\s*,\s*,'), ',')
        .replaceAll(RegExp(r'^\s*,\s*|\s*,\s*$'), '')
        .trim();

    String timeInfo = '';
    if (startTime != null && endTime != null) {
      timeInfo = '$startTime - $endTime';
    } else if (startTime != null) {
      timeInfo = startTime;
    }

    final int day = (nextLoc['day'] as num?)?.toInt() ?? 1;
    String dateStr = '';
    final dynamic startDateRaw =
        _itineraryData['startDate'] ?? _itineraryData['start_date'];
    if (startDateRaw != null) {
      DateTime? startDate;
      if (startDateRaw is DateTime) {
        startDate = startDateRaw;
      } else if (startDateRaw is String) {
        startDate = DateTime.tryParse(startDateRaw);
      }
      if (startDate != null) {
        final targetDate = startDate.add(Duration(days: day - 1));
        final String dayStr = targetDate.day.toString().padLeft(2, '0');
        final String monthStr = targetDate.month.toString().padLeft(2, '0');
        final String yearStr = targetDate.year.toString();
        dateStr = '$dayStr/$monthStr/$yearStr';
      }
    }

    final String dayAndDateText = dateStr.isNotEmpty
        ? 'Ngày $day ($dateStr)'
        : 'Ngày $day';

    try {
      final flutterLocalNotificationsPlugin = FlutterLocalNotificationsPlugin();

      const initializationSettingsAndroid = AndroidInitializationSettings(
        '@mipmap/ic_launcher',
      );
      const initializationSettingsDarwin = DarwinInitializationSettings();
      const initializationSettings = InitializationSettings(
        android: initializationSettingsAndroid,
        iOS: initializationSettingsDarwin,
      );

      await flutterLocalNotificationsPlugin.initialize(initializationSettings);

      const androidChannel = AndroidNotificationChannel(
        'cloudmood_live_destination_v2',
        'Điểm đến tiếp theo',
        description:
            'Thông báo đẩy ghim điểm đến trên thanh trạng thái và màn hình khóa',
        importance: Importance.max,
        playSound: true,
        enableVibration: true,
      );

      final androidPlugin = flutterLocalNotificationsPlugin
          .resolvePlatformSpecificImplementation<
            AndroidFlutterLocalNotificationsPlugin
          >();
      if (androidPlugin != null) {
        await androidPlugin.createNotificationChannel(androidChannel);
        await androidPlugin.requestNotificationsPermission();
      }

      final bodyText =
          '🗓️ $dayAndDateText • ⏰ ${timeInfo.isNotEmpty ? timeInfo : "Chuẩn bị khởi hành"}${cleanAddr.isNotEmpty ? " • $cleanAddr" : ""}';

      final androidDetails = AndroidNotificationDetails(
        'cloudmood_live_destination_v2',
        'Điểm đến tiếp theo',
        channelDescription:
            'Thông báo đẩy ghim điểm đến trên thanh trạng thái và màn hình khóa',
        importance: Importance.max,
        priority: Priority.high,
        ongoing: true,
        autoCancel: false,
        onlyAlertOnce: true,
        playSound: true,
        enableVibration: true,
        visibility: NotificationVisibility.public,
        styleInformation: BigTextStyleInformation(bodyText),
      );

      const darwinDetails = DarwinNotificationDetails(
        presentAlert: true,
        presentBadge: true,
        presentSound: true,
        interruptionLevel: InterruptionLevel.timeSensitive,
      );

      final notificationDetails = NotificationDetails(
        android: androidDetails,
        iOS: darwinDetails,
      );

      await flutterLocalNotificationsPlugin.show(
        8888,
        '📍 ĐIỂM ĐẾN TIẾP THEO: $name',
        bodyText,
        notificationDetails,
      );
    } catch (e) {
      debugPrint('Notification trigger error: $e');
    }
  }

  Future<void> _loadVisitedDetails() async {
    final prefs = await SharedPreferences.getInstance();
    final itinId = _itineraryData['id'];
    final list = prefs.getStringList('visited_details_$itinId') ?? [];
    final localVisited = list
        .map((e) => int.tryParse(e) ?? 0)
        .where((id) => id > 0)
        .toSet();
    final hasServerState = _details.any(
      (detail) => detail.containsKey('isVisited'),
    );
    final serverVisited = _details
        .where((detail) => detail['isVisited'] == true)
        .map<int>((detail) => (detail['id'] as num).toInt())
        .toSet();
    final migrationKey = 'visited_state_migrated_$itinId';
    final shouldMigrateLocalState =
        hasServerState &&
        prefs.getBool(migrationKey) != true &&
        localVisited.isNotEmpty;
    final visited = hasServerState
        ? {...serverVisited, if (shouldMigrateLocalState) ...localVisited}
        : localVisited;
    if (shouldMigrateLocalState) {
      final localOnlyIds = localVisited.difference(serverVisited);
      await Future.wait(
        localOnlyIds.map(
          (id) =>
              DatabaseService().updateItineraryDetail(id, {'isVisited': true}),
        ),
      );
      await prefs.setBool(migrationKey, true);
    } else if (hasServerState && prefs.getBool(migrationKey) != true) {
      await prefs.setBool(migrationKey, true);
    }
    if (mounted) {
      setState(() {
        _visitedDetailIds = visited;
      });
      await prefs.setStringList(
        'visited_details_$itinId',
        visited.map((e) => e.toString()).toList(),
      );
      _autoScrollToFirstUnvisitedDay();
    }
  }

  void _autoScrollToFirstUnvisitedDay() {
    final nextLoc = _getNextLocation();
    if (nextLoc != null) {
      final unvisitedDay = (nextLoc['day'] as num?)?.toInt() ?? 1;
      final dayIndex = (unvisitedDay - 1).clamp(0, 30);
      if (dayIndex != _activeDayIndex && mounted) {
        setState(() {
          _activeDayIndex = dayIndex;
        });
      }
    }
  }

  Future<void> _toggleVisitedDetail(
    int detailId,
    Map<String, dynamic> detail,
  ) async {
    final prefs = await SharedPreferences.getInstance();
    final itinId = _itineraryData['id'];
    final bool wasVisited = _visitedDetailIds.contains(detailId);
    setState(() {
      if (wasVisited) {
        _visitedDetailIds.remove(detailId);
      } else {
        _visitedDetailIds.add(detailId);
      }
    });
    await prefs.setStringList(
      'visited_details_$itinId',
      _visitedDetailIds.map((e) => e.toString()).toList(),
    );
    final savedOnServer = await DatabaseService().updateItineraryDetail(
      detailId,
      {'isVisited': !wasVisited},
    );
    if (!savedOnServer) {
      if (mounted) {
        setState(() {
          if (wasVisited) {
            _visitedDetailIds.add(detailId);
          } else {
            _visitedDetailIds.remove(detailId);
          }
        });
        await prefs.setStringList(
          'visited_details_$itinId',
          _visitedDetailIds.map((e) => e.toString()).toList(),
        );
        _showPremiumNotification(
          title: 'Không thể lưu trạng thái',
          message: 'Vui lòng kiểm tra kết nối và thử lại.',
          icon: Icons.error_outline_rounded,
          color: Colors.orange,
        );
      }
      return;
    }
    detail['isVisited'] = !wasVisited;

    if (wasVisited) {
      _showPremiumNotification(
        title: 'Đã hoàn tác ghé thăm',
        message: 'Địa điểm đã được chuyển lại thành Chưa ghé.',
        icon: Icons.undo_rounded,
        color: const Color(0xFF64748B),
      );
    } else if (_visitedDetailIds.contains(detailId)) {
      final placeName = detail['place']?['name'] ?? 'Địa điểm';
      int currentIdx = _details.indexWhere((d) => d['id'] == detailId);
      Map<String, dynamic>? nextDetail;
      if (currentIdx != -1 && currentIdx < _details.length - 1) {
        for (int i = currentIdx + 1; i < _details.length; i++) {
          if (!_visitedDetailIds.contains(_details[i]['id'])) {
            nextDetail = _details[i];
            break;
          }
        }
      }

      if (nextDetail != null && mounted) {
        final nextName = nextDetail['place']?['name'] ?? 'địa điểm tiếp theo';
        final int nextDay = (nextDetail['day'] as num?)?.toInt() ?? 1;

        if (nextDay - 1 != _activeDayIndex) {
          setState(() {
            _activeDayIndex = nextDay - 1;
            _dayCollapsed[_activeDayIndex] = false;
          });
        }

        _showPremiumNotification(
          title: 'Đã ghé thăm: $placeName! 🎉',
          message:
              'Tự động chuyển sang địa điểm tiếp theo: $nextName (Ngày $nextDay)',
          icon: Icons.check_circle_rounded,
          color: Colors.green,
        );
      } else if (mounted) {
        _showPremiumNotification(
          title: 'Tuyệt vời! 🎉',
          message: 'Bạn đã hoàn tất tất cả các địa điểm trong lịch trình!',
          icon: Icons.emoji_events_rounded,
          color: Colors.amber,
        );
      }
    }
    final nextLoc = _getNextLocation();
    if (nextLoc != null) {
      _triggerLiveActivityNotification(nextLoc);
    }
  }

