  // Expense Tab custom items
  String _formatTimeStr(String t) {
    if (t.contains('T')) {
      try {
        final dt = DateTime.parse(t).toLocal();
        return '${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}';
      } catch (_) {}
    }
    return t.length >= 5 ? t.substring(0, 5) : t;
  }

