  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _itineraryData = widget.itinerary;

    _guideIntroFocusNode.addListener(() {
      if (!_guideIntroFocusNode.hasFocus) {
        _saveGuideIntro();
      }
    });

    // Request Android notification permission on foreground init & sync primary trip ID
    try {
      final flutterLocalNotificationsPlugin = FlutterLocalNotificationsPlugin();
      const initializationSettingsAndroid = AndroidInitializationSettings(
        '@mipmap/ic_launcher',
      );
      const initializationSettingsDarwin = DarwinInitializationSettings();
      flutterLocalNotificationsPlugin.initialize(
        const InitializationSettings(
          android: initializationSettingsAndroid,
          iOS: initializationSettingsDarwin,
        ),
      );
      flutterLocalNotificationsPlugin
          .resolvePlatformSpecificImplementation<
            AndroidFlutterLocalNotificationsPlugin
          >()
          ?.requestNotificationsPermission();
    } catch (_) {}

    final currentItinId = (_itineraryData['id'] is num)
        ? (_itineraryData['id'] as num).toInt()
        : int.tryParse(_itineraryData['id']?.toString() ?? '') ?? 0;

    final currentUser = AuthService().currentUser.value;
    final currentUserIdStr = currentUser?.id?.toString();
    final ownerIdStr =
        (_itineraryData['userId'] ??
                _itineraryData['user_id'] ??
                _itineraryData['user']?['id'] ??
                _itineraryData['authorId'] ??
                _itineraryData['author']?['id'])
            ?.toString();

    if (currentUserIdStr != null &&
        ownerIdStr != null &&
        currentUserIdStr == ownerIdStr) {
      _currentRole = 'OWNER';
    } else if (_itineraryData['role'] != null) {
      _currentRole = _itineraryData['role'].toString().toUpperCase();
    } else {
      _currentRole = 'OWNER';
    }
    _privacySetting = 'private';
    SharedPreferences.getInstance().then((prefs) {
      if (currentItinId > 0) {
        prefs.setInt('primary_itinerary_id', currentItinId);
      }
      final saved = prefs.getString('privacy_${_itineraryData['id']}');
      if (saved != null && mounted) {
        setState(() => _privacySetting = saved);
      }
    });
    final int numDays = (_itineraryData['days'] as int?) ?? 1;
    _checkedDays = Set.from(Iterable.generate(numDays, (i) => i + 1));
    final bool isGuide = _itineraryData['isGuide'] == true;
    final int targetInitialIndex = widget.initialTabIndex.clamp(
      0,
      isGuide ? 1 : 3,
    );
    _tabController = TabController(
      length: isGuide ? 2 : 4,
      vsync: this,
      initialIndex: targetInitialIndex,
    );
    final String dest = _itineraryData['destination'] ?? '';
    if (_cachedDestination == dest) {
      _explorePosts = _cachedExplorePosts;
      _hasFetchedExplore = true;
    } else {
      _explorePosts = [];
      _hasFetchedExplore = false;
    }

    _tabController.addListener(() {
      if (_tabController.indexIsChanging) return;
      final int exploreIdx = (_itineraryData['isGuide'] == true) ? 1 : 3;
      if (_tabController.index == exploreIdx) {
        _fetchExplorePosts();
      }
    });
    _fetchExplorePosts();

    // Initialize details and savedPlaces from passed itinerary if available
    final rawDetails = List<Map<String, dynamic>>.from(
      _itineraryData['details'] ?? [],
    );
    rawDetails.sort((a, b) {
      final int orderA = a['sortOrder'] ?? 0;
      final int orderB = b['sortOrder'] ?? 0;
      if (orderA != orderB) {
        return orderA.compareTo(orderB);
      }
      final int idA = a['id'] ?? 0;
      final int idB = b['id'] ?? 0;
      return idA.compareTo(idB);
    });
    _details = rawDetails;

    final rawSaved = List<Map<String, dynamic>>.from(
      _itineraryData['savedPlaces'] ?? [],
    );
    rawSaved.sort((a, b) {
      final int orderA = a['sortOrder'] ?? 0;
      final int orderB = b['sortOrder'] ?? 0;
      if (orderA != orderB) {
        return orderA.compareTo(orderB);
      }
      final int idA = a['id'] ?? 0;
      final int idB = b['id'] ?? 0;
      return idA.compareTo(idB);
    });
    _parseSectionsData();
    final dayConfigs = _itineraryData['dayConfigs'] as Map<String, dynamic>?;
    if (dayConfigs != null) {
      try {
        dayConfigs.forEach((k, v) {
          if (v is Map && v['color'] != null) {
            _dayColors[int.parse(k)] = _filterHarshColor(
              Color(int.parse(v['color'].toString())),
            );
          }
        });
      } catch (_) {}
    }
    for (int i = 0; i < numDays; i++) {
      if (!_dayColors.containsKey(i) ||
          _dayColors[i] == const Color(0xFF40E0D0) ||
          _dayColors[i] == const Color(0xFF36E4C7) ||
          _dayColors[i] == const Color(0xFF64FFDA)) {
        _dayColors[i] = _filterHarshColor(
          _availableColors[i % _availableColors.length],
        );
      }
    }

    _itineraryScrollController.addListener(_onItineraryScroll);

    // Skip full screen blocking loader if initial details or places are present
    _isLoading = _details.isEmpty && _savedPlaces.isEmpty;
    // Đợi dữ liệu server về rồi mới hợp nhất trạng thái "đã ghé" cũ trên máy,
    // tránh hai Future chạy song song và ghi đè kết quả migration của nhau.
    _loadData(
      silent: _details.isNotEmpty || _savedPlaces.isNotEmpty,
    ).whenComplete(_loadVisitedDetails);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _loadAutoWeatherSettings(showLatestChange: true);
    });

    // Kết nối Socket Real-time cho Chuyến đi
    final itinId = _itineraryData['id'] is int
        ? _itineraryData['id']
        : int.parse(_itineraryData['id'].toString());

    UserModel? user = AuthService().currentUser.value;
    Map<String, dynamic>? userData;
    if (user != null) {
      userData = {
        'id': user.id,
        'fullName': user.fullName,
        'avatarUrl': user.avatar,
        'email': user.email,
        'role': _itineraryData['role'] ?? 'MEMBER',
      };
      _activeMembers = [userData];
    }

    ItinerarySocketService().connect();
    ItinerarySocketService().joinItinerary(itinId, user: userData);
    ItinerarySocketService().addUpdateListener(_onItinerarySocketUpdated);
    ItinerarySocketService().addActiveMembersListener(_onActiveMembersUpdated);
    ItinerarySocketService().addNoteTypingListener(_onNoteTypingUpdated);
  }

  void _onNoteTypingUpdated(Map<String, dynamic> data) {
    final eventItinId = data['itineraryId']?.toString();
    final currentItinId = _itineraryData['id']?.toString();
    final updatedByUserId = data['updatedByUserId']?.toString();
    final currentUserId = AuthService().currentUser.value?.id?.toString();

    if (eventItinId == currentItinId &&
        updatedByUserId != currentUserId &&
        mounted) {
      final int noteId = data['noteId'] as int;
      final String text = data['text'] as String;
      final bool isItineraryDetail = data['isItineraryDetail'] == true;

      setState(() {
        if (isItineraryDetail) {
          final idx = _details.indexWhere((d) => d['id'] == noteId);
          if (idx != -1) _details[idx]['noteText'] = text;
        } else {
          final idx = _savedPlaces.indexWhere((sp) => sp['id'] == noteId);
          if (idx != -1) _savedPlaces[idx]['noteText'] = text;
        }
      });
    }
  }

  void _onItinerarySocketUpdated(Map<String, dynamic> data) {
    final eventItinId = data['itineraryId']?.toString();
    final currentItinId = _itineraryData['id']?.toString();
    final updatedByUserId = data['updatedByUserId']?.toString();
    final currentUserId = AuthService().currentUser.value?.id?.toString();
    final actionType = data['actionType']?.toString() ?? '';

    if (eventItinId == currentItinId &&
        (updatedByUserId == null || updatedByUserId != currentUserId) &&
        mounted) {
      // Debounce: trì hoãn reload 1.5s để gom nhiều event liên tiếp
      // và tránh flicker khi optimistic update đang áp dụng
      _socketReloadTimer?.cancel();
      _socketReloadTimer = Timer(const Duration(milliseconds: 1500), () async {
        if (mounted && !_isUpdatingDatabase) {
          debugPrint(
            '⚡ Real-time update từ máy chủ: Đang cập nhật dữ liệu ngầm...',
          );
          await _loadData(silent: true);
          if (actionType.startsWith('AUTO_WEATHER')) {
            await _loadAutoWeatherSettings(showLatestChange: true);
          }
        }
      });
    }
  }

  void _onActiveMembersUpdated(Map<String, dynamic> data) {
    final eventItinId = data['itineraryId']?.toString();
    final currentItinId = _itineraryData['id']?.toString();
    if (eventItinId == currentItinId && mounted) {
      final List<dynamic> list = data['activeMembers'] ?? [];
      final Map<String, Map<String, dynamic>> uniqueMap = {};
      for (var item in list) {
        if (item is Map) {
          final m = Map<String, dynamic>.from(item);
          final uid = (m['userId'] ?? m['id'])?.toString();
          if (uid != null) {
            uniqueMap[uid] = m;
          }
        }
      }
      setState(() {
        _activeMembers = uniqueMap.values.toList();
      });
    }
  }

  bool _isProgrammaticScrolling = false;

  void _onItineraryScroll() {
    if (_isProgrammaticScrolling || !_itineraryScrollController.hasClients)
      return;

    final numDays = (_itineraryData['days'] as num?)?.toInt() ?? 1;
    if (numDays <= 1) return;

    int newlyActiveDay = 0;
    final double currentOffset = _itineraryScrollController.offset;

    // 1. Calculate accumulated offset for each day
    double accumulated = 0.0;
    for (int k = 0; k < numDays; k++) {
      final placesCount = _details.where((d) => d['day'] == (k + 1)).length;
      final isCollapsed = _dayCollapsed[k] == true;
      final dayHeight = isCollapsed ? 90.0 : (160.0 + (placesCount * 360.0));

      if (currentOffset >= accumulated - 80.0) {
        newlyActiveDay = k;
      }
      accumulated += dayHeight;
    }

    // 2. Fine-tune using RenderBox position if context is rendered
    for (int k = numDays - 1; k >= 0; k--) {
      final key = _dayKeys[k];
      if (key?.currentContext != null) {
        final box = key!.currentContext!.findRenderObject() as RenderBox?;
        if (box != null && box.attached) {
          final position = box.localToGlobal(Offset.zero);
          if (position.dy <= 300 && position.dy >= -500) {
            newlyActiveDay = k;
            break;
          }
        }
      }
    }

    if (newlyActiveDay != _activeDayIndex && mounted) {
      setState(() {
        _activeDayIndex = newlyActiveDay;
      });
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    final itinId = _itineraryData['id'] is int
        ? _itineraryData['id']
        : int.parse(_itineraryData['id'].toString());
    ItinerarySocketService().removeUpdateListener(_onItinerarySocketUpdated);
    ItinerarySocketService().removeActiveMembersListener(
      _onActiveMembersUpdated,
    );
    ItinerarySocketService().leaveItinerary(itinId);

    _currentNotification?.remove();
    _currentNotification = null;
    _socketReloadTimer?.cancel();
    _tabController.dispose();
    _itineraryScrollController.removeListener(_onItineraryScroll);
    _itineraryScrollController.dispose();
    for (var controller in _searchControllers.values) {
      controller.dispose();
    }
    _sectionTitleController.dispose();
    _sectionTitleFocusNode.dispose();
    for (final ctrl in _noteControllers.values) {
      ctrl.dispose();
    }
    for (final ctrl in _todoAddControllers.values) {
      ctrl.dispose();
    }
    _saveGuideIntro();
    _guideIntroFocusNode.dispose();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      DatabaseService.refreshTrigger.value++;
    });
    super.dispose();
  }

  Future<void> _saveGuideIntro() async {
    final newIntro = _guideIntroController.text.trim();
    if (_lastSavedGuideIntro == newIntro) return;
    _lastSavedGuideIntro = newIntro;
    _itineraryData['description'] = newIntro;

    final rawId = _itineraryData['id'];
    final itinId = (rawId is int)
        ? rawId
        : (rawId != null ? int.tryParse(rawId.toString()) : null);
    if (itinId != null) {
      await DatabaseService().updateItinerary(itinId, {
        'description': newIntro,
      });
      if (_privacySetting == 'public') {
        _syncPublicPostIfNeeded();
      }
    }
  }

  void _saveSectionTitle(String oldTitle, String newTitle) {
    if (!_checkCanEdit()) {
      setState(() => _editingSection = null);
      return;
    }
    if (newTitle.trim().isEmpty || newTitle == oldTitle) {
      setState(() {
        _editingSection = null;
      });
      return;
    }

    String finalTitle = newTitle.trim();
    int counter = 1;
    while (_sectionNames.any(
      (sec) => sec.toLowerCase() == finalTitle.toLowerCase() && sec != oldTitle,
    )) {
      finalTitle = '${newTitle.trim()} $counter';
      counter++;
    }
    newTitle = finalTitle;

    setState(() {
      final index = _sectionNames.indexOf(oldTitle);
      if (index != -1) {
        _sectionNames[index] = newTitle;
        if (_searchControllers.containsKey(oldTitle)) {
          _searchControllers[newTitle] = _searchControllers.remove(oldTitle)!;
        }
        if (_searchResults.containsKey(oldTitle)) {
          _searchResults[newTitle] = _searchResults.remove(oldTitle)!;
        }
        for (var d in _savedPlaces) {
          if (d['section'] == oldTitle) {
            d['section'] = newTitle;
            if (d['id'] != null) {
              DatabaseService().updateSavedPlace(d['id'] as int, {
                'section': newTitle,
              });
            }
          }
        }
        if (_sectionColors.containsKey(oldTitle)) {
          _sectionColors[newTitle] = _sectionColors.remove(oldTitle)!;
        }
        if (_sectionIcons.containsKey(oldTitle)) {
          _sectionIcons[newTitle] = _sectionIcons.remove(oldTitle)!;
        }
      }
      _deletedSectionNames.add(oldTitle.toLowerCase().trim());
      _editingSection = null;
    });

    // Sync the rename to database (delete old, insert new)
    final itinId = _itineraryData['id'] as int;
    SharedPreferences.getInstance().then((prefs) {
      prefs.setStringList(
        'deleted_sections_$itinId',
        _deletedSectionNames.toList(),
      );
    });
    DatabaseService().deleteItinerarySection(itinId, oldTitle);
    _syncSectionsToDatabase();
  }

  void _showSectionStyleSheet(
    BuildContext context,
    String sectionName, {
    int initialTabIndex = 0,
  }) {
    if (!_checkCanEdit()) return;
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (context) => SectionStyleSheet(
        initialSection: sectionName,
        sections: _sectionNames,
        savedPlaces: _savedPlaces,
        sectionColors: _sectionColors,
        sectionIcons: _sectionIcons,
        initialTabIndex: initialTabIndex,
        onSaved: (newSections, newPlaces, newColors, newIcons) async {
          _socketReloadTimer?.cancel();

          setState(() {
            _sectionNames.clear();
            _sectionNames.addAll(newSections);
            _savedPlaces = newPlaces;
            _sectionColors.clear();
            _sectionColors.addAll(newColors);
            if (newIcons != null) {
              _sectionIcons.clear();
              _sectionIcons.addAll(newIcons);
            }
          });

          await _syncSectionsToDatabase();

          for (var p in _savedPlaces) {
            if (p['id'] != null) {
              await DatabaseService().updateSavedPlace(p['id'] as int, {
                'section': p['section'],
                'sortOrder': p['sortOrder'],
              });
            }
          }

          await _loadData(silent: true);
        },
      ),
    );
  }

  void _showItineraryStyleSheet(
    BuildContext context, {
    int initialTabIndex = 0,
    int initialDayIndex = 0,
  }) {
    if (!_checkCanEdit()) return;
    final int totalDays = (_itineraryData['days'] as num?)?.toInt() ?? 1;

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (context) => ItineraryStyleSheet(
        daysCount: totalDays,
        details: _details,
        dayColors: _dayColors,
        initialTabIndex: initialTabIndex,
        initialDayIndex: initialDayIndex,
        onSaved: (newDetails, newColors) async {
          _socketReloadTimer?.cancel();

          setState(() {
            _dayColors.clear();
            _dayColors.addAll(newColors);
            _details = newDetails;
          });

          await _saveDayColors();

          for (var p in _details) {
            await DatabaseService().updateItineraryDetail(p['id'] as int, {
              'day': p['day'],
              'sortOrder': p['sortOrder'],
            });
          }

          await _loadData(silent: true);
        },
      ),
    );
  }

  void _showPremiumNotification({
    required String message,
    required IconData icon,
    required Color color,
    String? title,
    String? actionLabel,
    VoidCallback? onAction,
    Duration displayDuration = const Duration(seconds: 3),
  }) {
    if (!mounted) return;

    // Clear existing notification
    _currentNotification?.remove();
    _currentNotification = null;

    final overlay = Overlay.of(context);
    final entry = OverlayEntry(
      builder: (context) {
        return Positioned(
          top: MediaQuery.of(context).padding.top + 16,
          left: 16,
          right: 16,
          child: Material(
            color: Colors.transparent,
            child: TweenAnimationBuilder<double>(
              tween: Tween(begin: 0.0, end: 1.0),
              duration: const Duration(milliseconds: 300),
              curve: Curves.easeOutBack,
              builder: (context, val, child) {
                return Opacity(
                  opacity: val.clamp(0.0, 1.0),
                  child: Transform.translate(
                    offset: Offset(0, -20 * (1.0 - val)),
                    child: child,
                  ),
                );
              },
              child: Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(color: AppTheme.border),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withAlpha(20),
                      blurRadius: 24,
                      offset: const Offset(0, 10),
                    ),
                  ],
                ),
                child: Row(
                  children: [
                    Container(
                      padding: const EdgeInsets.all(8),
                      decoration: BoxDecoration(
                        color: color.withAlpha(25),
                        shape: BoxShape.circle,
                      ),
                      child: Icon(icon, color: color, size: 20),
                    ),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          if (title != null)
                            Text(
                              title,
                              style: TextStyle(
                                fontWeight: FontWeight.bold,
                                color: AppTheme.darkText,
                                fontSize: 13,
                              ),
                            ),
                          Text(
                            message,
                            style: TextStyle(
                              color: title != null
                                  ? AppTheme.subtitleText
                                  : AppTheme.darkText,
                              fontSize: 12,
                              fontWeight: title != null
                                  ? FontWeight.normal
                                  : FontWeight.bold,
                            ),
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ],
                      ),
                    ),
                    if (actionLabel != null && onAction != null) ...[
                      const SizedBox(width: 4),
                      TextButton(
                        style: TextButton.styleFrom(
                          visualDensity: VisualDensity.compact,
                          padding: const EdgeInsets.symmetric(horizontal: 7),
                          minimumSize: const Size(0, 32),
                        ),
                        onPressed: () {
                          _currentNotification?.remove();
                          _currentNotification = null;
                          onAction();
                        },
                        child: Text(
                          actionLabel,
                          maxLines: 1,
                          style: TextStyle(
                            color: color,
                            fontSize: 11,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                    ],
                    const SizedBox(width: 8),
                    GestureDetector(
                      onTap: () {
                        _currentNotification?.remove();
                        _currentNotification = null;
                      },
                      child: Icon(
                        Icons.close_rounded,
                        color: AppTheme.subtitleText,
                        size: 16,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );

    _currentNotification = entry;
    overlay.insert(entry);

    // Auto-remove after 3 seconds
    Future.delayed(displayDuration, () {
      if (entry.mounted && _currentNotification == entry) {
        entry.remove();
        if (_currentNotification == entry) {
          _currentNotification = null;
        }
      }
    });
  }

  Future<void> _fetchMapData() async {
    // 1. Ưu tiên lấy tọa độ từ danh sách địa điểm đã lưu hoặc các địa điểm thuộc điểm đến
    for (var d in _details) {
      final p = d['place'];
      if (p != null && p['latitude'] != null && p['longitude'] != null) {
        final lat = (p['latitude'] as num).toDouble();
        final lon = (p['longitude'] as num).toDouble();
        if (lat != 0.0 && lon != 0.0 && mounted) {
          setState(() => _mapCenter = LatLng(lat, lon));
          return;
        }
      }
    }
    for (var sp in _savedPlaces) {
      final p = sp['place'];
      if (p != null && p['latitude'] != null && p['longitude'] != null) {
        final lat = (p['latitude'] as num).toDouble();
        final lon = (p['longitude'] as num).toDouble();
        if (lat != 0.0 && lon != 0.0 && mounted) {
          setState(() => _mapCenter = LatLng(lat, lon));
          return;
        }
      }
    }

    // 2. Nếu chưa có địa điểm nào, dùng mặc định tọa độ điểm đến Cần Thơ / Việt Nam để tránh lỗi CORS 429 từ trình duyệt web
    if (mounted && _mapCenter == null) {
      setState(() {
        _mapCenter = const LatLng(10.0364634, 105.7875821);
      });
    }
  }

  Future<void> _fetchExplorePosts() async {
    setState(() => _isLoadingExplore = true);
    final String dest = _itineraryData['destination'] ?? '';
    try {
      final posts = await DatabaseService().fetchExplorePosts(
        destination: dest,
      );
      if (mounted) {
        setState(() {
          _explorePosts = posts;
          _cachedExplorePosts = posts;
          _cachedDestination = dest;
        });
      }
    } catch (e) {
      debugPrint('Error fetching explore posts: $e');
    } finally {
      if (mounted) {
        setState(() {
          _isLoadingExplore = false;
          _hasFetchedExplore = true;
        });
      }
    }
  }

  void _updateProminentPlaces() {
    final List<Map<String, dynamic>> prominent = [];
    final Set<int> seenIds = {};
    for (var p in _allPlaces) {
      if (p['id'] != null && !seenIds.contains(p['id'] as int)) {
        seenIds.add(p['id'] as int);
        prominent.add(Map<String, dynamic>.from(p));
      }
    }
    prominent.sort((a, b) {
      final double ratingA = (a['rating'] as num?)?.toDouble() ?? 0.0;
      final double ratingB = (b['rating'] as num?)?.toDouble() ?? 0.0;
      final int countA =
          ((a['userRatingCount'] ??
                      a['user_rating_count'] ??
                      a['reviewsCount'] ??
                      0)
                  as num)
              .toInt();
      final int countB =
          ((b['userRatingCount'] ??
                      b['user_rating_count'] ??
                      b['reviewsCount'] ??
                      0)
                  as num)
              .toInt();

      if (ratingB != ratingA) {
        return ratingB.compareTo(ratingA);
      }
      return countB.compareTo(countA);
    });
    _cachedProminentPlaces = prominent;
  }

  void _parseSectionsData() {
    final savedSections = _itineraryData['sections'] as List<dynamic>?;
    _sectionNames.clear();
    if (savedSections != null && savedSections.isNotEmpty) {
      final List<dynamic> sorted = List.from(savedSections);
      sorted.sort(
        (a, b) => (a['sortOrder'] as int? ?? 0).compareTo(
          b['sortOrder'] as int? ?? 0,
        ),
      );
      for (var sec in sorted) {
        if (sec is Map) {
          final name = sec['name']?.toString();
          if (name != null &&
              name.isNotEmpty &&
              !_deletedSectionNames.contains(name.toLowerCase().trim()) &&
              !_sectionNames.contains(name)) {
            _sectionNames.add(name);
            _searchControllers.putIfAbsent(name, () => TextEditingController());
            _searchResults.putIfAbsent(name, () => []);
            if (sec['colorCode'] != null) {
              try {
                _sectionColors[name] = Color(
                  int.parse(sec['colorCode'].toString()),
                );
              } catch (_) {}
            }
            if (sec['iconCode'] != null) {
              final int rawCode = sec['iconCode'] as int;
              _sectionIcons[name] = rawCode == 983363
                  ? Icons.looks_one_rounded
                  : IconData(rawCode, fontFamily: 'MaterialIcons');
            }
            _sectionTypes[name] = sec['sectionType']?.toString() ?? 'LIST';
          }
        }
      }
    }

    for (var place in _savedPlaces) {
      final section = place['section'] as String?;
      if (section != null &&
          !_deletedSectionNames.contains(section.toLowerCase().trim()) &&
          !_sectionNames.contains(section) &&
          !(section.startsWith('Ngày') && _itineraryData['isGuide'] != true)) {
        _sectionNames.add(section);
        _searchControllers.putIfAbsent(section, () => TextEditingController());
        _searchResults.putIfAbsent(section, () => []);
        _sectionColors.putIfAbsent(
          section,
          () =>
              _availableColors[_sectionNames.length % _availableColors.length],
        );
        _sectionIcons.putIfAbsent(section, () => Icons.folder_rounded);
        _sectionTypes.putIfAbsent(section, () => 'LIST');
      }
    }

    final rawDesc = (_itineraryData['description'] ?? '').toString().trim();
    if (rawDesc.isNotEmpty &&
        rawDesc != 'Riêng tư' &&
        rawDesc != 'Công khai' &&
        rawDesc != 'null') {
      _guideIntroController.text = rawDesc;
      _lastSavedGuideIntro = rawDesc;
    } else {
      _guideIntroController.text = '';
      _lastSavedGuideIntro = '';
    }

    if (_itineraryData['isGuide'] == true) {
      const defaultSec = 'Địa điểm tham quan';
      if (_sectionNames.isEmpty &&
          !_deletedSectionNames.contains(defaultSec.toLowerCase())) {
        _sectionNames.insert(0, defaultSec);
        _searchControllers.putIfAbsent(
          defaultSec,
          () => TextEditingController(),
        );
        _searchResults.putIfAbsent(defaultSec, () => []);
        _sectionColors.putIfAbsent(defaultSec, () => _availableColors[0]);
        _sectionIcons.putIfAbsent(defaultSec, () => Icons.place_rounded);
        _sectionTypes.putIfAbsent(defaultSec, () => 'LIST');
      }
    }

    _checkedSections ??= Set.from(_sectionNames);
  }

  Future<void> _loadData({bool silent = false}) async {
    if (!silent) {
      setState(() => _isLoading = true);
      _fetchExplorePosts();
    }

    // Fetch map data in background
    if (_mapCenter == null) {
      _fetchMapData();
    }
    final itineraryId = _itineraryData['id'] is int
        ? _itineraryData['id'] as int
        : int.parse(_itineraryData['id'].toString());

    // Load privacy setting for this itinerary
    final prefs = await SharedPreferences.getInstance();
    final deletedList =
        prefs.getStringList('deleted_sections_$itineraryId') ?? [];
    _deletedSectionNames.addAll(deletedList.map((e) => e.toLowerCase().trim()));

    final cachedPrivacy = prefs.getString('privacy_$itineraryId');
    if (cachedPrivacy != null) {
      if (mounted) setState(() => _privacySetting = cachedPrivacy);
    } else {
      final comp = (_itineraryData['companion'] ?? '').toString().toLowerCase();
      if (comp.contains('công khai') || comp == 'public') {
        if (mounted) setState(() => _privacySetting = 'public');
      } else if (comp.contains('thành viên') || comp == 'members') {
        if (mounted) setState(() => _privacySetting = 'members');
      } else if (comp.contains('riêng tư') || comp == 'private') {
        if (mounted) setState(() => _privacySetting = 'private');
      } else {
        final bool isGuide = _itineraryData['isGuide'] == true;
        if (mounted)
          setState(() => _privacySetting = isGuide ? 'public' : 'members');
      }
    }

    // Fetch member roles to get exact currentRole of user
    DatabaseService().getItineraryMembers(itineraryId).then((membersData) {
      if (membersData != null && mounted) {
        setState(() {
          if (membersData['currentRole'] != null) {
            _currentRole = membersData['currentRole'].toString().toUpperCase();
          }
          if (membersData['members'] is List) {
            _itineraryMembers = List<Map<String, dynamic>>.from(
              membersData['members'],
            );
          }
        });
      }
    });

    // Fetch refreshed itinerary details
    final refreshed = await DatabaseService().fetchItineraryById(itineraryId);
    if (refreshed != null && mounted) {
      _itineraryData = refreshed;
      final comp = (refreshed['companion'] ?? '').toString().toLowerCase();
      String newPrivacy = _privacySetting;
      if (comp.contains('công khai') || comp == 'public') {
        newPrivacy = 'public';
      } else if (comp.contains('thành viên') || comp == 'members') {
        newPrivacy = 'members';
      } else if (comp.contains('riêng tư') || comp == 'private') {
        newPrivacy = 'private';
      }
      if (newPrivacy != _privacySetting) {
        setState(() {
          _privacySetting = newPrivacy;
        });
        prefs.setString('privacy_$itineraryId', newPrivacy);
      }
      final rawDetails = List<Map<String, dynamic>>.from(
        refreshed['details'] ?? [],
      );
      rawDetails.sort((a, b) {
        final int orderA = a['sortOrder'] ?? 0;
        final int orderB = b['sortOrder'] ?? 0;
        if (orderA != orderB) {
          return orderA.compareTo(orderB);
        }
        final int idA = a['id'] ?? 0;
        final int idB = b['id'] ?? 0;
        return idA.compareTo(idB);
      });
      final cleanDetails = rawDetails
          .where((d) => !_deletingDetailIds.contains(d['id']))
          .toList();

      final rawSaved = List<Map<String, dynamic>>.from(
        refreshed['savedPlaces'] ?? [],
      );
      rawSaved.sort((a, b) {
        final int orderA = a['sortOrder'] ?? 0;
        final int orderB = b['sortOrder'] ?? 0;
        if (orderA != orderB) {
          return orderA.compareTo(orderB);
        }
        final int idA = a['id'] ?? 0;
        final int idB = b['id'] ?? 0;
        return idA.compareTo(idB);
      });
      final cleanSaved = rawSaved
          .where((sp) => !_deletingDetailIds.contains(sp['id']))
          .toList();

      // Preserve pending optimistic temporary items (id >= 1000000000000)
      final pendingTempSaved = _savedPlaces
          .where((sp) => ((sp['id'] as num?)?.toInt() ?? 0) >= 1000000000000)
          .toList();
      final pendingTempDetails = _details
          .where((d) => ((d['id'] as num?)?.toInt() ?? 0) >= 1000000000000)
          .toList();

      for (var ts in pendingTempSaved) {
        if (!cleanSaved.any((s) => s['id'] == ts['id'])) {
          cleanSaved.add(ts);
        }
      }
      for (var td in pendingTempDetails) {
        if (!cleanDetails.any((d) => d['id'] == td['id'])) {
          cleanDetails.add(td);
        }
      }

      for (var cd in cleanDetails) {
        final existing = _details.firstWhere(
          (d) => d['id'] == cd['id'],
          orElse: () => {},
        );
        if (existing.isNotEmpty) {
          if (cd['incidentReport'] == null &&
              existing['incidentReport'] != null) {
            cd['incidentReport'] = existing['incidentReport'];
            cd['incidentTag'] = existing['incidentTag'];
            cd['incidentNote'] = existing['incidentNote'];
          }
        }
      }

      // Auto-recalculate day timelines on load ONLY for manual non-AI trips
      final bool isAiTrip =
          _itineraryData['isAiGenerated'] == true ||
          _itineraryData['isAiTrip'] == true ||
          (_itineraryData['title'] ?? '').toString().toLowerCase().contains(
            'ai',
          );

      cleanDetails.sort((a, b) {
        final dayA = (a['day'] as num?)?.toInt() ?? 1;
        final dayB = (b['day'] as num?)?.toInt() ?? 1;
        if (dayA != dayB) return dayA.compareTo(dayB);
        final ordA = (a['sortOrder'] as num?)?.toInt() ?? 0;
        final ordB = (b['sortOrder'] as num?)?.toInt() ?? 0;
        return ordA.compareTo(ordB);
      });
      _details = cleanDetails;
      _savedPlaces = cleanSaved;
      if (cleanDetails.any((detail) => detail.containsKey('isVisited'))) {
        _visitedDetailIds = cleanDetails
            .where((detail) => detail['isVisited'] == true)
            .map<int>((detail) => (detail['id'] as num).toInt())
            .toSet();
        await prefs.setStringList(
          'visited_details_$itineraryId',
          _visitedDetailIds.map((e) => e.toString()).toList(),
        );
      }
    }

    // Fetch places near destination for Explore and recommendations (only if not loaded)
    if (_allPlaces.isEmpty) {
      if (mounted) setState(() => _isLoadingPlaces = true);
      final String dest = _itineraryData['destination'] ?? '';
      final places = await DatabaseService().fetchPlacesByDestination(dest);

      // Extract user preferences from itinerary
      final List<dynamic> selectedCats = _itineraryData['categories'] is List
          ? _itineraryData['categories']
          : [];
      final List<dynamic> selectedAms = _itineraryData['amenities'] is List
          ? _itineraryData['amenities']
          : [];

      if (selectedCats.isNotEmpty || selectedAms.isNotEmpty) {
        // Sort places dynamically by matching user's selected categories & amenities
        places.sort((a, b) {
          int scoreA = 0;
          int scoreB = 0;

          final catA = (a['category']?['name'] ?? a['category'] ?? '')
              .toString();
          final catB = (b['category']?['name'] ?? b['category'] ?? '')
              .toString();

          for (var userCat in selectedCats) {
            final uCatStr = userCat.toString().toLowerCase();
            if (catA.toLowerCase().contains(uCatStr) ||
                uCatStr.contains(catA.toLowerCase()))
              scoreA += 5;
            if (catB.toLowerCase().contains(uCatStr) ||
                uCatStr.contains(catB.toLowerCase()))
              scoreB += 5;
          }

          final subCatA = (a['subCategories'] ?? []).toString().toLowerCase();
          final subCatB = (b['subCategories'] ?? []).toString().toLowerCase();
          for (var am in selectedAms) {
            final amStr = am.toString().toLowerCase();
            if (subCatA.contains(amStr)) scoreA += 3;
            if (subCatB.contains(amStr)) scoreB += 3;
          }

          if (scoreB != scoreA) return scoreB.compareTo(scoreA);

          final ratingA = (a['rating'] as num?)?.toDouble() ?? 0.0;
          final ratingB = (b['rating'] as num?)?.toDouble() ?? 0.0;
          return ratingB.compareTo(ratingA);
        });

        // Mark top matched places with dynamic preference tag
        for (var p in places) {
          final catP = (p['category']?['name'] ?? p['category'] ?? '')
              .toString();
          bool matchesCat = selectedCats.any(
            (c) =>
                catP.toLowerCase().contains(c.toString().toLowerCase()) ||
                c.toString().toLowerCase().contains(catP.toLowerCase()),
          );
          if (matchesCat) {
            p['isRecommendedForYou'] = true;
          }
        }
      }

      _allPlaces = places;
      _updateProminentPlaces();
      if (mounted) setState(() => _isLoadingPlaces = false);
    }

    _parseSectionsData();

    // Restore custom expenses and budget
    _tripBudget =
        prefs.getInt('budget_$itineraryId') ??
        (_itineraryData['budget'] as num?)?.toInt() ??
        0;
    final savedExpenses = prefs.getString('expenses_$itineraryId');
    if (savedExpenses != null) {
      try {
        _customExpenses = List<Map<String, dynamic>>.from(
          json.decode(savedExpenses),
        );
      } catch (e) {
        debugPrint('Error loading expenses: $e');
      }
    }

    final savedSettlements = prefs.getString('settlements_$itineraryId');
    if (savedSettlements != null) {
      try {
        _settlements = List<Map<String, dynamic>>.from(
          json.decode(savedSettlements),
        );
      } catch (e) {
        debugPrint('Error loading settlements: $e');
      }
    }

    final int currentItineraryId = (_itineraryData['id'] as num?)?.toInt() ?? 0;
    if (currentItineraryId > 0) {
      DatabaseService().getExpenses(currentItineraryId).then((serverExp) {
        if (mounted) {
          setState(() {
            _customExpenses = serverExp;
          });
          _saveExpensesToPrefs();
        }
      });

      DatabaseService().getSettlements(currentItineraryId).then((serverSt) {
        if (mounted) {
          setState(() {
            _settlements = serverSt;
          });
          _saveSettlementsToPrefs();
        }
      });

      DatabaseService().getCurrencyRates().then((rates) {
        if (mounted && rates.isNotEmpty) {
          setState(() {
            _currencyRates = rates;
          });
        }
      });
    }

    final daySubtitlesStr = prefs.getString('day_subtitles_$itineraryId');
    _daySubtitles.clear();
    if (daySubtitlesStr != null) {
      try {
        final Map<String, dynamic> parsed = json.decode(daySubtitlesStr);
        parsed.forEach((k, v) {
          _daySubtitles[int.parse(k)] = v as String;
        });
      } catch (e) {
        debugPrint('Error loading day subtitles: $e');
      }
    }

    final dayConfigs = _itineraryData['dayConfigs'] as Map<String, dynamic>?;
    _dayColors.clear();
    if (dayConfigs != null) {
      try {
        dayConfigs.forEach((k, v) {
          if (v is Map && v['color'] != null) {
            _dayColors[int.parse(k)] = _filterHarshColor(
              Color(int.parse(v['color'].toString())),
            );
          }
        });
      } catch (e) {
        debugPrint('Error loading day colors from dayConfigs: $e');
      }
    }

    final int numDays = (_itineraryData['days'] as num?)?.toInt() ?? 1;
    for (int i = 0; i < numDays; i++) {
      if (!_dayColors.containsKey(i) ||
          _dayColors[i] == const Color(0xFF40E0D0) ||
          _dayColors[i] == const Color(0xFF36E4C7) ||
          _dayColors[i] == const Color(0xFF64FFDA)) {
        _dayColors[i] = _filterHarshColor(
          _availableColors[i % _availableColors.length],
        );
      }
    }

    if (_searchCategories.isEmpty) {
      final categories = await DatabaseService().getCategories();
      if (mounted) {
        setState(() {
          _searchCategories = categories;
        });
      }
    }

    if (mounted) {
      setState(() {
        if (!silent) {
          _isLoading = false;
        }
      });
    }

    if (_privacySetting == 'public') {
      _syncPublicPostIfNeeded();
    }
  }

