  Future<void> _syncPublicPostIfNeeded() async {
    if (_privacySetting == 'public' && _itineraryData['id'] != null) {
      try {
        final itineraryId = _itineraryData['id'];
        final postData = _buildPostData();
        await ApiClient.post(
          '/explore/publish-itinerary/$itineraryId',
          body: postData,
        );
        if (mounted) {
          _fetchExplorePosts();
        }
      } catch (e) {
        debugPrint('Error syncing public post: $e');
      }
    }
  }

