  String _getDayLabel(int dayIndex) {
    final startStr = _itineraryData['startDate'] as String?;
    if (startStr == null) {
      return 'Ngày ${dayIndex + 1}';
    }
    final startDate = DateTime.tryParse(startStr);
    if (startDate == null) {
      return 'Ngày ${dayIndex + 1}';
    }
    final date = startDate.add(Duration(days: dayIndex));
    final weekday = date.weekday;
    String weekdayStr = '';
    switch (weekday) {
      case DateTime.monday:
        weekdayStr = 'T2';
        break;
      case DateTime.tuesday:
        weekdayStr = 'T3';
        break;
      case DateTime.wednesday:
        weekdayStr = 'T4';
        break;
      case DateTime.thursday:
        weekdayStr = 'T5';
        break;
      case DateTime.friday:
        weekdayStr = 'T6';
        break;
      case DateTime.saturday:
        weekdayStr = 'T7';
        break;
      case DateTime.sunday:
        weekdayStr = 'CN';
        break;
    }
    return '$weekdayStr ${date.day}/${date.month}';
  }

  Future<void> _insertDayAfter(int dayIndex) async {
    if (!_checkCanEdit()) return;
    final itineraryId = _itineraryData['id'] as int;
    final int targetDay = dayIndex + 1; // Insert after this day

    // Shift days in DB
    await DatabaseService().shiftItineraryDetailsDays(
      itineraryId: itineraryId,
      targetDay: targetDay,
      offset: 1,
    );

    // Update itinerary total days
    final currentDays = (_itineraryData['days'] as num?)?.toInt() ?? 1;
    await DatabaseService().updateItinerary(itineraryId, {
      'days': currentDays + 1,
    });
    await _loadData();
  }

  Future<void> _deleteDay(int dayIndex) async {
    if (!_checkCanEdit()) return;
    final itineraryId = _itineraryData['id'] as int;
    final int targetDay = dayIndex + 1;

    // Delete details belonging to targetDay
    await DatabaseService().deleteItineraryDetailsForDay(
      itineraryId: itineraryId,
      day: targetDay,
    );

    // Shift day numbers down for details after targetDay
    await DatabaseService().shiftItineraryDetailsDays(
      itineraryId: itineraryId,
      targetDay: targetDay,
      offset: -1,
    );

    // Update itinerary total days
    final currentDays = (_itineraryData['days'] as num?)?.toInt() ?? 1;
    if (currentDays > 1) {
      await DatabaseService().updateItinerary(itineraryId, {
        'days': currentDays - 1,
      });
    }
    await _loadData();
  }

  Future<void> _changeTripStartDate() async {
    final currentStartStr = _itineraryData['startDate'] as String?;
    final currentDays = (_itineraryData['days'] as num?)?.toInt() ?? 1;
    final currentStart = currentStartStr != null
        ? DateTime.tryParse(currentStartStr) ?? DateTime.now()
        : DateTime.now();

    final Set<int> completedDayIndexes = {};
    final Set<int> inProgressDayIndexes = {};
    for (int i = 0; i < currentDays; i++) {
      final dayDetails = _details.where((d) => d['day'] == (i + 1)).toList();
      if (dayDetails.isNotEmpty &&
          dayDetails.every((d) => _visitedDetailIds.contains(d['id']))) {
        completedDayIndexes.add(i);
      } else if (dayDetails.any((d) => _visitedDetailIds.contains(d['id']))) {
        inProgressDayIndexes.add(i);
      }
    }

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (context) {
        return TripDatePickerSheet(
          initialStartDate: currentStart,
          initialDays: currentDays,
          isReadOnly: true,
          completedDayIndexes: completedDayIndexes,
          inProgressDayIndexes: inProgressDayIndexes,
        );
      },
    );
  }

