    final txt = newValue.trim();
    setState(() {
      if (txt.isNotEmpty) {
        _daySubtitles[dayIndex] = txt;
      } else {
        _daySubtitles.remove(dayIndex);
      }
      _editingDaySubtitleIndex = null;
    });
    _saveDaySubtitles();
  }

