  // Add place to a section/day
  Future<void> _addPlace(
    Map<String, dynamic> place,
    String sectionOrDay,
  ) async {
    if (!_checkCanEdit()) return;
    _socketReloadTimer?.cancel();
    final itineraryId = _itineraryData['id'] as int;
    final placeId = place['id'] as int;
    dynamic result;

    // Check duplicate in the SAME section or day
    if (sectionOrDay.startsWith('Ngày') && _itineraryData['isGuide'] != true) {
      final int day =
          int.tryParse(sectionOrDay.replaceAll(RegExp(r'[^0-9]'), '')) ?? 1;
      final alreadyInDay = _details.any(
        (d) => d['day'] == day && d['placeId'] == placeId,
      );
      if (alreadyInDay) {
        _showPremiumNotification(
          title: 'Đã có trong ngày',
          message: '"${place['name']}" đã có trong $sectionOrDay!',
          icon: Icons.info_outline_rounded,
          color: Colors.orangeAccent,
        );
        return;
      }
    } else {
      final alreadyInSection = _savedPlaces.any(
        (sp) =>
            sp['section'] == sectionOrDay &&
            (sp['placeId'] == placeId ||
                (sp['place'] != null && sp['place']['id'] == placeId)),
      );
      if (alreadyInSection) {
        _showPremiumNotification(
          title: 'Đã có trong danh sách',
          message: '"${place['name']}" đã có trong danh sách "$sectionOrDay"!',
          icon: Icons.info_outline_rounded,
          color: Colors.orangeAccent,
        );
        return;
      }
    }

    final bool isDayItem =
        sectionOrDay.startsWith('Ngày') && _itineraryData['isGuide'] != true;
    String? calculatedStartTime;
    String? calculatedEndTime;
    String? shrunkId;
    String? shrunkEndTime;
    if (isDayItem) {
      final int day =
          int.tryParse(sectionOrDay.replaceAll(RegExp(r'[^0-9]'), '')) ?? 1;
      final existingDayPlaces = _details
          .where((d) => d['day'] == day && d['place'] != null)
          .toList();

      existingDayPlaces.sort((a, b) {
        final aStart = a['startTime']?.toString() ?? '';
        final bStart = b['startTime']?.toString() ?? '';
        final aHasTime = aStart.isNotEmpty;
        final bHasTime = bStart.isNotEmpty;

        if (aHasTime && !bHasTime) {
          return -1;
        } else if (!aHasTime && bHasTime) {
          return 1;
        } else if (aHasTime && bHasTime) {
          final aStartVal = _getSortableTimeValue(aStart);
          final bStartVal = _getSortableTimeValue(bStart);
          if (aStartVal != bStartVal) {
            return aStartVal.compareTo(bStartVal);
          }
        }
        final aOrd = (a['sortOrder'] as num?)?.toInt() ?? 0;
        final bOrd = (b['sortOrder'] as num?)?.toInt() ?? 0;
        return aOrd.compareTo(bOrd);
      });

      final calculated = _calculatePlaceTimeGaps(
        place: place,
        existingDayPlaces: existingDayPlaces,
      );
      calculatedStartTime = calculated['startTime'];
      calculatedEndTime = calculated['endTime'];
      shrunkId = calculated['shrunkId'];
      shrunkEndTime = calculated['shrunkEndTime'];
    }
    final int? affectedDay = sectionOrDay.startsWith('Ngày')
        ? (int.tryParse(sectionOrDay.replaceAll(RegExp(r'[^0-9]'), '')) ?? 1)
        : null;

    int maxOrder = 0;
    if (affectedDay != null) {
      final dayDetails = _details
          .where((d) => d['day'] == affectedDay)
          .toList();
      for (final d in dayDetails) {
        final ord = (d['sortOrder'] as num?)?.toInt() ?? 0;
        if (ord > maxOrder) maxOrder = ord;
      }
    }
    final int nextSortOrder = maxOrder + 1;

    final Map<String, dynamic> tempItem = {
      'id': DateTime.now().millisecondsSinceEpoch,
      'itineraryId': itineraryId,
      'placeId': placeId,
      'place': place,
      'section': sectionOrDay,
      'day': affectedDay,
      'startTime': calculatedStartTime,
      'endTime': calculatedEndTime,
      'sortOrder': nextSortOrder,
    };

    setState(() {
      if (shrunkId != null && shrunkEndTime != null) {
        final sid = int.tryParse(shrunkId!);
        if (sid != null) {
          final idx = _details.indexWhere((d) => d['id'] == sid);
          if (idx != -1) {
            _details[idx]['endTime'] = shrunkEndTime;
          }
        }
      }
      if (affectedDay != null && _itineraryData['isGuide'] != true) {
        _details.add(tempItem);
        final dayItems = _details
            .where((d) => d['day'] == affectedDay)
            .toList();
        final optimized = _optimizeDayTimeSlots(dayItems);
        for (final item in optimized) {
          final idx = _details.indexWhere((d) => d['id'] == item['id']);
          if (idx != -1) {
            _details[idx]['startTime'] = item['startTime'];
            _details[idx]['endTime'] = item['endTime'];
            _details[idx]['sortOrder'] = item['sortOrder'];
          }
        }
        final optimizedTempItem = optimized.firstWhere(
          (item) => item['id'] == tempItem['id'],
          orElse: () => tempItem,
        );
        calculatedStartTime = optimizedTempItem['startTime'];
        calculatedEndTime = optimizedTempItem['endTime'];
      } else {
        _savedPlaces.add(tempItem);
      }
    });

    _showPremiumNotification(
      title: 'Thêm thành công',
      message: 'Đã thêm "${place['name']}" vào $sectionOrDay!',
      icon: Icons.check_circle_outline_rounded,
      color: AppTheme.green,
    );

    if (affectedDay != null && _itineraryData['isGuide'] != true) {
      if (shrunkId != null && shrunkEndTime != null) {
        final sid = int.tryParse(shrunkId!);
        if (sid != null) {
          DatabaseService().updateItineraryDetail(sid, {
            'endTime': shrunkEndTime,
          });
        }
      }

      result = await DatabaseService().addPlaceToItinerary(
        itineraryId: itineraryId,
        placeId: placeId,
        day: affectedDay,
        startTime: calculatedStartTime,
        endTime: calculatedEndTime,
        sortOrder: tempItem['sortOrder'] ?? nextSortOrder,
      );

      final dayItems = _details
          .where((d) => d['day'] == affectedDay && d['id'] != tempItem['id'])
          .toList();
      final List<Future<bool>> futures = [];
      for (final item in dayItems) {
        final itemId = item['id'] as int;
        futures.add(
          DatabaseService().updateItineraryDetail(itemId, {
            'startTime': item['startTime'],
            'endTime': item['endTime'],
            'sortOrder': item['sortOrder'],
          }),
        );
      }
      Future.wait(futures).catchError((e) => <bool>[]);
    } else {
      result = await DatabaseService().addPlaceToSaved(
        itineraryId: itineraryId,
        placeId: placeId,
        section: sectionOrDay,
      );
    }

    if (result != null && result['id'] != null) {
      final Map<String, dynamic> updatedItem = Map<String, dynamic>.from(
        result is Map ? result : {},
      );
      if (updatedItem['place'] == null) {
        updatedItem['place'] = place;
      }
      setState(() {
        if (affectedDay != null && _itineraryData['isGuide'] != true) {
          final idx = _details.indexWhere((d) => d['id'] == tempItem['id']);
          if (idx != -1) {
            final oldItem = _details[idx];
            _details[idx] = {
              ...oldItem,
              ...updatedItem,
              'startTime': updatedItem['startTime'] ?? oldItem['startTime'],
              'endTime': updatedItem['endTime'] ?? oldItem['endTime'],
              'sortOrder':
                  (oldItem['sortOrder'] != null &&
                      (oldItem['sortOrder'] as num) > 0)
                  ? oldItem['sortOrder']
                  : (updatedItem['sortOrder'] ?? nextSortOrder),
            };
          }
        } else {
          final idx = _savedPlaces.indexWhere(
            (sp) => sp['id'] == tempItem['id'],
          );
          if (idx != -1) {
            _savedPlaces[idx] = {
              ...tempItem,
              ...updatedItem,
              'section':
                  updatedItem['section'] ?? tempItem['section'] ?? sectionOrDay,
              'place': updatedItem['place'] ?? place,
            };
          }
        }
      });
    }
  }

  Future<void> _removePlaceDetail(
    int detailId,
    String placeName, {
    bool isSavedPlace = false,
  }) async {
    if (!_checkCanEdit()) return;
    if (_visitedDetailIds.contains(detailId)) {
      _showPremiumNotification(
        title: 'Địa điểm đã ghé thăm',
        message: 'Không thể xóa địa điểm đã hoàn thành!',
        icon: Icons.lock_rounded,
        color: Colors.orange,
      );
      return;
    }
    if (_deletingDetailIds.contains(detailId)) return;
    _deletingDetailIds.add(detailId);

    final bool inSaved = _savedPlaces.any((p) => p['id'] == detailId);
    final bool inDetails = _details.any((d) => d['id'] == detailId);

    final targetSavedItem = _savedPlaces.firstWhere(
      (p) => p['id'] == detailId,
      orElse: () => {},
    );
    final targetDetailItem = _details.firstWhere(
      (d) => d['id'] == detailId,
      orElse: () => {},
    );
    final dynamic targetPlaceId =
        targetSavedItem['placeId'] ??
        targetSavedItem['place']?['id'] ??
        targetDetailItem['placeId'] ??
        targetDetailItem['place']?['id'];

    int? affectedDay;
    final itemToRemove = _details.firstWhere(
      (d) => d['id'] == detailId,
      orElse: () => {},
    );
    if (itemToRemove.isNotEmpty && itemToRemove['day'] != null) {
      affectedDay = (itemToRemove['day'] as num).toInt();
    }

    // OPTIMISTIC DELETE: Xóa khỏi giao diện ngay lập tức ở cả 2 danh sách (0ms)
    setState(() {
      _savedPlaces.removeWhere((p) {
        final idMatches = p['id'] == detailId;
        final pIdMatches =
            targetPlaceId != null &&
            (p['placeId'] == targetPlaceId ||
                p['place']?['id'] == targetPlaceId);
        return idMatches || pIdMatches;
      });

      _details.removeWhere((d) {
        final idMatches = d['id'] == detailId;
        final pIdMatches =
            targetPlaceId != null &&
            (d['placeId'] == targetPlaceId ||
                d['place']?['id'] == targetPlaceId);
        return idMatches || pIdMatches;
      });

      _itineraryData['savedPlaces'] = _savedPlaces;
      _itineraryData['details'] = _details;
      if (widget.itinerary != null) {
        widget.itinerary['savedPlaces'] = _savedPlaces;
        widget.itinerary['details'] = _details;
      }

      if (affectedDay != null) {
        final dayItems = _details
            .where((d) => d['day'] == affectedDay)
            .toList();
        if (dayItems.isNotEmpty) {
          final optimized = _optimizeDayTimeSlots(dayItems);
          for (final item in optimized) {
            final idx = _details.indexWhere((d) => d['id'] == item['id']);
            if (idx != -1) {
              _details[idx]['startTime'] = item['startTime'];
              _details[idx]['endTime'] = item['endTime'];
              _details[idx]['sortOrder'] = item['sortOrder'];
            }
          }
        }
      }
    });

    // Gom thông báo xóa bằng Debounce Timer để không sinh ra hàng loạt Overlay gây giật lag
    _deletedCountInBatch++;
    _deleteNotificationTimer?.cancel();
    _deleteNotificationTimer = Timer(const Duration(milliseconds: 350), () {
      if (!mounted) return;
      final msg = _deletedCountInBatch == 1
          ? 'Đã xóa "$placeName" khỏi lịch trình và tự động cập nhật thời gian.'
          : 'Đã xóa $_deletedCountInBatch mục và tự động cập nhật thời gian.';
      _deletedCountInBatch = 0;
      _showPremiumNotification(
        title: 'Đã xóa & cập nhật thời gian',
        message: msg,
        icon: Icons.delete_sweep_outlined,
        color: Colors.redAccent,
      );
    });

    // Xóa ngầm ở DatabaseService không làm nghẽn Event Loop
    Future.microtask(() async {
      try {
        if (inSaved || isSavedPlace) {
          await DatabaseService().deletePlaceFromSaved(detailId);
        }
        if (inDetails || (!inSaved && !isSavedPlace)) {
          await DatabaseService().deletePlaceFromItinerary(detailId);
          if (affectedDay != null) {
            final dayItems = _details
                .where((d) => d['day'] == affectedDay)
                .toList();
            for (final item in dayItems) {
              if (item['id'] != null) {
                await DatabaseService()
                    .updateItineraryDetail(item['id'] as int, {
                      'startTime': item['startTime'],
                      'endTime': item['endTime'],
                      'sortOrder': item['sortOrder'],
                    });
              }
            }
          }
        }
      } catch (_) {
      } finally {
        Timer(const Duration(seconds: 3), () {
          _deletingDetailIds.remove(detailId);
        });
      }
    });
  }

  // Local place search within destination
  void _onSearchChanged(String query, String sectionName) {
    if (query.trim().isEmpty) {
      setState(() {
        _searchResults[sectionName] = [];
      });
      return;
    }

    final filtered = _allPlaces.where((place) {
      final name = (place['name'] as String).toLowerCase();
      final addr = (place['address'] as String).toLowerCase();
      final q = query.toLowerCase();
      return name.contains(q) || addr.contains(q);
    }).toList();

    setState(() {
      _searchResults[sectionName] = filtered;
    });
  }

