  void _showDeleteTripDialog() {
    final bool isGuide = _itineraryData['isGuide'] == true;
    final String label = isGuide ? 'hướng dẫn' : 'chuyến đi';

    if (_currentRole != 'OWNER') {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              'Chỉ chủ sở hữu (OWNER) mới có quyền xóa $label này.',
            ),
            duration: const Duration(seconds: 2),
            behavior: SnackBarBehavior.floating,
          ),
        );
      }
      return;
    }

    showDialog(
      context: context,
      builder: (BuildContext dialogContext) {
        return AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: Row(
            children: [
              const Icon(
                Icons.warning_amber_rounded,
                color: Colors.redAccent,
                size: 24,
              ),
              const SizedBox(width: 8),
              Text('Xóa $label'),
            ],
          ),
          content: Text(
            'Bạn có chắc chắn muốn xóa $label này không? Tất cả dữ liệu của $label sẽ bị xóa vĩnh viễn và không thể hoàn tác.',
            style: const TextStyle(fontSize: 14, height: 1.4),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(),
              child: const Text(
                'Hủy',
                style: TextStyle(
                  color: Colors.grey,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.redAccent,
                foregroundColor: Colors.white,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(8),
                ),
              ),
              onPressed: () async {
                Navigator.of(dialogContext).pop();

                final int itineraryId = _itineraryData['id'] is int
                    ? _itineraryData['id'] as int
                    : int.parse(_itineraryData['id'].toString());

                showDialog(
                  context: context,
                  barrierDismissible: false,
                  builder: (ctx) => const Center(
                    child: CircularProgressIndicator(color: AppTheme.primary),
                  ),
                );

                final success = await DatabaseService().deleteItinerary(
                  itineraryId,
                );

                if (mounted) {
                  Navigator.of(context).pop();
                  if (success) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text('Đã xóa $label thành công.'),
                        duration: const Duration(seconds: 2),
                        behavior: SnackBarBehavior.floating,
                      ),
                    );
                    Navigator.of(context).pop(true);
                  } else {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text(
                          'Không thể xóa $label. Vui lòng thử lại.',
                        ),
                        duration: const Duration(seconds: 2),
                        behavior: SnackBarBehavior.floating,
                      ),
                    );
                  }
                }
              },
              child: const Text(
                'Xóa',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
            ),
          ],
        );
      },
    );
  }

  Widget _buildSettingTile(IconData icon, String title, {VoidCallback? onTap}) {
    return ListTile(
      leading: Icon(icon, color: AppTheme.darkText),
      title: Text(title, style: TextStyle(color: AppTheme.darkText)),
      onTap: () {
        Navigator.pop(context);
        if (onTap != null) {
          Future.delayed(const Duration(milliseconds: 250), () {
            if (mounted) onTap();
          });
        }
      },
    );
  }

  void _showPrivacySettingsSheet() {
    final bool isGuide = _itineraryData['isGuide'] == true;
    if (_currentRole != 'OWNER') {
      if (mounted) {
        final String label = isGuide ? 'hướng dẫn' : 'chuyến đi';
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              'Chỉ chủ sở hữu (OWNER) mới có quyền cài đặt quyền riêng tư cho $label này.',
            ),
            duration: const Duration(seconds: 2),
            behavior: SnackBarBehavior.floating,
          ),
        );
      }
      return;
    }
    showModalBottomSheet(
      context: context,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (context) {
        return SafeArea(
          child: StatefulBuilder(
            builder: (context, setSheetState) {
              Widget buildPrivacyOption(
                String title,
                String subtitle,
                IconData icon,
                String value,
              ) {
                return ListTile(
                  leading: Icon(icon, color: AppTheme.darkText),
                  title: Text(
                    title,
                    style: TextStyle(
                      color: AppTheme.darkText,
                      fontWeight: FontWeight.w500,
                    ),
                  ),
                  subtitle: Text(
                    subtitle,
                    style: TextStyle(
                      color: AppTheme.subtitleText,
                      fontSize: 12,
                    ),
                  ),
                  trailing: _privacySetting == value
                      ? Icon(Icons.check, color: AppTheme.darkText)
                      : null,
                  onTap: () async {
                    setSheetState(() => _privacySetting = value);
                    setState(() => _privacySetting = value);
                    final prefs = await SharedPreferences.getInstance();
                    final itineraryId = _itineraryData['id'];
                    await prefs.setString('privacy_$itineraryId', value);

                    if (itineraryId != null) {
                      try {
                        await ApiClient.put(
                          '/itineraries/$itineraryId',
                          body: {'companion': value},
                        );
                      } catch (e) {
                        debugPrint('Error updating companion in backend: $e');
                      }

                      if (value == 'public' && isGuide) {
                        try {
                          final postData = _buildPostData();
                          await ApiClient.post(
                            '/explore/publish-itinerary/$itineraryId',
                            body: postData,
                          );
                        } catch (_) {}
                      } else {
                        try {
                          await ApiClient.post(
                            '/explore/unpublish-itinerary/$itineraryId',
                          );
                        } catch (_) {}
                      }
                    }

                    if (mounted) {
                      _fetchExplorePosts();
                      Navigator.pop(context);
                    }
                  },
                );
              }

              return Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  const SizedBox(height: 12),
                  Container(
                    width: 40,
                    height: 4,
                    decoration: BoxDecoration(
                      color: Colors.grey.shade300,
                      borderRadius: BorderRadius.circular(2),
                    ),
                  ),
                  const SizedBox(height: 16),
                  Row(
                    children: [
                      IconButton(
                        icon: Icon(Icons.arrow_back, color: AppTheme.darkText),
                        onPressed: () => Navigator.pop(context),
                      ),
                      Expanded(
                        child: Text(
                          'Cài đặt quyền riêng tư',
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            fontSize: 18,
                            fontWeight: FontWeight.bold,
                            color: AppTheme.darkText,
                          ),
                        ),
                      ),
                      const SizedBox(width: 48),
                    ],
                  ),
                  const SizedBox(height: 16),
                  if (isGuide) ...[
                    buildPrivacyOption(
                      'Công khai',
                      'Đăng bài lên Khám phá cho mọi người cùng xem',
                      Icons.public,
                      'public',
                    ),
                    buildPrivacyOption(
                      'Thành viên',
                      'Chỉ bạn và những người đồng tác giả được mời',
                      Icons.group,
                      'members',
                    ),
                    buildPrivacyOption(
                      'Riêng tư',
                      'Lưu nháp, chỉ mình bạn có quyền xem',
                      Icons.lock,
                      'private',
                    ),
                  ] else ...[
                    buildPrivacyOption(
                      'Riêng tư',
                      'Chỉ bạn mới có quyền xem hành trình này',
                      Icons.lock,
                      'private',
                    ),
                    buildPrivacyOption(
                      'Thành viên',
                      'Chỉ bạn và những người được mời trong chuyến đi',
                      Icons.group,
                      'members',
                    ),
                  ],
                  const SizedBox(height: 24),
                ],
              );
            },
          ),
        );
      },
    );
  }

  IconData _getPrivacyIcon() {
    switch (_privacySetting) {
      case 'public':
        return Icons.public;
      case 'members':
        return Icons.group;
      case 'private':
      default:
        return Icons.lock;
    }
  }

  void _showEditTitleDialog() {
    if (!_checkCanEdit()) return;
    final TextEditingController titleController = TextEditingController(
      text: _itineraryData['title'] as String? ?? '',
    );

    showDialog(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: const Text(
            'Chỉnh sửa tiêu đề',
            style: TextStyle(fontWeight: FontWeight.bold),
          ),
          content: TextField(
            controller: titleController,
            decoration: const InputDecoration(
              hintText: 'Nhập tiêu đề mới',
              border: OutlineInputBorder(),
              contentPadding: EdgeInsets.symmetric(
                horizontal: 16,
                vertical: 12,
              ),
            ),
            autofocus: true,
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: Text(
                'Hủy',
                style: TextStyle(color: AppTheme.subtitleText),
              ),
            ),
            ElevatedButton(
              onPressed: () async {
                final newTitle = titleController.text.trim();
                if (newTitle.isNotEmpty &&
                    newTitle != _itineraryData['title']) {
                  setState(() {
                    _itineraryData['title'] = newTitle;
                  });
                  final itineraryId = _itineraryData['id'] as int?;
                  if (itineraryId != null) {
                    try {
                      await DatabaseService().updateItinerary(itineraryId, {
                        'title': newTitle,
                      });
                    } catch (e) {
                      debugPrint('Error updating title: $e');
                    }
                  }
                }
                if (mounted) Navigator.pop(dialogContext);
              },
              style: ElevatedButton.styleFrom(
                backgroundColor: AppTheme.primary,
                foregroundColor: Colors.white,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(8),
                ),
              ),
              child: const Text('Lưu'),
            ),
          ],
        );
      },
    );
  }

  void _showSearchOverlay() {
    List<Map<String, dynamic>> overlaySearchResults = [];
    bool isSearching = false;
    String currentQuery = '';
    Timer? debounce;
    final dest = _itineraryData['destination'] ?? '';

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (context) => StatefulBuilder(
        builder: (context, setStateOverlay) {
          return SizedBox(
            height: MediaQuery.of(context).size.height * 0.9,
            child: Padding(
              padding: const EdgeInsets.all(16.0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: TextField(
                          onChanged: (val) {
                            setStateOverlay(() {
                              currentQuery = val;
                            });
                            if (debounce?.isActive ?? false) debounce!.cancel();
                            debounce = Timer(
                              const Duration(milliseconds: 500),
                              () async {
                                if (val.isEmpty) {
                                  setStateOverlay(() {
                                    overlaySearchResults = [];
                                    isSearching = false;
                                  });
                                  return;
                                }
                                setStateOverlay(() {
                                  isSearching = true;
                                });
                                final results = await DatabaseService()
                                    .searchPlaces(
                                      destination: dest,
                                      query: val,
                                    );
                                setStateOverlay(() {
                                  overlaySearchResults = results;
                                  isSearching = false;
                                });
                              },
                            );
                          },
                          decoration: InputDecoration(
                            hintText: 'Tìm kiếm theo tên hoặc địa chỉ',
                            prefixIcon: const Icon(Icons.search_rounded),
                            filled: true,
                            fillColor: Colors.grey.shade100,
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(12),
                              borderSide: BorderSide.none,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 12),
                      IconButton(
                        icon: const Icon(Icons.close_rounded),
                        onPressed: () => Navigator.pop(context),
                      ),
                    ],
                  ),
                  const SizedBox(height: 24),
                  if (isSearching)
                    const Center(child: CircularProgressIndicator())
                  else if (currentQuery.isNotEmpty)
                    Expanded(
                      child: ListView.builder(
                        itemCount: overlaySearchResults.length + 1,
                        itemBuilder: (context, index) {
                          if (index == 0) {
                            return ListTile(
                              leading: const Icon(Icons.search_rounded),
                              title: Text(
                                'Tìm kiếm: $currentQuery',
                                style: const TextStyle(
                                  fontWeight: FontWeight.bold,
                                ),
                              ),
                              subtitle: const Text('Xem kết quả trên bản đồ'),
                              onTap: () async {
                                final query = currentQuery;
                                Navigator.pop(context);
                                setState(() {
                                  _activeSearchQuery = query;
                                  _isMapExpanded = true;
                                  _isSheetHalf = false;
                                });

                                final results = await DatabaseService()
                                    .searchPlaces(
                                      destination: dest,
                                      query: query,
                                    );

                                setState(() {
                                  _filteredMapPlaces = results;
                                  if (results.isNotEmpty) {
                                    final lat =
                                        (results.first['latitude'] as num)
                                            .toDouble();
                                    final lon =
                                        (results.first['longitude'] as num)
                                            .toDouble();
                                    _mapController.move(LatLng(lat, lon), 13.0);
                                    _selectedMapPlace = results.first;
                                  }
                                });
                              },
                            );
                          }

                          final place = overlaySearchResults[index - 1];
                          return ListTile(
                            leading: const Icon(Icons.place_rounded),
                            title: Text(place['name'] ?? ''),
                            subtitle: Text(
                              place['address'] ?? '',
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                            ),
                            onTap: () {
                              setState(() {
                                _activeSearchQuery = place['name'];
                                _filteredMapPlaces = [place];
                                _isMapExpanded = true;
                                _isSheetHalf = false;
                                if (place['latitude'] != null &&
                                    place['longitude'] != null) {
                                  _mapController.move(
                                    LatLng(
                                      (place['latitude'] as num).toDouble(),
                                      (place['longitude'] as num).toDouble(),
                                    ),
                                    15.0,
                                  );
                                }
                              });
                              Navigator.pop(context);
                            },
                          );
                        },
                      ),
                    )
                  else ...[
                    const Text(
                      'Tìm kiếm thường xuyên',
                      style: TextStyle(
                        fontWeight: FontWeight.bold,
                        fontSize: 16,
                      ),
                    ),
                    const SizedBox(height: 16),
                    if (_searchCategories.isEmpty)
                      const Center(child: CircularProgressIndicator())
                    else
                      Expanded(
                        child: ListView.builder(
                          itemCount: _searchCategories.length,
                          itemBuilder: (context, index) {
                            final category = _searchCategories[index];
                            final iconCode = category['iconCode'] as int?;
                            IconData iconData = Icons.category_rounded;

                            if (iconCode != null) {
                              iconData = IconData(
                                iconCode,
                                fontFamily: 'MaterialIcons',
                              );
                            } else {
                              final iconString = category['icon'] as String?;
                              if (iconString != null && iconString.isNotEmpty) {
                                try {
                                  if (iconString.startsWith('0x')) {
                                    iconData = IconData(
                                      int.parse(iconString),
                                      fontFamily: 'MaterialIcons',
                                    );
                                  }
                                } catch (_) {}
                              }
                            }

                            return _buildSearchCategory(
                              iconData,
                              category['name'] ?? '',
                            );
                          },
                        ),
                      ),
                  ],
                ],
              ),
            ),
          );
        },
      ),
    );
  }

  Widget _buildSearchCategory(IconData icon, String title) {
    return ListTile(
      leading: Icon(icon),
      title: Text(title),
      onTap: () async {
        Navigator.pop(context);
        setState(() {
          _activeSearchQuery = title;
          _isMapExpanded = true;
          _isSheetHalf = false;
        });

        final dest = _itineraryData['destination'] ?? '';
        final results = await DatabaseService().searchPlaces(
          destination: dest,
          categoryName: title,
        );

        setState(() {
          _filteredMapPlaces = results;
          if (results.isNotEmpty) {
            final lat = (results.first['latitude'] as num).toDouble();
            final lon = (results.first['longitude'] as num).toDouble();
            _mapController.move(LatLng(lat, lon), 13.0);
            _selectedMapPlace = results.first;
          }
        });
      },
    );
  }

  void _showLayersSheet() {
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (context) => StatefulBuilder(
        builder: (context, setSheetState) => SafeArea(
          child: SingleChildScrollView(
            child: Padding(
              padding: const EdgeInsets.all(20),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Center(
                    child: Container(
                      width: 40,
                      height: 4,
                      margin: const EdgeInsets.only(bottom: 20),
                      decoration: BoxDecoration(
                        color: Colors.grey.shade300,
                        borderRadius: BorderRadius.circular(2),
                      ),
                    ),
                  ),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      const Text(
                        'Khám phá khu vực',
                        style: TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 16),
                  SizedBox(
                    height: 100,
                    child: _searchCategories.isEmpty
                        ? const Center(
                            child: Text(
                              'Không có dữ liệu',
                              style: TextStyle(color: Colors.grey),
                            ),
                          )
                        : ListView.builder(
                            scrollDirection: Axis.horizontal,
                            itemCount: _searchCategories.length,
                            itemBuilder: (context, index) {
                              final cat = _searchCategories[index];
                              return GestureDetector(
                                onTap: () async {
                                  Navigator.pop(context);
                                  setState(() {
                                    _activeSearchQuery = cat['name'];
                                    _isMapExpanded = true;
                                    _isSheetHalf = false;
                                  });
                                  final dest =
                                      _itineraryData['destination'] ?? '';
                                  final results = await DatabaseService()
                                      .searchPlaces(
                                        destination: dest,
                                        categoryName: cat['name'],
                                      );
                                  setState(() {
                                    _filteredMapPlaces = results;
                                    if (results.isNotEmpty) {
                                      final lat =
                                          (results.first['latitude'] as num)
                                              .toDouble();
                                      final lon =
                                          (results.first['longitude'] as num)
                                              .toDouble();
                                      _mapController.move(
                                        LatLng(lat, lon),
                                        13.0,
                                      );
                                      _selectedMapPlace = results.first;
                                    }
                                  });
                                },
                                child: Container(
                                  width: 80,
                                  margin: const EdgeInsets.only(right: 12),
                                  child: Column(
                                    children: [
                                      CircleAvatar(
                                        radius: 28,
                                        backgroundColor: Colors.grey.shade100,
                                        child: Icon(
                                          IconData(
                                            cat['iconCode'] ??
                                                Icons.place.codePoint,
                                            fontFamily: 'MaterialIcons',
                                          ),
                                          color: AppTheme.subtitleText,
                                        ),
                                      ),
                                      const SizedBox(height: 8),
                                      Text(
                                        cat['name'] ?? '',
                                        textAlign: TextAlign.center,
                                        style: TextStyle(
                                          fontSize: 12,
                                          color: AppTheme.subtitleText,
                                        ),
                                        maxLines: 2,
                                        overflow: TextOverflow.ellipsis,
                                      ),
                                    ],
                                  ),
                                ),
                              );
                            },
                          ),
                  ),
                  const SizedBox(height: 8),
                  const Divider(),
                  const SizedBox(height: 4),
                  const Padding(
                    padding: EdgeInsets.only(top: 4, bottom: 4),
                    child: Align(
                      alignment: Alignment.centerLeft,
                      child: Text(
                        'Hành trình',
                        style: TextStyle(color: Colors.grey),
                      ),
                    ),
                  ),
                  if (_checkedDays != null)
                    ...List.generate((_itineraryData['days'] as int?) ?? 1, (
                      index,
                    ) {
                      final day = index + 1;
                      final color = _dayColors[day - 1] ?? AppTheme.primary;
                      return CheckboxListTile(
                        secondary: Icon(Icons.location_on, color: color),
                        title: Text(
                          'Ngày $day',
                          style: TextStyle(
                            color: AppTheme.darkText,
                            fontWeight: FontWeight.w500,
                          ),
                        ),
                        value: _checkedDays!.contains(day),
                        activeColor: AppTheme.primary,
                        contentPadding: EdgeInsets.zero,
                        controlAffinity: ListTileControlAffinity.trailing,
                        visualDensity: VisualDensity.compact,
                        onChanged: (val) {
                          setSheetState(() {
                            if (val == true) {
                              _checkedDays!.add(day);
                            } else {
                              _checkedDays!.remove(day);
                            }
                          });
                          setState(() {});
                        },
                      );
                    }),
                ],
              ),
            ),
          ),
        ),
      ),
    ).then((_) {
      final int numDays = (_itineraryData['days'] as int?) ?? 1;
      final bool hasFilter =
          (_checkedSections != null &&
              _checkedSections!.length < _sectionNames.length) ||
          (_checkedDays != null && _checkedDays!.length < numDays);
      if (hasFilter && mounted) {
        setState(() {
          _isMapExpanded = true;
          _isSheetHalf = false;
        });
      }
    });
  }

  Widget _buildExploreIcon(IconData icon, String label) {
    return Column(
      children: [
        CircleAvatar(
          radius: 24,
