  Future<void> _goToMyLocation() async {
    bool serviceEnabled;
    LocationPermission permission;

    serviceEnabled = await Geolocator.isLocationServiceEnabled();
    if (!serviceEnabled) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Dịch vụ định vị đã bị tắt.')),
        );
      }
      return;
    }

    permission = await Geolocator.checkPermission();
    if (permission == LocationPermission.denied) {
      permission = await Geolocator.requestPermission();
      if (permission == LocationPermission.denied) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('Quyền truy cập vị trí bị từ chối.')),
          );
        }
        return;
      }
    }

    if (permission == LocationPermission.deniedForever) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Quyền bị từ chối vĩnh viễn, hãy bật trong cài đặt.'),
          ),
        );
      }
      return;
    }

    try {
      Position position = await Geolocator.getCurrentPosition(
        desiredAccuracy: LocationAccuracy.high,
      );
      if (mounted) {
        setState(() {
          _currentLocation = LatLng(position.latitude, position.longitude);
        });
        _mapController.move(
          LatLng(position.latitude, position.longitude),
          15.0,
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Lỗi khi lấy vị trí: $e')));
      }
    }
  }

  Map<String, dynamic> _buildPostData() {
    final List<Map<String, dynamic>> items = [];

    final List<Map<String, dynamic>> sectionsList = [];
    for (final section in _sectionNames) {
      final color =
          _sectionColors[section]?.toARGB32() ?? AppTheme.primary.toARGB32();
      final icon =
          _sectionIcons[section]?.codePoint ??
          Icons.looks_one_rounded.codePoint;
      sectionsList.add({
        'name': section,
        'colorCode': color.toString(),
        'iconCode': icon,
      });

      items.add({
        'itemType': 'SECTION_HEADER',
        'content': section,
        'section': section,
        'colorCode': color.toString(),
        'iconCode': icon,
      });

      final sectionDetails = _savedPlaces
          .where((d) => d['section'] == section)
          .toList();
      sectionDetails.sort(
        (a, b) => (a['sortOrder'] ?? 0).compareTo(b['sortOrder'] ?? 0),
      );

      for (final detail in sectionDetails) {
        if (detail['place'] != null) {
          final place = detail['place'];
          String content = detail['content'] ?? '';
          if (content.trim().isEmpty && place['description'] != null) {
            content = place['description'];
          }
          items.add({
            'itemType': 'PLACE',
            'placeId': place['id'],
            'place': {
              ...place,
              'section': section,
              'colorCode': color.toString(),
              'iconCode': icon,
            },
            'content': content,
            'section': section,
            'colorCode': color.toString(),
            'iconCode': icon,
          });
        } else if (detail['noteText'] != null) {
          final String text = detail['noteText'] ?? detail['notetext'] ?? '';
          final bool isTodo = text.startsWith('[TODO]');
          if (isTodo) {
            items.add({
              'itemType': 'TODO',
              'section': section,
              'content': jsonEncode({
                'title': text.replaceFirst('[TODO]', '').trim(),
                'items': detail['todoItems'] ?? detail['todoitems'] ?? [],
              }),
            });
          } else {
            items.add({
              'itemType': 'NOTE',
              'section': section,
              'content': text,
            });
          }
        }
      }
    }

    _itineraryData['sections'] = sectionsList;

    return {
      'title': _itineraryData['title'] ?? 'Hướng dẫn của tôi',
      'description': _itineraryData['description'] ?? '',
      'destination': _itineraryData['destination'] ?? '',
      'coverImage': _itineraryData['coverImage'] ?? null,
      'postType': 'USER_CURATION',
      'sections': sectionsList,
      'items': items,
    };
  }

  void _previewGuide() {
    final user = AuthService().currentUser.value;
    final postData = _buildPostData();

    final mockPost = {
      ...postData,
      'id': _itineraryData['id'] ?? 'preview',
      'author': {
        'fullName': user?.fullName ?? 'Người dùng',
        'avatar': user?.avatar ?? 'https://via.placeholder.com/150',
      },
    };

    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => ExplorePostDetailScreen(
          post: mockPost,
          title: mockPost['title'] as String,
          initialItinerary: _itineraryData,
        ),
      ),
    );
  }

  bool _isSightseeingPlace(Map<String, dynamic> place) {
    final categoryName = (place['category']?['name'] ?? place['category'] ?? '')
        .toString()
        .toLowerCase();
    final placeName = (place['name'] ?? '').toString().toLowerCase();
    final subCategories = (place['subCategories'] as List? ?? [])
        .map((e) => e.toString().toLowerCase())
        .join(' ');

    final combined = '$categoryName $placeName $subCategories';
    final excluded = [
      'spa',
      'massage',
      'quán',
      'ăn',
      'uống',
      'nhà hàng',
      'cà phê',
      'cafe',
      'bình dân',
      'ẩm thực',
      'food',
      'restaurant',
      'dining',
      'bar',
      'pub',
      'tiệm',
      'bánh',
      'trà sữa',
      'búp phê',
      'buffet',
      'lẩu',
      'nướng',
      'gà rán',
    ];

    for (final word in excluded) {
      if (combined.contains(word)) {
        return false;
      }
    }
    return true;
  }

