  @override
  Widget build(BuildContext context) {
    final bool isGuide = _itineraryData['isGuide'] == true;
    final currentUser = AuthService().currentUser.value;
    final currentUserIdStr = currentUser?.id?.toString();
    final currentUserEmail = currentUser?.email?.trim().toLowerCase();

    final ownerIdStr =
        (_itineraryData['userId'] ??
                _itineraryData['user_id'] ??
                _itineraryData['user']?['id'] ??
                _itineraryData['authorId'] ??
                _itineraryData['author']?['id'])
            ?.toString();

    final bool isOwner =
        _currentRole == 'OWNER' ||
        (currentUserIdStr != null &&
            ownerIdStr != null &&
            currentUserIdStr == ownerIdStr) ||
        (_itineraryData['role'] == null && ownerIdStr == null);

    // Build comprehensive list of member entries from _itineraryMembers & _itineraryData['members']
    final List rawMembersList = [
      ...?_itineraryMembers,
      if (_itineraryData['members'] is List)
        ...(_itineraryData['members'] as List),
    ];

    final bool isInMembersList = rawMembersList.any((m) {
      if (m is! Map) return false;
      final mUserId =
          (m['userId'] ?? m['user_id'] ?? m['id'] ?? m['user']?['id'])
              ?.toString();
      final mEmail = (m['email'] ?? m['user']?['email'])
          ?.toString()
          .trim()
          .toLowerCase();
      return (currentUserIdStr != null && mUserId == currentUserIdStr) ||
          (currentUserEmail != null &&
              mEmail != null &&
              currentUserEmail == mEmail);
    });

    final bool isMember =
        isOwner ||
        _currentRole == 'EDITOR' ||
        _currentRole == 'VIEWER' ||
        isInMembersList;

    bool isAccessDenied = false;
    String accessDeniedMsg = '';

    if (_privacySetting == 'private' && !isOwner) {
      isAccessDenied = true;
      accessDeniedMsg = isGuide
          ? 'Bài hướng dẫn này ở chế độ Riêng tư. Chỉ chủ sở hữu mới có quyền xem.'
          : 'Hành trình này ở chế độ Riêng tư. Chỉ chủ sở hữu mới có quyền xem.';
    } else if (_privacySetting == 'members' && !isMember) {
      isAccessDenied = true;
      accessDeniedMsg = isGuide
          ? 'Bài hướng dẫn này ở chế độ Thành viên. Chỉ các đồng tác giả được mời mới có quyền xem.'
          : 'Hành trình này ở chế độ Thành viên. Chỉ các thành viên được mời mới có quyền xem.';
    }

    if (isAccessDenied) {
      return Scaffold(
        backgroundColor: AppTheme.background,
        appBar: AppBar(
          backgroundColor: Colors.white,
          elevation: 0,
          leading: IconButton(
            icon: Icon(Icons.arrow_back, color: AppTheme.darkText),
            onPressed: () => Navigator.pop(context),
          ),
          title: Text(
            isGuide ? 'Hướng dẫn du lịch' : 'Lịch trình chuyến đi',
            style: TextStyle(
              color: AppTheme.darkText,
              fontWeight: FontWeight.bold,
            ),
          ),
        ),
        body: Center(
          child: Padding(
            padding: const EdgeInsets.all(32.0),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Icon(
                  _privacySetting == 'private'
                      ? Icons.lock_rounded
                      : Icons.group_off_rounded,
                  size: 64,
                  color: Colors.grey[400],
                ),
                const SizedBox(height: 16),
                Text(
                  'Quyền truy cập bị hạn chế',
                  style: TextStyle(
                    fontSize: 20,
                    fontWeight: FontWeight.bold,
                    color: AppTheme.darkText,
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  accessDeniedMsg,
                  textAlign: TextAlign.center,
                  style: TextStyle(fontSize: 14, color: Colors.grey[600]),
                ),
                const SizedBox(height: 24),
                ElevatedButton(
                  onPressed: () => Navigator.pop(context),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: AppTheme.primary,
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                  child: const Text(
                    'Quay lại',
                    style: TextStyle(color: Colors.white),
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    }

    final destination = _itineraryData['destination'] ?? 'Điểm đến';
    final PreferredSizeWidget appBarBottom = PreferredSize(
      preferredSize: const Size.fromHeight(48),
      child: Container(
        color: Colors.white,
        child: TabBar(
          controller: _tabController,
          labelColor: AppTheme.primary,
          unselectedLabelColor: AppTheme.subtitleText,
          indicatorColor: AppTheme.primary,
          indicatorWeight: 3,
          indicatorSize: TabBarIndicatorSize.tab,
          labelPadding: EdgeInsets.zero,
          labelStyle: const TextStyle(
            fontWeight: FontWeight.bold,
            fontSize: 13,
          ),
          tabs: _itineraryData['isGuide'] == true
              ? const [
                  Tab(
                    child: Text(
                      'Tổng quan',
                      textScaler: TextScaler.noScaling,
                      maxLines: 1,
                    ),
                  ),
                  Tab(
                    child: Text(
                      'Khám phá',
                      textScaler: TextScaler.noScaling,
                      maxLines: 1,
                    ),
                  ),
                ]
              : const [
                  Tab(
                    child: Text(
                      'Tổng quan',
                      textScaler: TextScaler.noScaling,
                      maxLines: 1,
                    ),
                  ),
                  Tab(
                    child: Text(
                      'Hành trình',
                      textScaler: TextScaler.noScaling,
                      maxLines: 1,
                    ),
                  ),
                  Tab(
                    child: Text(
                      'Chi phí',
                      textScaler: TextScaler.noScaling,
                      maxLines: 1,
                    ),
                  ),
                  Tab(
                    child: Text(
                      'Khám phá',
                      textScaler: TextScaler.noScaling,
                      maxLines: 1,
                    ),
                  ),
                ],
        ),
      ),
    );

    final topPadding = MediaQuery.of(context).padding.top;
    final headerHeight =
        topPadding + 56.0 + 48.0; // 56 for AppBar + 48 for TabBar
    final screenHeight = MediaQuery.of(context).size.height;
    final double halfHeight = (screenHeight - headerHeight) * 0.55;
    final double targetSheetHeight = !_isMapExpanded
        ? (screenHeight - headerHeight)
        : (_selectedMapPlace != null
              ? 0.0
              : (_isSheetHalf ? halfHeight : 75.0));

    return Scaffold(
      backgroundColor: AppTheme.background,
      body: Stack(
        children: [
          // 1. Background Map
          Positioned.fill(
            child: _mapCenter != null
                ? FlutterMap(
                    mapController: _mapController,
                    options: MapOptions(
                      initialCenter: _mapCenter!,
                      initialZoom: 13.0,
                      onTap: (tapPosition, point) {
                        setState(() {
                          _selectedMapPlace = null;
                        });
                      },
                    ),
                    children: [
                      TileLayer(
                        urlTemplate:
                            'https://mt1.google.com/vt/lyrs=m&x={x}&y={y}&z={z}&apistyle=s.t%3A2%7Cp.v%3Aoff',
                      ),
                      PolylineLayer(
                        polylines: (() {
                          // Khi tìm kiếm địa điểm hoặc lọc: ẩn chỉ đường của các địa điểm ở hành trình đi
                          if ((_activeSearchQuery != null &&
                                  _activeSearchQuery!.isNotEmpty) ||
                              _filteredMapPlaces.isNotEmpty) {
                            return const <Polyline>[];
                          }

                          if (_activeNavStartPlace != null &&
                              _activeNavEndPlace != null) {
                            final List<Polyline> navPolylines = [];
                            if (_activeNavRoutePoints.length >= 2) {
                              navPolylines.add(
                                Polyline(
                                  points: _activeNavRoutePoints,
                                  strokeWidth: 8.5,
                                  color: const Color(0xFF2563EB).withAlpha(90),
                                ),
                              );
                              navPolylines.add(
                                Polyline(
                                  points: _activeNavRoutePoints,
                                  strokeWidth: 5.0,
                                  color: const Color(0xFF2563EB),
                                ),
                              );
                            }
                            return navPolylines;
                          }

                          if (_dayRoadPolylines.isEmpty &&
                              !_isLoadingRoadRoutes) {
                            WidgetsBinding.instance.addPostFrameCallback((_) {
                              _updateRoadPolylines();
                            });
                          }

                          final List<Polyline> polylines = [];
                          final int numDays =
                              (_itineraryData['days'] as num?)?.toInt() ?? 1;

                          for (int dayIdx = 0; dayIdx < numDays; dayIdx++) {
                            final dayNum = dayIdx + 1;
                            if (_checkedDays != null &&
                                !_checkedDays!.contains(dayNum)) {
                              continue;
                            }

                            final color =
                                _dayColors[dayIdx % _dayColors.length] ??
                                AppTheme.primary;
                            final roadPoints = _dayRoadPolylines[dayNum];

                            if (roadPoints != null && roadPoints.length >= 2) {
                              polylines.add(
                                Polyline(
                                  points: roadPoints,
                                  strokeWidth: 4.5,
                                  color: color.withAlpha(230),
                                ),
                              );
                            } else {
                              final rawDayPlaces = _details
                                  .where(
                                    (d) =>
                                        (d['day'] as num?)?.toInt() == dayNum &&
                                        d['place'] != null,
                                  )
                                  .toList();
                              final dayPlaces = _optimizeDayPlacesWithAStar(
                                rawDayPlaces,
                              );
                              final List<LatLng> dayPoints = [];
                              for (var d in dayPlaces) {
                                final p = d['place'];
                                if (p != null &&
                                    p['latitude'] != null &&
                                    p['longitude'] != null) {
                                  final lat = (p['latitude'] as num).toDouble();
                                  final lon = (p['longitude'] as num)
                                      .toDouble();
                                  if (lat != 0.0 && lon != 0.0) {
                                    dayPoints.add(LatLng(lat, lon));
                                  }
                                }
                              }

                              if (dayPoints.length >= 2) {
                                polylines.add(
                                  Polyline(
                                    points: dayPoints,
                                    strokeWidth: 4.0,
                                    color: color.withAlpha(220),
                                  ),
                                );
                              }
                            }
                          }
                          return polylines;
                        })(),
                      ),
                      MarkerLayer(
                        markers: (() {
                          if (_activeNavStartPlace != null &&
                              _activeNavEndPlace != null) {
                            final List<Marker> navMarkers = [];
                            final p1 = _activeNavStartPlace!;
                            final p2 = _activeNavEndPlace!;

                            final lat1 =
                                (p1['latitude'] as num?)?.toDouble() ??
                                (p1['place']?['latitude'] as num?)?.toDouble();
                            final lng1 =
                                (p1['longitude'] as num?)?.toDouble() ??
                                (p1['place']?['longitude'] as num?)?.toDouble();
                            final lat2 =
                                (p2['latitude'] as num?)?.toDouble() ??
                                (p2['place']?['latitude'] as num?)?.toDouble();
                            final lng2 =
                                (p2['longitude'] as num?)?.toDouble() ??
                                (p2['place']?['longitude'] as num?)?.toDouble();

                            final name1 =
                                p1['name'] ?? p1['place']?['name'] ?? 'Điểm đi';
                            final name2 =
                                p2['name'] ??
                                p2['place']?['name'] ??
                                'Điểm đến';

                            if (lat1 != null &&
