            width: double.infinity,
            color: !_isMapExpanded ? Colors.white : Colors.transparent,
            child: SafeArea(
              bottom: false,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  // Top Bar
                  SizedBox(
                    height: 56,
                    child: _isSelectionMode
                        ? Row(
                            children: [
                              Container(
