  bool _isEmptyNote(Map<String, dynamic> item) {
    final isPlace = item['placeId'] != null || item['place'] != null;
    if (isPlace) return false;
    final text = (item['noteText'] ?? item['notetext'] ?? '').toString();
    final rawTodo = item['todoItems'] ?? item['todoitems'];
    final isChecklist = text.startsWith('[TODO]') || rawTodo != null;
    if (isChecklist) return false;
    return text.trim().isEmpty ||
        text == 'Ghi chú mới' ||
        text == 'Thêm ghi chú tại đây';
  }

  bool _isEmptyChecklist(Map<String, dynamic> item) {
    final isPlace = item['placeId'] != null || item['place'] != null;
    if (isPlace) return false;
    final text = (item['noteText'] ?? item['notetext'] ?? '').toString();
    final rawTodo = item['todoItems'] ?? item['todoitems'];
    final isChecklist = text.startsWith('[TODO]') || rawTodo != null;
    if (!isChecklist) return false;

    List<dynamic> todoList = [];
    if (rawTodo != null) {
      if (rawTodo is List) {
        todoList = rawTodo;
      } else if (rawTodo is String) {
        try {
          todoList = json.decode(rawTodo) as List;
        } catch (_) {}
      }
    }
    return todoList.isEmpty;
  }

  Future<void> _addNoteInline(String section) async {
    if (!_checkCanEdit() || _isAddingInlineItem) return;
    _isAddingInlineItem = true;
    try {
      final itineraryId = _itineraryData['id'] as int;
      final isDay =
          section.startsWith('Ngày') && _itineraryData['isGuide'] != true;
      final int? day = isDay
          ? (int.tryParse(section.replaceAll(RegExp(r'[^0-9]'), '')) ?? 1)
          : null;

      final targetList = isDay
          ? _details.where((d) => d['day'] == day).toList()
          : _savedPlaces.where((sp) => sp['section'] == section).toList();

      for (final item in targetList) {
        if (_isEmptyNote(item) || _isEmptyChecklist(item)) {
          setState(() {
            _editingNoteId = item['id'] as int?;
          });
          _showPremiumNotification(
            title: 'Vui lòng nhập nội dung',
            message:
                'Bạn đang có một ghi chú hoặc danh sách chưa nhập nội dung.',
            icon: Icons.edit_note_rounded,
            color: Colors.orangeAccent,
          );
          return;
        }
      }

      final tempItem = {
        'id': DateTime.now().millisecondsSinceEpoch,
        'itineraryId': itineraryId,
        'section': isDay ? null : section,
        'day': day,
        'noteText': '',
        'sortOrder': 9999,
      };

      // OPTIMISTIC ADD NOTE: Hiện ngay trên màn hình (0s)
      setState(() {
        _editingNoteId = tempItem['id'] as int;
        if (isDay) {
          _details.add(tempItem);
        } else {
          _savedPlaces.add(tempItem);
        }
      });

      dynamic result;
      if (isDay) {
        final dayDetails = _details.where((d) => d['day'] == day).toList();
        int maxOrder = 0;
        for (var d in dayDetails) {
          final ord = d['sortOrder'] ?? 0;
          if (ord > maxOrder) maxOrder = ord;
        }
        result = await DatabaseService().addPlaceToItinerary(
          itineraryId: itineraryId,
          day: day!,
          noteText: '',
          sortOrder: maxOrder + 1,
        );
      } else {
        final sectionDetails = _savedPlaces
            .where((d) => d['section'] == section)
            .toList();
        int maxOrder = 0;
        for (var d in sectionDetails) {
          final ord = d['sortOrder'] ?? 0;
          if (ord > maxOrder) maxOrder = ord;
        }
        result = await DatabaseService().addPlaceToSaved(
          itineraryId: itineraryId,
          section: section,
          noteText: '',
          sortOrder: maxOrder + 1,
        );
      }

      if (result != null && result['id'] != null) {
        setState(() {
          _editingNoteId = result['id'] as int;
          if (isDay) {
            final idx = _details.indexWhere((d) => d['id'] == tempItem['id']);
            if (idx != -1) _details[idx] = result;
          } else {
            final idx = _savedPlaces.indexWhere(
              (sp) => sp['id'] == tempItem['id'],
            );
            if (idx != -1) _savedPlaces[idx] = result;
          }
        });
      }
    } finally {
      await Future.delayed(const Duration(milliseconds: 300));
      _isAddingInlineItem = false;
    }
  }

  Future<void> _addChecklistInline(String section) async {
    if (!_checkCanEdit() || _isAddingInlineItem) return;
    _isAddingInlineItem = true;

    try {
      final itineraryId = _itineraryData['id'] as int;
      final isDay =
          section.startsWith('Ngày') && _itineraryData['isGuide'] != true;
      final int? day = isDay
          ? (int.tryParse(section.replaceAll(RegExp(r'[^0-9]'), '')) ?? 1)
          : null;

      final targetList = isDay
          ? _details.where((d) => d['day'] == day).toList()
          : _savedPlaces.where((sp) => sp['section'] == section).toList();

      for (final item in targetList) {
        if (_isEmptyNote(item) || _isEmptyChecklist(item)) {
          setState(() {
            _editingNoteId = item['id'] as int?;
          });
          _showPremiumNotification(
            title: 'Vui lòng nhập nội dung',
            message:
                'Bạn đang có một ghi chú hoặc danh sách chưa nhập nội dung.',
            icon: Icons.checklist_rounded,
            color: Colors.orangeAccent,
          );
          return;
        }
      }

      final tempItem = {
        'id': DateTime.now().millisecondsSinceEpoch,
        'itineraryId': itineraryId,
        'section': isDay ? null : section,
        'day': day,
        'noteText': '[TODO] Danh sách công việc',
        'sortOrder': 9999,
        'todoItems': [],
      };

      // OPTIMISTIC ADD CHECKLIST: Hiển thị ngay lập tức (0s)
      setState(() {
        _editingNoteId = tempItem['id'] as int;
        if (isDay) {
          _details.add(tempItem);
        } else {
          _savedPlaces.add(tempItem);
        }
      });

      dynamic result;
      if (isDay) {
        final dayDetails = _details.where((d) => d['day'] == day).toList();
        int maxOrder = 0;
        for (var d in dayDetails) {
          final ord = d['sortOrder'] ?? d['sortorder'] ?? 0;
          if (ord > maxOrder) maxOrder = ord;
        }
        result = await DatabaseService().addPlaceToItinerary(
          itineraryId: itineraryId,
          day: day!,
          noteText: '[TODO] Danh sách công việc',
          sortOrder: maxOrder + 1,
        );
      } else {
        final sectionDetails = _savedPlaces
            .where((d) => d['section'] == section)
            .toList();
        int maxOrder = 0;
        for (var d in sectionDetails) {
          final ord = d['sortOrder'] ?? d['sortorder'] ?? 0;
          if (ord > maxOrder) maxOrder = ord;
        }
        result = await DatabaseService().addPlaceToSaved(
          itineraryId: itineraryId,
          section: section,
          noteText: '[TODO] Danh sách công việc',
          sortOrder: maxOrder + 1,
        );
      }

      if (result != null && result['id'] != null) {
        setState(() {
          _editingNoteId = result['id'] as int?;
          if (isDay) {
            final idx = _details.indexWhere((d) => d['id'] == tempItem['id']);
            if (idx != -1) _details[idx] = result;
          } else {
            final idx = _savedPlaces.indexWhere(
              (sp) => sp['id'] == tempItem['id'],
            );
            if (idx != -1) _savedPlaces[idx] = result;
          }
        });
      }
    } finally {
      await Future.delayed(const Duration(milliseconds: 300));
      _isAddingInlineItem = false;
    }
  }

  void _showTemplateBottomSheet(
    int checklistId,
    List<dynamic> currentItems,
    bool isItineraryDetail, {
    VoidCallback? onAddFinished,
  }) {
    if (!_checkCanEdit()) return;
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (context) {
        return _ChecklistTemplateSheet(
          checklistId: checklistId,
          currentItems: currentItems,
          onAddItems: (newItems) async {
            final List<Map<String, dynamic>> updated =
                List<Map<String, dynamic>>.from(
                  currentItems
                      .map((it) => Map<String, dynamic>.from(it as Map))
                      .toList(),
                );
            for (var itemText in newItems) {
              if (!updated.any((it) => it['text'] == itemText)) {
                updated.add({'text': itemText, 'done': false});
              }
            }
            final success = await DatabaseService().updateNoteOrDetail(
              checklistId,
              {'todoItems': updated},
              isItineraryDetail,
            );
            if (success && mounted) {
              await _loadData(silent: true);
              if (onAddFinished != null) {
                onAddFinished();
              }
            }
          },
        );
      },
    );
  }

  void _fitMapToBounds(List<Map<String, dynamic>> details) {
    if (details.isEmpty) return;

    double minLat = 90.0;
    double maxLat = -90.0;
    double minLon = 180.0;
    double maxLon = -180.0;
    bool hasValidPoints = false;

    for (var d in details) {
      final p = d['place'];
      if (p != null && p['latitude'] != null && p['longitude'] != null) {
        final lat = (p['latitude'] as num).toDouble();
        final lon = (p['longitude'] as num).toDouble();
        if (lat < minLat) minLat = lat;
        if (lat > maxLat) maxLat = lat;
        if (lon < minLon) minLon = lon;
        if (lon > maxLon) maxLon = lon;
        hasValidPoints = true;
      }
    }

    if (!hasValidPoints) return;

    // Add some padding to bounds
    final latPadding = (maxLat - minLat) * 0.1;
    final lonPadding = (maxLon - minLon) * 0.1;

    // If it's a single point, bounds will be zero, so we pad it.
    if (maxLat == minLat && maxLon == minLon) {
      _mapController.move(LatLng(minLat, minLon), 15.0);
      return;
    }

    final bounds = LatLngBounds(
      LatLng(minLat - latPadding, minLon - lonPadding),
      LatLng(maxLat + latPadding, maxLon + lonPadding),
    );

    try {
      _mapController.fitCamera(
        CameraFit.bounds(
          bounds: bounds,
          padding: const EdgeInsets.all(50),
          maxZoom: 16.0,
          minZoom: 10.0,
        ),
      );
    } catch (_) {}
  }

