    bool isSavedToCurrentTrip = savedCount > 0;

    return Positioned(
      left: 16,
      right: 16,
      bottom: 16.0 + MediaQuery.of(context).padding.bottom,
      child: Container(
        padding: const EdgeInsets.all(16),
