  Widget _buildSavedNoteCard(
    Map<String, dynamic> detail,
    int index,
    int listIdx,
    List<Map<String, dynamic>> sectionDetails,
  ) {
    final bool isItineraryDetail = detail.containsKey('day');
    final String text = detail['noteText'] ?? detail['notetext'] ?? '';
    final bool isCollapsed =
        detail['isCollapsed'] == true || detail['iscollapsed'] == true;
    final int id = detail['id'] as int;
    final bool isEditing = id == _editingNoteId;

    final bool isTodo = text.startsWith('[TODO]');
    final String displayTitle = isTodo
        ? text.replaceFirst('[TODO]', '').trim()
        : text;

    TextEditingController? editController;
    if (isEditing) {
      editController = TextEditingController(
        text: isTodo
            ? displayTitle
            : ((text == 'Thêm ghi chú tại đây' || text == 'Ghi chú mới')
                  ? ''
                  : text),
      );
      editController.selection = TextSelection.fromPosition(
        TextPosition(offset: editController.text.length),
      );
    }

    List<dynamic> reactions = [];
    if (detail['reactions'] != null) {
      if (detail['reactions'] is List) {
        reactions = detail['reactions'] as List;
      } else if (detail['reactions'] is String) {
        try {
          reactions = json.decode(detail['reactions']) as List;
        } catch (_) {}
      }
    }

    List<dynamic> todoList = [];
    final rawTodo = detail['todoItems'] ?? detail['todoitems'];
    if (rawTodo != null) {
      if (rawTodo is List) {
        todoList = rawTodo;
      } else if (rawTodo is String) {
        try {
          todoList = json.decode(rawTodo) as List;
        } catch (_) {}
      }
    }

    final bool allDone =
        todoList.isNotEmpty && todoList.every((item) => item['done'] == true);

    final cardWidget = GestureDetector(
      onTap: () {
        if (_isSelectionMode) {
          setState(() {
            if (_selectedItemIds.contains(id)) {
              _selectedItemIds.remove(id);
            } else {
              _selectedItemIds.add(id);
            }
          });
        }
      },
      child: Container(
        margin: const EdgeInsets.only(bottom: 12),
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: const Color(0xFFF8FAFC),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: AppTheme.border, width: 0.5),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // ── Header row: icon + title + collapse/check toggle
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (!_isViewer && isItineraryDetail)
                  ReorderableDragStartListener(
                    index: listIdx,
                    child: Padding(
                      padding: const EdgeInsets.only(right: 8, top: 4),
                      child: Icon(
                        Icons.drag_indicator_rounded,
                        color: Colors.grey[400],
                        size: 20,
                      ),
                    ),
                  ),
                Container(
                  padding: const EdgeInsets.all(8),
                  decoration: const BoxDecoration(
                    color: Color(0xFFE2E8F0),
                    shape: BoxShape.circle,
                  ),
                  child: Icon(
                    isTodo
                        ? Icons.fact_check_outlined
                        : Icons.description_outlined,
                    color: AppTheme.subtitleText,
                    size: 16,
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.only(top: 6),
                    child: isEditing
                        ? Builder(
                            builder: (context) {
                              if (editController != null &&
                                  editController.text.isNotEmpty) {
                                editController.selection = TextSelection(
                                  baseOffset: 0,
                                  extentOffset: editController.text.length,
                                );
                              }
                              return TextField(
                                controller: editController,
                                autofocus: true,
                                style: TextStyle(
                                  fontSize: 13,
                                  color: AppTheme.darkText,
                                  fontWeight: FontWeight.w500,
                                ),
                                onChanged: (val) {
                                  final itinId = _itineraryData['id'] as int;
                                  final userId = AuthService()
                                      .currentUser
                                      .value
                                      ?.id
                                      ?.toString();
                                  ItinerarySocketService().sendTypingNote(
                                    itineraryId: itinId,
                                    noteId: id,
                                    text: isTodo ? '[TODO] $val' : val,
                                    isItineraryDetail: isItineraryDetail,
                                    userId: userId,
                                  );
                                },
                                decoration: InputDecoration(
                                  hintText: isTodo
                                      ? 'Tên danh sách...'
                                      : 'Nhập ghi chú...',
                                  hintStyle: const TextStyle(
                                    color: Colors.black26,
                                    fontSize: 13,
                                  ),
                                  border: InputBorder.none,
                                  focusedBorder: InputBorder.none,
                                  enabledBorder: InputBorder.none,
                                  errorBorder: InputBorder.none,
                                  disabledBorder: InputBorder.none,
                                  filled: false,
                                  fillColor: Colors.transparent,
                                  isDense: true,
                                  contentPadding: EdgeInsets.zero,
                                ),
                                onSubmitted: (val) async {
                                  final cleanVal = val.trim();
                                  String finalVal = cleanVal;
                                  if (isTodo && cleanVal.isEmpty)
                                    finalVal = 'Danh sách công việc';
                                  if (isTodo) finalVal = '[TODO] $finalVal';
                                  setState(() {
                                    if (isItineraryDetail) {
                                      final idx = _details.indexWhere(
                                        (d) => d['id'] == id,
                                      );
                                      if (idx != -1)
                                        _details[idx]['noteText'] = finalVal;
                                    } else {
                                      final idx = _savedPlaces.indexWhere(
                                        (sp) => sp['id'] == id,
                                      );
                                      if (idx != -1)
                                        _savedPlaces[idx]['noteText'] =
                                            finalVal;
                                    }
                                    _editingNoteId = null;
                                  });
                                  DatabaseService().updateNoteOrDetail(id, {
                                    'noteText': finalVal,
                                  }, isItineraryDetail);
                                },
                              );
                            },
                          )
                        : GestureDetector(
                            onTap: () {
                              if (!_checkCanEdit()) return;
                              setState(() => _editingNoteId = id);
                            },
                            child: Text(
                              isTodo
                                  ? (displayTitle.isEmpty
                                        ? 'Danh sách công việc'
                                        : displayTitle)
                                  : (text.isEmpty ? 'Nhập ghi chú...' : text),
                              style: TextStyle(
                                fontSize: 13,
                                color: (!isTodo && text.isEmpty)
                                    ? Colors.black26
                                    : AppTheme.darkText,
                                fontWeight: FontWeight.w500,
                              ),
                            ),
                          ),
                  ),
                ),
                const SizedBox(width: 8),
                // Right-side button: save / all-done / collapse-toggle
                if (isEditing)
                  GestureDetector(
                    onTap: () {
                      final cleanVal = editController?.text.trim() ?? '';
                      String finalVal = cleanVal;
                      if (isTodo && cleanVal.isEmpty)
                        finalVal = 'Danh sách công việc';
                      if (isTodo) finalVal = '[TODO] $finalVal';
                      setState(() {
                        if (isItineraryDetail) {
                          final idx = _details.indexWhere((d) => d['id'] == id);
                          if (idx != -1) _details[idx]['noteText'] = finalVal;
                        } else {
                          final idx = _savedPlaces.indexWhere(
                            (sp) => sp['id'] == id,
                          );
                          if (idx != -1)
                            _savedPlaces[idx]['noteText'] = finalVal;
                        }
                        _editingNoteId = null;
                      });
                      DatabaseService().updateNoteOrDetail(id, {
                        'noteText': finalVal,
                      }, isItineraryDetail);
                    },
                    child: Icon(
                      Icons.check_rounded,
                      color: AppTheme.green,
                      size: 22,
                    ),
                  )
                else
                  GestureDetector(
                    onTap: () {
                      final newCollapsed = !isCollapsed;
                      setState(() {
                        if (isItineraryDetail) {
                          final idx = _details.indexWhere((d) => d['id'] == id);
                          if (idx != -1)
                            _details[idx]['isCollapsed'] = newCollapsed;
                        } else {
                          final idx = _savedPlaces.indexWhere(
                            (sp) => sp['id'] == id,
                          );
                          if (idx != -1)
                            _savedPlaces[idx]['isCollapsed'] = newCollapsed;
                        }
                      });
                      DatabaseService().updateNoteOrDetail(id, {
                        'isCollapsed': newCollapsed,
                      }, isItineraryDetail);
                    },
                    child: Padding(
                      padding: const EdgeInsets.only(left: 4),
                      child: Icon(
                        isCollapsed
                            ? Icons.keyboard_arrow_down_rounded
                            : Icons.keyboard_arrow_up_rounded,
                        color: AppTheme.subtitleText,
                        size: 20,
                      ),
                    ),
                  ),
                if (_isSelectionMode)
                  IgnorePointer(
                    child: Checkbox(
                      value: _selectedItemIds.contains(id),
                      onChanged: (_) {},
                      activeColor: AppTheme.primary,
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(4),
                      ),
                    ),
                  ),
              ],
            ),

            // ── Todo items list
            if (isTodo && todoList.isNotEmpty) ...[
              const SizedBox(height: 8),
              Padding(
                padding: const EdgeInsets.only(left: 36),
                child: ReorderableListView(
                  shrinkWrap: true,
                  physics: const NeverScrollableScrollPhysics(),
                  buildDefaultDragHandles: true,
                  onReorder: (oldIndex, newIndex) {
                    if (!_checkCanEdit()) return;
                    if (oldIndex < newIndex) newIndex -= 1;
                    final updated = List.from(todoList);
                    final item = updated.removeAt(oldIndex);
                    updated.insert(newIndex, item);
                    setState(() {
                      if (isItineraryDetail) {
                        final idx = _details.indexWhere((d) => d['id'] == id);
                        if (idx != -1) _details[idx]['todoItems'] = updated;
                      } else {
                        final idx = _savedPlaces.indexWhere(
                          (sp) => sp['id'] == id,
                        );
                        if (idx != -1) _savedPlaces[idx]['todoItems'] = updated;
                      }
                    });
                    DatabaseService().updateNoteOrDetail(id, {
                      'todoItems': updated,
                    }, isItineraryDetail);
                  },
                  children: todoList.asMap().entries.map((entry) {
                    final itemIdx = entry.key;
                    final item = entry.value;
                    final String itemText = item['text'] ?? '';
                    final bool done = item['done'] == true;
                    final String itemKey = '${id}_$itemText';
                    final bool isFocused = _focusedTodoItemKey == itemKey;

                    return Padding(
                      key: ValueKey(itemKey),
                      padding: const EdgeInsets.symmetric(vertical: 4),
                      child: Row(
                        children: [
                          GestureDetector(
                            onTap: () {
                              if (!_checkCanEdit()) return;
                              final updated = todoList.map((it) {
                                if (it['text'] == itemText) {
                                  return {...it as Map, 'done': !done};
                                }
                                return it;
                              }).toList();
                              setState(() {
                                if (isItineraryDetail) {
                                  final idx = _details.indexWhere(
                                    (d) => d['id'] == id,
                                  );
                                  if (idx != -1)
                                    _details[idx]['todoItems'] = updated;
                                } else {
                                  final idx = _savedPlaces.indexWhere(
                                    (sp) => sp['id'] == id,
                                  );
                                  if (idx != -1)
                                    _savedPlaces[idx]['todoItems'] = updated;
                                }
                              });
                              DatabaseService().updateNoteOrDetail(id, {
                                'todoItems': updated,
                              }, isItineraryDetail);
                            },
                            child: Icon(
                              done
                                  ? Icons.check_circle
                                  : Icons.radio_button_unchecked,
                              color: done
                                  ? AppTheme.primary
                                  : AppTheme.subtitleText,
                              size: 20,
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: GestureDetector(
                              onTap: () {
                                setState(() {
                                  if (isFocused) {
                                    _focusedTodoItemKey = null;
                                  } else {
                                    _focusedTodoItemKey = itemKey;
                                  }
                                });
                              },
                              child: Container(
                                color: Colors.transparent,
                                child: Text(
                                  itemText,
                                  style: TextStyle(
                                    fontSize: 13,
                                    color: done
                                        ? AppTheme.subtitleText
                                        : AppTheme.darkText,
                                    decoration: done
                                        ? TextDecoration.lineThrough
                                        : null,
                                  ),
                                ),
                              ),
                            ),
                          ),
                          if (isFocused) ...[
                            GestureDetector(
                              onTap: () {
                                if (!_checkCanEdit()) return;
                                final updated = List.from(todoList)
                                  ..removeWhere((it) => it['text'] == itemText);
                                setState(() {
                                  if (isItineraryDetail) {
                                    final idx = _details.indexWhere(
                                      (d) => d['id'] == id,
                                    );
                                    if (idx != -1)
                                      _details[idx]['todoItems'] = updated;
                                  } else {
                                    final idx = _savedPlaces.indexWhere(
                                      (sp) => sp['id'] == id,
                                    );
                                    if (idx != -1)
                                      _savedPlaces[idx]['todoItems'] = updated;
                                  }
                                  _focusedTodoItemKey = null;
                                });
                                DatabaseService().updateNoteOrDetail(id, {
                                  'todoItems': updated,
                                }, isItineraryDetail);
                              },
                              child: const Padding(
                                padding: EdgeInsets.symmetric(horizontal: 4),
                                child: Icon(
                                  Icons.delete_outline_rounded,
                                  size: 16,
                                  color: Colors.redAccent,
                                ),
                              ),
                            ),
                          ],
                        ],
                      ),
                    );
                  }).toList(),
                ),
              ),
            ],

            // ── Add todo item input
            if (isTodo && !isCollapsed && !_isViewer) ...[
              const SizedBox(height: 4),
              Padding(
                padding: const EdgeInsets.only(left: 36),
                child: Row(
                  children: [
                    Icon(
                      Icons.radio_button_unchecked,
                      color: AppTheme.subtitleText,
                      size: 20,
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: TextField(
                        decoration: InputDecoration(
                          hintText: 'Thêm mục mới...',
                          hintStyle: TextStyle(
                            color: AppTheme.subtitleText,
                            fontSize: 13,
                          ),
                          border: InputBorder.none,
                          focusedBorder: InputBorder.none,
                          enabledBorder: InputBorder.none,
                          errorBorder: InputBorder.none,
                          disabledBorder: InputBorder.none,
                          filled: false,
                          fillColor: Colors.transparent,
                          isDense: true,
                          contentPadding: EdgeInsets.symmetric(vertical: 4),
                        ),
                        onSubmitted: (val) {
                          final cleanVal = val.trim();
                          if (cleanVal.isNotEmpty &&
                              !todoList.any((it) => it['text'] == cleanVal)) {
                            final updated = List.from(todoList)
                              ..add({'text': cleanVal, 'done': false});
                            setState(() {
                              if (isItineraryDetail) {
                                final idx = _details.indexWhere(
                                  (d) => d['id'] == id,
                                );
                                if (idx != -1)
                                  _details[idx]['todoItems'] = updated;
                              } else {
                                final idx = _savedPlaces.indexWhere(
                                  (sp) => sp['id'] == id,
                                );
                                if (idx != -1)
                                  _savedPlaces[idx]['todoItems'] = updated;
                              }
                            });
                            DatabaseService().updateNoteOrDetail(id, {
                              'todoItems': updated,
                            }, isItineraryDetail);
                          }
                        },
                      ),
                    ),
                  ],
                ),
              ),
            ],

            // ── Collapsed emoji display for notes
            if (!isTodo && isCollapsed && reactions.isNotEmpty) ...[
              const SizedBox(height: 8),
              Wrap(
                spacing: 6,
                runSpacing: 6,
                children: reactions.map((emoji) {
                  return GestureDetector(
                    onTap: () {
                      final updated = List.from(reactions)..remove(emoji);
                      DatabaseService()
                          .updateNoteOrDetail(id, {
                            'reactions': updated,
                          }, isItineraryDetail)
                          .then((_) => _loadData(silent: true));
                    },
                    child: _emojiChip(emoji as String),
                  );
                }).toList(),
              ),
            ],

            // ── Toolbar (shown when expanded)
            if (!isCollapsed) ...[
              const SizedBox(height: 8),
              Divider(color: AppTheme.border, height: 1, thickness: 0.5),
              const SizedBox(height: 8),
              Row(
                crossAxisAlignment: CrossAxisAlignment.center,
                children: [
                  Expanded(
                    child: isTodo
                        // Todo left side: "Danh sách làm sẵn" button
                        ? GestureDetector(
                            onTap: () => _showTemplateBottomSheet(
                              id,
                              todoList,
                              isItineraryDetail,
                            ),
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Icon(
                                  Icons.card_travel_outlined,
                                  color: AppTheme.subtitleText,
                                  size: 16,
                                ),
                                SizedBox(width: 6),
                                Text(
                                  'Danh sách làm sẵn',
                                  style: TextStyle(
                                    fontSize: 12,
                                    color: AppTheme.darkText,
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                              ],
                            ),
                          )
                        // Note left side: emoji chips + picker button
                        : Wrap(
                            spacing: 6,
                            runSpacing: 6,
                            crossAxisAlignment: WrapCrossAlignment.center,
                            children: [
                              ...reactions.map((emoji) {
                                return GestureDetector(
                                  onTap: () {
                                    final updated = List.from(reactions)
                                      ..remove(emoji);
                                    DatabaseService()
                                        .updateNoteOrDetail(id, {
                                          'reactions': updated,
                                        }, isItineraryDetail)
                                        .then((_) => _loadData(silent: true));
                                  },
                                  child: _emojiChip(emoji as String),
                                );
                              }),
                              // Emoji picker button
                              GestureDetector(
                                onTap: () => _showEmojiPickerSheet(
                                  id,
                                  reactions,
                                  isItineraryDetail,
                                ),
                                child: Container(
                                  padding: const EdgeInsets.all(4),
                                  decoration: BoxDecoration(
                                    color: Colors.white,
                                    shape: BoxShape.circle,
                                    border: Border.all(color: AppTheme.border),
                                  ),
                                  child: Icon(
                                    Icons.sentiment_satisfied_alt_outlined,
                                    color: AppTheme.subtitleText,
                                    size: 16,
                                  ),
                                ),
                              ),
                            ],
                          ),
                  ),
                  // Right: delete, drag, collapse
                  GestureDetector(
                    onTap: () => _removePlaceDetail(
                      id,
                      text,
                      isSavedPlace: !isItineraryDetail,
                    ),
                    child: Padding(
                      padding: EdgeInsets.symmetric(horizontal: 6),
                      child: Icon(
                        Icons.delete_outline_rounded,
                        color: AppTheme.subtitleText,
                        size: 18,
                      ),
                    ),
                  ),
                ],
              ),
            ],
          ],
        ),
      ),
    );

    if (_isViewer) return cardWidget;

    return Draggable<Map<String, dynamic>>(
      data: detail,
      feedback: Material(
        type: MaterialType.transparency,
        child: Opacity(
          opacity: 0.8,
          child: Container(
            width: MediaQuery.of(context).size.width * 0.8,
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(16),
              border: Border.all(color: AppTheme.primary, width: 2),
              boxShadow: [
                BoxShadow(color: Colors.black.withAlpha(20), blurRadius: 10),
              ],
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(
                  isTodo
                      ? Icons.fact_check_outlined
                      : Icons.description_outlined,
                  color: AppTheme.primary,
                  size: 20,
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    displayTitle.isEmpty ? 'Ghi chú trống' : displayTitle,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.bold,
                      color: AppTheme.darkText,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
      childWhenDragging: Opacity(opacity: 0.3, child: cardWidget),
      child: cardWidget,
    );
  }

  Widget _emojiChip(String emoji) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: AppTheme.primary.withAlpha(20),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: AppTheme.primary.withAlpha(50)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(emoji, style: const TextStyle(fontSize: 14)),
          const SizedBox(width: 3),
          Text(
            '1',
            style: TextStyle(
              fontSize: 10,
              color: AppTheme.primary,
              fontWeight: FontWeight.bold,
            ),
          ),
        ],
      ),
    );
  }

