  Future<void> _selectTimeForDetail(Map<String, dynamic> detail) async {
    if (!_checkCanEdit()) return;
    final int detailId = detail['id'] as int;
    final bool isItineraryDetail = detail.containsKey('day');

    TimeOfDay initialStart = const TimeOfDay(hour: 8, minute: 0);
    if (detail['startTime'] != null &&
        detail['startTime'].toString().contains(':')) {
      final parts = detail['startTime'].toString().split(':');
      initialStart = TimeOfDay(
        hour: int.tryParse(parts[0]) ?? 8,
        minute: int.tryParse(parts[1]) ?? 0,
      );
    }

    final TimeOfDay? start = await showTimePicker(
      context: context,
      initialTime: initialStart,
      helpText: 'CHỌN GIỜ BẮT ĐẦU',
    );
    if (start == null) return;

    final int startMinutes = start.hour * 60 + start.minute;

    TimeOfDay initialEnd = TimeOfDay(
      hour: (start.hour + 1) % 24,
      minute: (start.minute + 30) % 60,
    );
    if (detail['endTime'] != null &&
        detail['endTime'].toString().contains(':')) {
      final parts = detail['endTime'].toString().split(':');
      final parsedH = int.tryParse(parts[0]) ?? initialEnd.hour;
      final parsedM = int.tryParse(parts[1]) ?? initialEnd.minute;
      if (parsedH * 60 + parsedM > startMinutes) {
        initialEnd = TimeOfDay(hour: parsedH, minute: parsedM);
      }
    }

    TimeOfDay? end = await showTimePicker(
      context: context,
      initialTime: initialEnd,
      helpText: 'CHỌN GIỜ KẾT THÚC (SAU GIỜ BẮT ĐẦU)',
    );
    if (end == null) return;

    int endMinutes = end.hour * 60 + end.minute;
    if (endMinutes <= startMinutes) {
      final adjustedMinutes = (startMinutes + 90) % (24 * 60);
      end = TimeOfDay(
        hour: adjustedMinutes ~/ 60,
        minute: adjustedMinutes % 60,
      );
      _showPremiumNotification(
        title: 'Giờ kết thúc đã tự điều chỉnh',
        message:
            'Giờ kết thúc phải sau giờ bắt đầu. Đã tự động chỉnh thành ${end.hour.toString().padLeft(2, '0')}:${end.minute.toString().padLeft(2, '0')}',
        icon: Icons.access_time_filled_rounded,
        color: const Color(0xFFD97706),
      );
    }

    final startStr =
        '${start.hour.toString().padLeft(2, '0')}:${start.minute.toString().padLeft(2, '0')}';
    final endStr =
        '${end.hour.toString().padLeft(2, '0')}:${end.minute.toString().padLeft(2, '0')}';

    List<Map<String, dynamic>> updatedDayItems = [];

    final String detailIdStr = (detail['id'] ?? detail['detailId'] ?? '')
        .toString();

    setState(() {
      if (isItineraryDetail) {
        final idx = _details.indexWhere(
          (d) => (d['id'] ?? '').toString() == detailIdStr,
        );
        if (idx != -1) {
          _details[idx]['startTime'] = startStr;
          _details[idx]['endTime'] = endStr;
          _details[idx]['isUserPinned'] = true;

          final int day = (_details[idx]['day'] as num?)?.toInt() ?? 1;

          // Fetch all items for this day
          final dayDetails = _details
              .where((d) => (d['day'] as num?)?.toInt() == day)
              .toList();

          int _getMin(dynamic item) {
            final String st = (item['startTime'] ?? '').toString();
            if (!st.contains(':')) return 99999;
            final parts = st.split(':');
            final h = int.tryParse(parts[0]) ?? 0;
            final m = int.tryParse(parts[1]) ?? 0;
            return h * 60 + m;
          }

          // Chronologically sort day items by startTime so cards set to earlier times jump up immediately
          dayDetails.sort((a, b) {
            final minA = _getMin(a);
            final minB = _getMin(b);
            if (minA != minB) return minA.compareTo(minB);
            return ((a['sortOrder'] as num?)?.toInt() ?? 0).compareTo(
              (b['sortOrder'] as num?)?.toInt() ?? 0,
            );
          });

          for (int i = 0; i < dayDetails.length; i++) {
            dayDetails[i]['sortOrder'] = i;
          }

          // Run timeline recalculation using the edited card as the center anchor
          final recalculatedDayItems = _recalculateDayTimeline(
            dayDetails,
            pinnedDetailId: detailIdStr,
            forceResetUnpinned: false,
          );

          for (int i = 0; i < recalculatedDayItems.length; i++) {
            final rItem = recalculatedDayItems[i];
            rItem['sortOrder'] = i;
            final itemIdx = _details.indexWhere(
              (d) =>
                  (d['id'] ?? '').toString() == (rItem['id'] ?? '').toString(),
            );
            if (itemIdx != -1) {
              _details[itemIdx]['startTime'] = rItem['startTime'];
              _details[itemIdx]['endTime'] = rItem['endTime'];
              _details[itemIdx]['sortOrder'] = i;
              if ((rItem['id'] ?? '').toString() == detailIdStr) {
                _details[itemIdx]['isUserPinned'] = true;
              }
            }
          }
          updatedDayItems = recalculatedDayItems;
        }
      } else {
        final idx = _savedPlaces.indexWhere((sp) => sp['id'] == detailId);
        if (idx != -1) {
          _savedPlaces[idx]['startTime'] = startStr;
          _savedPlaces[idx]['endTime'] = endStr;
        }
      }
    });

    _showPremiumNotification(
      title: 'Đã cập nhật & tự động sắp xếp vị trí',
      message: 'Thời gian: $startStr - $endStr',
      icon: Icons.access_time_rounded,
      color: AppTheme.primary,
    );

    if (isItineraryDetail && updatedDayItems.isNotEmpty) {
      final List<Future<bool>> futures = [];
      for (final item in updatedDayItems) {
        final itemId = item['id'] as int;
        futures.add(
          DatabaseService().updateItineraryDetail(itemId, {
            'startTime': item['startTime'],
            'endTime': item['endTime'],
            'sortOrder': item['sortOrder'],
            if ((item['id'] ?? '').toString() == detailIdStr)
              'isUserPinned': true,
          }),
        );
      }
      await Future.wait(futures);
    } else {
      await DatabaseService().updateSavedPlace(detailId, {
        'startTime': startStr,
        'endTime': endStr,
      });
    }
  }

  Widget _buildSavedPlaceCard(
    Map<String, dynamic> detail,
    int index, {
    bool isItineraryMode = false,
  }) {
    final int id = detail['id'] as int;
    final bool isCollapsed = !_expandedPlaceIds.contains(id);

    if (detail['place'] == null && detail['noteText'] != null) {
      final sectionDetails = _savedPlaces
          .where((d) => d['section'] == detail['section'])
          .toList();
      return Container(
        key: ValueKey('note_$id'),
        child: _buildSavedNoteCard(detail, index + 1, index, sectionDetails),
      );
    }

    final place = detail['place'] ?? {};
    final categoryName = place['category']?['name'] ?? 'Điểm tham quan';
    final String name = place['name'] ?? 'Địa điểm';
    final String image = place['image'] ?? '';
    final bool isVisited = _visitedDetailIds.contains(id);

    String? extraInfo;
    if (detail['startTime'] != null && detail['endTime'] != null) {
      extraInfo = '${detail['startTime']} - ${detail['endTime']}';
    } else if (detail['startTime'] != null) {
      extraInfo = '${detail['startTime']}';
    } else if (detail['endTime'] != null) {
      extraInfo = '${detail['endTime']}';
    }

    final placeCard = VisibilityDetector(
      key: Key("place_detector_${detail['id']}"),
      onVisibilityChanged: (info) {
        if (info.visibleFraction > 0.6) {
          if (_focusedPlaceId != detail['id']) {
            setState(() {
              _focusedPlaceId = detail['id'] as int?;
            });
            if (_isMapExpanded &&
                place['latitude'] != null &&
                place['longitude'] != null) {
              final lat = (place['latitude'] as num).toDouble();
              final lon = (place['longitude'] as num).toDouble();
              // Offset latitude by -0.005 so marker is in the upper visible half
              _mapController.move(LatLng(lat - 0.005, lon), 15.0);
            }
          }
        }
      },
      child: GestureDetector(
        onTap: () {
          if (_isSelectionMode && detail['id'] != null) {
            setState(() {
              if (_selectedItemIds.contains(id)) {
                _selectedItemIds.remove(id);
              } else {
                _selectedItemIds.add(id);
              }
            });
          } else {
            setState(() {
              if (isCollapsed) {
                _expandedPlaceIds.add(id);
              } else {
                _expandedPlaceIds.remove(id);
              }
            });
          }
