  Future<void> _offerManualReplacementForUnresolved(
    Map<String, dynamic> proposal,
  ) async {
    final unresolved = List<Map<String, dynamic>>.from(
      proposal['unresolved'] ?? [],
    );
    if (unresolved.isEmpty || !mounted) return;
    final actionable = unresolved
        .where((entry) => entry['requiresPrompt'] == true)
        .toList();
    if (actionable.isEmpty) return;
    final first = actionable.first;
    final detailId = (first['detailId'] as num?)?.toInt();
    if (detailId == null) return;
    final detail = _details.cast<Map<String, dynamic>?>().firstWhere(
      (item) => item?['id'] == detailId,
      orElse: () => null,
    );
    if (detail == null) return;
    if (_visitedDetailIds.contains(detailId) ||
        detail['isUserPinned'] == true) {
      return;
    }
    final placeName = first['place']?['name']?.toString() ?? 'địa điểm này';
    final wantsManual = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Cần yêu cầu thay thế'),
        content: Text(
          'Không tìm được phương án tự động phù hợp cho $placeName. '
          'Bạn có muốn nhập yêu cầu thay thế thủ công không?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Giữ nguyên'),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Nhập yêu cầu'),
          ),
        ],
      ),
    );
    if (wantsManual == true && mounted) {
      final reason = first['reason']?.toString().toLowerCase() ?? '';
      final environment = first['place']?['environmentType']
          ?.toString()
          .toUpperCase();
      final requireIndoor =
          first['requiresIndoor'] == true ||
          environment == 'OUTDOOR' ||
          reason.contains('mưa') ||
          reason.contains('ngoài trời');
      _showReplacementRequirementDialog(detail, requireIndoor: requireIndoor);
    }
  }

  // ================= TAB 1: TỔNG QUAN =================
  Map<String, dynamic>? _getNextLocation() {
    if (_details.isEmpty) return null;
    final List<Map<String, dynamic>> sortedDetails = List.from(_details);
    sortedDetails.sort((a, b) {
      final int dayA = (a['day'] as num?)?.toInt() ?? 1;
      final int dayB = (b['day'] as num?)?.toInt() ?? 1;
      if (dayA != dayB) {
        return dayA.compareTo(dayB);
      }
      final aStart = a['startTime']?.toString() ?? '';
      final bStart = b['startTime']?.toString() ?? '';
      final aHasTime = aStart.isNotEmpty;
      final bHasTime = bStart.isNotEmpty;

      if (aHasTime && !bHasTime) {
        return -1;
      } else if (!aHasTime && bHasTime) {
        return 1;
      } else if (aHasTime && bHasTime) {
        final aStartVal = _getSortableTimeValue(aStart);
        final bStartVal = _getSortableTimeValue(bStart);
        if (aStartVal != bStartVal) {
          return aStartVal.compareTo(bStartVal);
        }
      }
      final int orderA = (a['sortOrder'] as num?)?.toInt() ?? 0;
      final int orderB = (b['sortOrder'] as num?)?.toInt() ?? 0;
      if (orderA != orderB) {
        return orderA.compareTo(orderB);
      }
      final int idA = (a['id'] as num?)?.toInt() ?? 0;
      final int idB = (b['id'] as num?)?.toInt() ?? 0;
      return idA.compareTo(idB);
    });

    for (var detail in sortedDetails) {
      final isPlace = detail['place'] != null || detail['placeId'] != null;
      if (isPlace && !_visitedDetailIds.contains(detail['id'])) {
        return detail;
      }
    }
    return null;
  }

