  void _showAddPlaceBottomSheet(
    String sectionOrDay, [
    List<Map<String, dynamic>>? savedPlaces,
  ]) {
    if (!_checkCanEdit()) return;
    final searchController = TextEditingController();
    final bool isItinerary = sectionOrDay.startsWith('Ngày');
    bool showOnlyOpen = false;

    int visibleProminentCount = 15;
    int visibleSearchCount = 15;
    String lastQuery = "";

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (context) {
        return StatefulBuilder(
          builder: (context, setModalState) {
            final query = searchController.text.trim().toLowerCase();
            if (query != lastQuery) {
              visibleSearchCount = 15;
              lastQuery = query;
            }

            final List<Map<String, dynamic>> matchingPlaces = [];
            if (query.isNotEmpty) {
              final Set<int> seenIds = {};

              void checkAndAdd(Map<String, dynamic>? p) {
                if (p == null || p['id'] == null) return;
                final id = p['id'] as int;
                if (seenIds.contains(id)) return;

                final name = (p['name'] as String?)?.toLowerCase() ?? '';
                final address = (p['address'] as String?)?.toLowerCase() ?? '';
                if (name.contains(query) || address.contains(query)) {
                  seenIds.add(id);
                  matchingPlaces.add(Map<String, dynamic>.from(p));
                }
              }

              for (var p in _allPlaces) {
                checkAndAdd(p);
              }
              for (var sp in _savedPlaces) {
                checkAndAdd(sp['place'] as Map<String, dynamic>?);
              }
              if (savedPlaces != null) {
                for (var p in savedPlaces) {
                  checkAndAdd(p);
                }
              }
            }

            List<Map<String, dynamic>> itinerarySectionItems = [];
            if (query.isEmpty && isItinerary) {
              final Set<int> existingDayPlaceIds = {};
              final int? dayNum = int.tryParse(
                sectionOrDay.replaceAll(RegExp(r'[^0-9]'), ''),
              );
              if (dayNum != null) {
                for (var d in _details) {
                  if (d['day'] == dayNum && d['placeId'] != null) {
                    existingDayPlaceIds.add(d['placeId'] as int);
                  }
                }
              }

              final Map<String, List<Map<String, dynamic>>> grouped = {};
              final sourceList = (savedPlaces != null && savedPlaces.isNotEmpty)
                  ? savedPlaces
                  : _savedPlaces;

              for (var item in sourceList) {
                final bool isPlace =
                    item['place'] != null || item['placeId'] != null;
                if (!isPlace) continue;

                final Map<String, dynamic>? p = item['place'] != null
                    ? item['place'] as Map<String, dynamic>?
                    : item;
                final String sec =
                    (item['section_name'] ??
                            item['section'] ??
                            'Điểm tham quan')
                        .toString();

                if (p != null && p['id'] != null) {
                  final targetDate = _getDateForDayLabel(sectionOrDay);
                  if (showOnlyOpen &&
                      !TimeUtils.isPlaceOpenOnDate(
                        p['openingHours'],
                        targetDate,
                      )) {
                    continue;
                  }
                  final int pId = p['id'] as int;
                  final pCopy = Map<String, dynamic>.from(p);
                  pCopy['section_name'] = sec;
                  pCopy['is_added_to_day'] = existingDayPlaceIds.contains(pId);
                  grouped.putIfAbsent(sec, () => []).add(pCopy);
                }
              }

              final List<String> allSecNames = List.from(_sectionNames);
              for (var k in grouped.keys) {
                if (!allSecNames.contains(k)) {
                  allSecNames.add(k);
                }
              }

              for (var secName in allSecNames) {
                final places = grouped[secName] ?? [];
                itinerarySectionItems.add({
                  'type': 'section_header',
                  'section_name': secName,
                  'count': places.length,
                });
                if (places.isEmpty) {
                  itinerarySectionItems.add({
                    'type': 'empty_section',
                    'section_name': secName,
                  });
                } else {
                  for (var p in places) {
                    itinerarySectionItems.add({
                      'type': 'place_item',
                      'place': p,
                    });
                  }
                }
              }
            }

            final targetDate = _getDateForDayLabel(sectionOrDay);

            final List<Map<String, dynamic>> prominentPlaces =
                _cachedProminentPlaces.isNotEmpty
                ? _cachedProminentPlaces
                : _allPlaces;

            final List<Map<String, dynamic>> filteredProminent = showOnlyOpen
                ? prominentPlaces
                      .where(
                        (p) => TimeUtils.isPlaceOpenOnDate(
                          p['openingHours'],
                          targetDate,
                        ),
                      )
                      .toList()
                : prominentPlaces;

            final List<Map<String, dynamic>> filteredMatching = showOnlyOpen
                ? matchingPlaces
                      .where(
                        (p) => TimeUtils.isPlaceOpenOnDate(
                          p['openingHours'],
                          targetDate,
                        ),
                      )
                      .toList()
                : matchingPlaces;

            final List<Map<String, dynamic>> sortedProminent = List.from(
              filteredProminent,
            );
            sortedProminent.sort((a, b) {
              final aOpen = TimeUtils.isPlaceOpenOnDate(
                a['openingHours'],
                targetDate,
              );
              final bOpen = TimeUtils.isPlaceOpenOnDate(
                b['openingHours'],
                targetDate,
              );
              if (aOpen && !bOpen) return -1;
              if (!aOpen && bOpen) return 1;
              return 0;
            });

            final List<Map<String, dynamic>> sortedMatching = List.from(
              filteredMatching,
            );
            sortedMatching.sort((a, b) {
              final aOpen = TimeUtils.isPlaceOpenOnDate(
                a['openingHours'],
                targetDate,
              );
              final bOpen = TimeUtils.isPlaceOpenOnDate(
                b['openingHours'],
                targetDate,
              );
              if (aOpen && !bOpen) return -1;
              if (!aOpen && bOpen) return 1;
              return 0;
            });

            final List<Map<String, dynamic>> displayProminent = sortedProminent
                .take(visibleProminentCount)
                .toList();
            final List<Map<String, dynamic>> displayMatching = sortedMatching
                .take(visibleSearchCount)
                .toList();

            return SafeArea(
              child: Padding(
                padding: EdgeInsets.only(
                  bottom: MediaQuery.of(context).viewInsets.bottom,
                ),
                child: Container(
                  height: MediaQuery.of(context).size.height * 0.75,
                  padding: const EdgeInsets.symmetric(
                    horizontal: 20,
                    vertical: 12,
                  ),
                  child: Column(
                    children: [
                      Center(
                        child: Container(
                          width: 40,
                          height: 4,
                          margin: const EdgeInsets.only(bottom: 16),
                          decoration: BoxDecoration(
                            color: Colors.grey[300],
                            borderRadius: BorderRadius.circular(2),
                          ),
                        ),
                      ),
                      Text(
                        'Thêm địa điểm',
                        style: TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.bold,
                          color: AppTheme.darkText,
                        ),
                      ),
                      const SizedBox(height: 16),
                      Row(
                        children: [
                          Expanded(
                            child: Container(
                              decoration: BoxDecoration(
                                color: const Color(0xFFF1F5F9),
                                borderRadius: BorderRadius.circular(16),
                              ),
                              child: TextField(
                                controller: searchController,
                                onChanged: (val) {
                                  setModalState(() {});
                                },
                                style: TextStyle(
                                  fontSize: 14,
                                  color: AppTheme.darkText,
                                ),
                                decoration: InputDecoration(
                                  hintText: 'Tìm kiếm theo tên hoặc địa chỉ',
                                  hintStyle: TextStyle(
                                    color: Colors.grey[400],
                                    fontSize: 14,
                                  ),
                                  border: InputBorder.none,
                                  contentPadding: const EdgeInsets.symmetric(
                                    horizontal: 16,
                                    vertical: 14,
                                  ),
                                  suffixIcon: searchController.text.isNotEmpty
                                      ? GestureDetector(
                                          onTap: () {
                                            searchController.clear();
                                            setModalState(() {});
                                          },
                                          child: Container(
                                            margin: const EdgeInsets.all(10),
                                            decoration: BoxDecoration(
                                              color: Colors.grey[300],
                                              shape: BoxShape.circle,
                                            ),
                                            child: const Icon(
                                              Icons.close_rounded,
                                              size: 16,
                                              color: Colors.white,
                                            ),
                                          ),
                                        )
                                      : null,
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(width: 10),
                          GestureDetector(
                            onTap: () {
                              setModalState(() {
                                showOnlyOpen = !showOnlyOpen;
                              });
                            },
                            child: AnimatedContainer(
                              duration: const Duration(milliseconds: 200),
                              width: 48,
                              height: 48,
                              decoration: BoxDecoration(
                                color: const Color(0xFFF1F5F9),
                                borderRadius: BorderRadius.circular(16),
                              ),
                              child: Stack(
                                alignment: Alignment.center,
                                children: [
                                  Icon(
                                    Icons.lock_clock_rounded,
                                    color: Colors.grey[600],
                                    size: 22,
                                  ),
                                  if (showOnlyOpen)
                                    Positioned.fill(
                                      child: CustomPaint(
                                        painter: RedSlashPainter(),
                                      ),
                                    ),
                                ],
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 16),
                      Expanded(
                        child: query.isEmpty
                            ? NotificationListener<ScrollNotification>(
                                onNotification:
                                    (ScrollNotification scrollInfo) {
                                      if (scrollInfo.metrics.pixels >=
                                          scrollInfo.metrics.maxScrollExtent -
                                              200) {
                                        if (visibleProminentCount <
                                            prominentPlaces.length) {
                                          setModalState(() {
                                            visibleProminentCount += 15;
                                          });
                                        }
                                      }
                                      return true;
                                    },
                                child: ListView.builder(
                                  itemCount:
                                      (displayProminent.isNotEmpty
                                          ? (displayProminent.length + 1)
                                          : 0) +
                                      1,
                                  itemBuilder: (context, idx) {
                                    final bool hasQuick = false;

                                    final int quickOffset = hasQuick
                                        ? (itinerarySectionItems.length + 1)
                                        : 0;
                                    final int prominentHeaderIdx = quickOffset;
                                    final int prominentStartIdx =
                                        prominentHeaderIdx + 1;
                                    final int prominentCount =
                                        displayProminent.length;
                                    final int footerIdx =
                                        quickOffset +
                                        (displayProminent.isNotEmpty
                                            ? (prominentCount + 1)
                                            : 0);

                                    if (hasQuick && idx == 0) {
                                      return Padding(
                                        padding: const EdgeInsets.only(
                                          bottom: 4,
                                          top: 4,
                                        ),
                                        child: Row(
                                          children: [
                                            const Icon(
                                              Icons
                                                  .collections_bookmark_rounded,
                                              color: Color(0xFF5C5CFF),
                                              size: 18,
                                            ),
                                            const SizedBox(width: 6),
                                            Text(
                                              'Địa điểm từ các Danh Sách Tổng Quan',
                                              style: TextStyle(
                                                fontSize: 14,
                                                fontWeight: FontWeight.bold,
                                                color: AppTheme.darkText,
                                              ),
                                            ),
                                          ],
                                        ),
                                      );
                                    }

                                    if (hasQuick &&
                                        idx > 0 &&
                                        idx < quickOffset) {
                                      final item =
                                          itinerarySectionItems[idx - 1];
                                      final String itemType =
                                          item['type'] ?? 'place_item';

                                      if (itemType == 'section_header') {
                                        return Container(
                                          margin: const EdgeInsets.only(
                                            top: 14,
                                            bottom: 6,
                                          ),
                                          padding: const EdgeInsets.symmetric(
                                            horizontal: 12,
                                            vertical: 8,
                                          ),
                                          decoration: BoxDecoration(
                                            color: const Color(0xFFF8FAFC),
                                            borderRadius: BorderRadius.circular(
                                              10,
                                            ),
                                            border: Border.all(
                                              color: const Color(0xFFE2E8F0),
                                            ),
                                          ),
                                          child: Row(
                                            children: [
                                              const Icon(
                                                Icons.folder_special_rounded,
                                                color: Color(0xFF5C5CFF),
                                                size: 18,
                                              ),
                                              const SizedBox(width: 8),
                                              Text(
                                                item['section_name'],
                                                style: TextStyle(
                                                  fontSize: 14,
                                                  fontWeight: FontWeight.bold,
                                                  color: AppTheme.darkText,
                                                ),
                                              ),
                                              const SizedBox(width: 4),
                                              if (false)
                                                _buildCardActionIcon(
                                                  icon:
                                                      item['incidentReport'] !=
                                                          null
                                                      ? Icons.warning_rounded
                                                      : Icons
                                                            .warning_amber_rounded,
                                                  active:
                                                      item['incidentReport'] !=
                                                      null,
                                                  badge:
                                                      item['incidentReport'] !=
                                                          null
                                                      ? '!'
                                                      : null,
                                                  onTap: () =>
                                                      _showPlaceIncidentReportSheet(
                                                        item,
                                                      ),
                                                ),
                                              const Spacer(),
                                              Container(
                                                padding:
                                                    const EdgeInsets.symmetric(
                                                      horizontal: 8,
                                                      vertical: 2,
                                                    ),
                                                decoration: BoxDecoration(
                                                  color: const Color(
                                                    0xFFE2E8F0,
                                                  ),
                                                  borderRadius:
                                                      BorderRadius.circular(12),
