                              if (detail['todoItems'] is List &&
                                  (detail['todoItems'] as List).isNotEmpty)
                                Padding(
                                  padding: const EdgeInsets.fromLTRB(
                                    12,
                                    0,
                                    12,
                                    10,
                                  ),
                                  child: _buildInlinePlaceChecklistPreview(
                                    detail,
                                  ),
                                ),
                            ],
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        );

        Widget? travelSeparator;
        // Render travel separator at the bottom of item `idx` IF AND ONLY IF the next item (`idx + 1`) is a Place
        if (idx + 1 < dayDetails.length &&
            dayDetails[idx + 1]['place'] != null) {
          final nextPlaceRaw =
              dayDetails[idx + 1]['place'] as Map<String, dynamic>;
          Map<String, dynamic>? prevPlaceRaw;
          for (int j = idx; j >= 0; j--) {
            if (dayDetails[j]['place'] != null) {
              prevPlaceRaw = dayDetails[j]['place'] as Map<String, dynamic>?;
              break;
            }
          }
          if (prevPlaceRaw != null) {
            travelSeparator = _buildTravelSeparator(
              Map<String, dynamic>.from(prevPlaceRaw),
              Map<String, dynamic>.from(nextPlaceRaw),
            );
          }
        }

        bool hasPrevPlace = false;
        for (int j = idx - 1; j >= 0; j--) {
          if (dayDetails[j]['place'] != null) {
            hasPrevPlace = true;
            break;
          }
        }

        bool hasNextPlace = false;
        for (int j = idx + 1; j < dayDetails.length; j++) {
          if (dayDetails[j]['place'] != null) {
            hasNextPlace = true;
            break;
          }
        }

        final contentWidget = Container(
          child: Stack(
            children: [
              // Top line (for Place)
              if (detail['place'] != null && hasPrevPlace)
                Positioned(
                  top: 0,
                  height: 24,
                  left: 15,
                  child: Container(
                    width: 2,
                    color: isVisited
                        ? const Color(0xFF10B981).withOpacity(0.5)
                        : customColor.withOpacity(0.3),
                  ),
                ),
              // Bottom line (for Place)
              if (detail['place'] != null && hasNextPlace)
                Positioned(
                  top: 36,
                  bottom: 0,
                  left: 15,
                  child: Container(
                    width: 2,
                    color: isVisited
                        ? const Color(0xFF10B981).withOpacity(0.5)
                        : customColor.withOpacity(0.3),
                  ),
                ),
              // Numbered Circle / Check Marker (for Place Timeline marker)
              if (detail['place'] != null)
                Positioned(
                  top: 16,
                  left: 2,
                  child: Container(
                    width: 28,
                    height: 28,
                    decoration: BoxDecoration(
                      color: isVisited ? const Color(0xFF10B981) : customColor,
                      shape: BoxShape.circle,
                      border: Border.all(color: Colors.white, width: 2),
                    ),
                    alignment: Alignment.center,
                    child: isVisited
                        ? const Icon(
                            Icons.check_rounded,
                            color: Colors.white,
                            size: 15,
                          )
                        : Text(
                            (() {
                              int placeNumber = 0;
                              for (int i = 0; i <= idx; i++) {
                                if (sortedDayDetails[i]['place'] != null) {
                                  placeNumber++;
                                }
                              }
                              return '$placeNumber';
                            })(),
                            style: const TextStyle(
                              color: Colors.white,
                              fontWeight: FontWeight.bold,
                              fontSize: 12,
                            ),
                          ),
                  ),
                ),
              // Continuous line (for Note)
              if (detail['place'] == null && hasPrevPlace && hasNextPlace)
                Positioned(
                  top: 0,
                  bottom: 0,
                  left: 15,
                  child: Container(
                    width: 2,
                    color: customColor.withOpacity(0.3),
                  ),
                ),
              // The content
              Padding(
                padding: const EdgeInsets.only(left: 32),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    card,
                    if (travelSeparator != null) travelSeparator,
                  ],
                ),
              ),
            ],
          ),
        );

        return Container(
          key: ValueKey('item_$id'),
          child: isVisited
              ? contentWidget
              : ReorderableDelayedDragStartListener(
                  index: idx,
                  child: contentWidget,
                ),
        );
      }),
    );
  }

  Widget _buildItineraryTab() {
    final int totalDays = (_itineraryData['days'] as num?)?.toInt() ?? 1;

    // Build the horizontal chips bar
    final Widget horizontalBar = Container(
      height: 60,
      color: Colors.white,
      padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 16),
      child: ListView(
        scrollDirection: Axis.horizontal,
        children: [
          // Edit Calendar Button
          GestureDetector(
            onTap: _changeTripStartDate,
            child: Container(
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: AppTheme.darkText,
                shape: BoxShape.circle,
              ),
              child: const Icon(
                Icons.calendar_today_rounded,
                color: Colors.white,
                size: 18,
              ),
            ),
          ),
          const SizedBox(width: 12),
          // Day Chips
          ...List.generate(totalDays, (index) {
            final isSelected = _activeDayIndex == index;
            final label = _getDayLabel(index);
            final dayDetails = _details
                .where((d) => d['day'] == (index + 1))
                .toList();
            final bool isCompletedDay =
                dayDetails.isNotEmpty &&
                dayDetails.every((d) => _visitedDetailIds.contains(d['id']));
            final bool isInProgressDay =
                !isCompletedDay &&
                dayDetails.any((d) => _visitedDetailIds.contains(d['id']));

            return Padding(
              padding: const EdgeInsets.only(right: 8.0),
              child: GestureDetector(
                onTap: () async {
                  _isProgrammaticScrolling = true;
                  setState(() {
                    _activeDayIndex = index;
                    _dayCollapsed[index] =
                        false; // Auto-expand day if collapsed
                  });

                  if (_itineraryScrollController.hasClients) {
                    final key = _dayKeys[index];
                    if (key?.currentContext != null) {
                      await Scrollable.ensureVisible(
                        key!.currentContext!,
                        duration: const Duration(milliseconds: 300),
                        curve: Curves.easeInOut,
                        alignment: 0.0,
                      );
                    } else {
                      // Calculate exact cumulative height offset based on preceding days & place counts
                      double calculatedOffset = 0.0;
                      for (int k = 0; k < index; k++) {
                        final placesCount = _details
                            .where((d) => d['day'] == (k + 1))
                            .length;
                        final isCollapsed = _dayCollapsed[k] == true;
                        if (isCollapsed) {
                          calculatedOffset += 90.0;
                        } else {
                          calculatedOffset += 160.0 + (placesCount * 360.0);
                        }
                      }

                      final double maxExtent =
                          _itineraryScrollController.position.maxScrollExtent;
                      final double targetOffset = calculatedOffset.clamp(
                        0.0,
                        maxExtent,
                      );

                      _itineraryScrollController.jumpTo(targetOffset);

                      await WidgetsBinding.instance.endOfFrame;
                      await Future.delayed(const Duration(milliseconds: 50));
                      final updatedKey = _dayKeys[index];
                      if (updatedKey?.currentContext != null) {
                        await Scrollable.ensureVisible(
                          updatedKey!.currentContext!,
                          duration: const Duration(milliseconds: 250),
                          curve: Curves.easeInOut,
                          alignment: 0.0,
                        );
                      }
                    }
                  }
                  Future.delayed(const Duration(milliseconds: 400), () {
                    _isProgrammaticScrolling = false;
                  });
                },
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 8,
                  ),
                  decoration: BoxDecoration(
                    color: isSelected ? AppTheme.darkText : Colors.grey[100],
                    borderRadius: BorderRadius.circular(20),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      if (isCompletedDay) ...[
                        Icon(
                          Icons.check_circle_rounded,
                          size: 14,
                          color: isSelected
                              ? Colors.greenAccent
                              : const Color(0xFF10B981),
                        ),
                        const SizedBox(width: 5),
                      ] else if (isInProgressDay) ...[
                        Icon(
                          Icons.check_circle_outline_rounded,
                          size: 14,
                          color: isSelected
                              ? Colors.lightBlueAccent
                              : AppTheme.primary,
                        ),
                        const SizedBox(width: 5),
                      ],
                      Text(
                        label,
                        style: TextStyle(
                          color: isSelected ? Colors.white : AppTheme.darkText,
                          fontWeight: FontWeight.bold,
                          fontSize: 13,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            );
          }),
        ],
      ),
    );

    // Build the vertical days list
    return Column(
      children: [
        horizontalBar,
        Expanded(
          child: Listener(
            onPointerDown: (event) {
              if (_isReordering) {
                _dragPointerY = event.position.dy;
              }
            },
            onPointerMove: (event) {
              if (_isReordering) {
                _dragPointerY = event.position.dy;
              }
            },
            onPointerUp: (event) {
              _stopAutoScrollTimer();
            },
            onPointerCancel: (event) {
              _stopAutoScrollTimer();
            },
            child: ListView.builder(
              controller: _itineraryScrollController,
              padding: const EdgeInsets.only(bottom: 80),
              itemCount: totalDays,
              itemBuilder: (context, index) {
                final dayLabel = 'Ngày ${index + 1}';
                final dayDetails = _details
                    .where((d) => d['day'] == (index + 1))
                    .toList();
                final daySavedItems = _savedPlaces
                    .where(
                      (d) => d['section'] == dayLabel && d['noteText'] != null,
                    )
                    .toList();
                final dayKey = _dayKeys.putIfAbsent(index, () => GlobalKey());
                final customColor =
                    _dayColors[index] ??
                    _availableColors[index % _availableColors.length];
                final subtitle = _daySubtitles[index] ?? '';
                final isCollapsed = _dayCollapsed[index] == true;

                return Container(
                  key: dayKey,
                  margin: const EdgeInsets.only(bottom: 12),
                  color: Colors.white,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // Gray separator before this day card (except first)
                      if (index > 0)
                        Container(height: 10, color: Colors.grey[100]),

                      Padding(
                        padding: const EdgeInsets.all(16.0),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              crossAxisAlignment: CrossAxisAlignment.center,
                              children: [
                                GestureDetector(
                                  behavior: HitTestBehavior.opaque,
                                  onTap: () {
                                    setState(() {
                                      _dayCollapsed[index] = !isCollapsed;
                                    });
                                  },
                                  child: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      Icon(
                                        isCollapsed
                                            ? Icons.keyboard_arrow_right_rounded
                                            : Icons.keyboard_arrow_down_rounded,
                                        color: AppTheme.darkText,
                                      ),
                                      const SizedBox(width: 8),
                                      Text(
                                        _getDayLabel(index),
                                        style: TextStyle(
                                          fontSize: 26,
                                          fontWeight: FontWeight.w800,
                                          color: AppTheme.darkText,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                                const SizedBox(width: 12),
                                Expanded(
                                  child: _editingDaySubtitleIndex == index
                                      ? TextField(
                                          controller: _daySubtitleControllers
                                              .putIfAbsent(
                                                index,
                                                () => TextEditingController(
                                                  text: subtitle,
                                                ),
                                              ),
                                          focusNode: _daySubtitleFocusNodes
                                              .putIfAbsent(
                                                index,
                                                () => FocusNode(),
                                              ),
                                          style: TextStyle(
                                            fontSize: 14,
                                            color: AppTheme.darkText,
                                            fontWeight: FontWeight.w500,
                                          ),
                                          decoration: const InputDecoration(
                                            isDense: true,
                                            contentPadding: EdgeInsets.zero,
                                            border: InputBorder.none,
                                            enabledBorder: InputBorder.none,
                                            focusedBorder: InputBorder.none,
                                            disabledBorder: InputBorder.none,
                                            focusedErrorBorder:
                                                InputBorder.none,
                                            errorBorder: InputBorder.none,
                                            hintText: 'Thêm tiêu đề phụ',
                                            hintStyle: TextStyle(
                                              fontSize: 14,
                                              color: Colors.grey,
                                              fontWeight: FontWeight.normal,
                                            ),
                                          ),
                                          onSubmitted: (newValue) =>
                                              _saveDaySubtitleInline(
                                                index,
                                                newValue,
                                              ),
                                          onTapOutside: (_) =>
                                              _saveDaySubtitleInline(
                                                index,
                                                _daySubtitleControllers[index]
                                                        ?.text ??
                                                    '',
                                              ),
                                        )
                                      : GestureDetector(
                                          behavior: HitTestBehavior.opaque,
                                          onTap: () =>
                                              _startEditingDaySubtitle(index),
                                          child: Padding(
                                            padding: const EdgeInsets.symmetric(
                                              vertical: 8.0,
                                            ),
                                            child: Text(
                                              subtitle.isNotEmpty
                                                  ? subtitle
                                                  : 'Thêm tiêu đề phụ',
                                              style: TextStyle(
                                                fontSize: 14,
                                                color: subtitle.isNotEmpty
                                                    ? AppTheme.darkText
                                                    : Colors.grey[400],
                                                fontWeight: subtitle.isNotEmpty
                                                    ? FontWeight.w500
                                                    : FontWeight.normal,
                                              ),
                                              maxLines: 1,
                                              overflow: TextOverflow.ellipsis,
                                            ),
                                          ),
                                        ),
                                ),
                                IconButton(
                                  icon: Icon(
                                    Icons.more_horiz_rounded,
                                    color: AppTheme.subtitleText,
                                  ),
                                  onPressed: () => _showDayOptionsSheet(index),
                                ),
                              ],
                            ),
                            const SizedBox(height: 8),

                            if (!isCollapsed) ...[
                              Builder(
                                builder: (context) {
                                  final bool isAiTrip =
                                      _itineraryData['isAiGenerated'] == true ||
                                      _itineraryData['isAiTrip'] == true ||
                                      _itineraryData['isAi'] == true ||
                                      (_itineraryData['title'] ?? '')
                                          .toString()
                                          .toLowerCase()
                                          .contains('ai');

                                  final placesOnly = dayDetails
                                      .where(
                                        (d) =>
                                            d['placeId'] != null &&
                                            d['place'] != null,
                                      )
                                      .toList();
                                  final placesCount = placesOnly.length;

                                  if (placesCount == 0) {
                                    return const SizedBox.shrink();
                                  }

                                  String subText = '';
                                  if (placesCount >= 2) {
                                    int totalDuration = 0;
                                    double totalDistance = 0;
                                    for (
                                      int i = 0;
                                      i < placesOnly.length - 1;
                                      i++
                                    ) {
                                      final p1 = Map<String, dynamic>.from(
                                        placesOnly[i]['place'] as Map,
                                      );
                                      final p2 = Map<String, dynamic>.from(
                                        placesOnly[i + 1]['place'] as Map,
                                      );
                                      final info = _getMockTravelInfo(p1, p2);
                                      totalDuration += info['duration'] as int;
                                      final dist =
                                          double.tryParse(
                                            (info['distance'] as String)
                                                .replaceAll(',', '.'),
                                          ) ??
                                          0.0;
                                      totalDistance += dist;
                                    }
                                    subText =
                                        ' · $totalDuration phút, ${totalDistance.toStringAsFixed(1).replaceAll('.', ',')} km';
                                  }

                                  final isOptimizing = _optimizingDayNumbers
                                      .contains(index + 1);
                                  return Material(
                                    color: Colors.transparent,
                                    child: InkWell(
                                      onTap: isOptimizing
                                          ? null
                                          : () => _optimizeDay(index),
                                      borderRadius: BorderRadius.circular(13),
                                      child: Ink(
                                        width: double.infinity,
                                        padding: const EdgeInsets.symmetric(
                                          horizontal: 13,
                                          vertical: 10,
                                        ),
                                        decoration: BoxDecoration(
                                          color: isOptimizing
                                              ? const Color(0xFF64748B)
                                              : const Color(0xFF2563EB),
                                          borderRadius: BorderRadius.circular(
                                            13,
                                          ),
                                          boxShadow: [
                                            BoxShadow(
                                              color: const Color(
                                                0xFF2563EB,
                                              ).withAlpha(42),
                                              blurRadius: 12,
                                              offset: const Offset(0, 4),
                                            ),
                                          ],
                                        ),
                                        child: Row(
                                          children: [
                                            isOptimizing
                                                ? const SizedBox(
                                                    width: 17,
                                                    height: 17,
                                                    child:
                                                        CircularProgressIndicator(
                                                          strokeWidth: 2,
                                                          color: Colors.white,
                                                        ),
                                                  )
                                                : const Icon(
                                                    Icons.auto_awesome_rounded,
                                                    color: Colors.white,
                                                    size: 18,
                                                  ),
                                            const SizedBox(width: 8),
                                            Expanded(
                                              child: Text(
                                                isOptimizing
                                                    ? 'Đang tối ưu lịch trình...'
                                                    : 'Tối ưu ngay',
                                                maxLines: 1,
                                                overflow: TextOverflow.ellipsis,
                                                style: const TextStyle(
                                                  color: Colors.white,
                                                  fontSize: 13,
                                                  fontWeight: FontWeight.w800,
                                                ),
                                              ),
                                            ),
                                            if (!isOptimizing &&
                                                subText.isNotEmpty)
                                              Flexible(
                                                child: Text(
                                                  subText.replaceFirst(
                                                    ' · ',
                                                    '',
                                                  ),
                                                  maxLines: 1,
                                                  overflow:
                                                      TextOverflow.ellipsis,
                                                  textAlign: TextAlign.right,
                                                  style: const TextStyle(
                                                    color: Color(0xFFDBEAFE),
                                                    fontSize: 10.5,
                                                    fontWeight: FontWeight.w600,
                                                  ),
                                                ),
                                              ),
                                          ],
                                        ),
                                      ),
                                    ),
                                  );
                                },
                              ),
                              const SizedBox(height: 16),

                              // Day details Column (replaces _buildDayListView)
                              if (dayDetails.isNotEmpty) ...[
                                _buildDayDetailsColumn(dayDetails, customColor),
                                const SizedBox(height: 16),
                              ],

                              // Day notes and checklists
                              if (daySavedItems.isNotEmpty) ...[
                                ...List.generate(daySavedItems.length, (sIdx) {
                                  final detail = daySavedItems[sIdx];
                                  return _buildSavedNoteCard(
                                    detail,
                                    sIdx + 1,
                                    sIdx,
                                    daySavedItems,
                                  );
                                }),
                                const SizedBox(height: 16),
                              ],

                              // Search & Options Input Row (Moved to bottom)
                              Builder(
                                builder: (context) {
                                  final bool isAiTrip =
                                      _itineraryData['isAiGenerated'] == true ||
                                      _itineraryData['isAiTrip'] == true ||
                                      (_itineraryData['title'] ?? '')
                                          .toString()
                                          .toLowerCase()
                                          .contains('ai');

                                  if (isAiTrip) {
                                    return const SizedBox.shrink();
                                  }

                                  return Row(
                                    children: [
                                      // Input Box (Add Location button)
                                      Expanded(
                                        child: _buildPopupMenuAddPlaceButton(
                                          dayLabel,
                                          customColor,
                                        ),
                                      ),
                                    ],
                                  );
                                },
                              ),
                            ],
                          ],
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
          ),
        ),
      ],
    );
  }

  // ================= TAB 3: KHÁM PHÁ =================
  Widget _buildExploreTab() {
    if ((_isLoadingExplore || !_hasFetchedExplore) && _explorePosts.isEmpty) {
      return const Center(
        child: CircularProgressIndicator(color: AppTheme.primary),
      );
    }

    final destination = _itineraryData['destination'] ?? 'Cần Thơ';

    final filteredPosts = _explorePosts.where((post) {
      if (_exploreSearchQuery.isEmpty) return true;
      final q = _exploreSearchQuery.toLowerCase();
      final title = (post['title'] ?? '').toString().toLowerCase();
      final desc = (post['description'] ?? post['content'] ?? '')
          .toString()
          .toLowerCase();
      final authorName =
          (post['user']?['name'] ?? post['author']?['name'] ?? '')
              .toString()
              .toLowerCase();

      bool matchesPlace = false;
      if (post['items'] is List) {
        for (var item in (post['items'] as List)) {
          final pName = (item['place']?['name'] ?? '').toString().toLowerCase();
          if (pName.contains(q)) {
            matchesPlace = true;
            break;
          }
        }
      }

      return title.contains(q) ||
          desc.contains(q) ||
          authorName.contains(q) ||
          matchesPlace;
    }).toList();

    return CustomScrollView(
      physics: const BouncingScrollPhysics(),
      slivers: [
        SliverToBoxAdapter(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 20),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // Section Title Header
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      'Khám phá $destination',
                      style: TextStyle(
                        fontSize: 20,
                        fontWeight: FontWeight.w800,
                        color: AppTheme.darkText,
                        letterSpacing: -0.5,
                      ),
                    ),
                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 4,
                      ),
                      decoration: BoxDecoration(
                        color: AppTheme.primaryContainer.withAlpha(120),
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: Row(
                        children: [
                          Icon(
                            Icons.stars_rounded,
                            color: AppTheme.primary,
                            size: 14,
                          ),
                          const SizedBox(width: 4),
                          Text(
                            'Gợi ý',
                            style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.bold,
                              color: AppTheme.primary,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 12),

                // Floating Search Pill
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 14,
                    vertical: 2,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(
                      color: AppTheme.border.withAlpha(180),
                      width: 1,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withAlpha(8),
                        blurRadius: 12,
                        offset: const Offset(0, 4),
                      ),
                    ],
                  ),
                  child: Row(
                    children: [
                      const Icon(
                        Icons.search_rounded,
                        color: AppTheme.primary,
                        size: 20,
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: TextField(
                          controller: _exploreSearchController,
                          onChanged: (val) {
                            setState(() {
                              _exploreSearchQuery = val.trim();
                            });
                          },
                          decoration: InputDecoration(
                            hintText: 'Tìm kiếm bài viết ở $destination...',
                            hintStyle: TextStyle(
                              color: AppTheme.subtitleText,
                              fontSize: 14,
                              fontWeight: FontWeight.w400,
                            ),
                            filled: false,
                            fillColor: Colors.transparent,
                            border: InputBorder.none,
                            enabledBorder: InputBorder.none,
                            focusedBorder: InputBorder.none,
                            errorBorder: InputBorder.none,
                            disabledBorder: InputBorder.none,
                            isDense: true,
                            contentPadding: const EdgeInsets.symmetric(
                              vertical: 10,
                            ),
                          ),
                          style: TextStyle(
                            color: AppTheme.darkText,
                            fontSize: 14,
                            fontWeight: FontWeight.w500,
                          ),
                        ),
                      ),
                      if (_exploreSearchQuery.isNotEmpty)
                        GestureDetector(
                          onTap: () {
                            setState(() {
                              _exploreSearchController.clear();
                              _exploreSearchQuery = '';
                            });
                          },
                          child: Padding(
                            padding: const EdgeInsets.only(right: 6),
                            child: Icon(
                              Icons.clear_rounded,
                              color: Colors.grey.shade400,
                              size: 18,
                            ),
                          ),
                        ),
                      Container(
                        padding: const EdgeInsets.all(4),
                        decoration: BoxDecoration(
                          color: Colors.grey.shade100,
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: Icon(
                          Icons.tune_rounded,
                          color: AppTheme.subtitleText,
                          size: 16,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),

        // Posts List
        if (filteredPosts.isEmpty && _hasFetchedExplore)
          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.all(40.0),
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Container(
                    padding: const EdgeInsets.all(16),
                    decoration: BoxDecoration(
                      color: AppTheme.primaryContainer.withAlpha(80),
                      shape: BoxShape.circle,
                    ),
                    child: Icon(
                      _exploreSearchQuery.isNotEmpty
                          ? Icons.search_off_rounded
                          : Icons.explore_off_rounded,
                      size: 40,
                      color: AppTheme.primary.withAlpha(180),
                    ),
                  ),
                  const SizedBox(height: 16),
                  Text(
                    _exploreSearchQuery.isNotEmpty
                        ? 'Không tìm thấy bài viết phù hợp'
                        : 'Chưa có bài viết khám phá nào',
                    style: TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.bold,
                      color: AppTheme.darkText,
                    ),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    _exploreSearchQuery.isNotEmpty
                        ? 'Thử tìm kiếm với từ khóa khác xem sao nhé!'
                        : 'Hãy quay lại sau để cập nhật các kinh nghiệm mới nhất nhé!',
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      fontSize: 13,
                      color: AppTheme.subtitleText,
                    ),
                  ),
                ],
              ),
            ),
          )
        else
          SliverPadding(
            padding: EdgeInsets.fromLTRB(
              16,
              0,
              16,
              80 + MediaQuery.of(context).padding.bottom,
            ),
            sliver: SliverList(
              delegate: SliverChildBuilderDelegate((context, index) {
                final post = filteredPosts[index];
                return ExplorePostCard(
                  post: post,
                  onTap: () {
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (context) => ExplorePostDetailScreen(
                          postId: post['id'] as int,
                          title: post['title'] ?? 'Chi tiết',
                          initialItinerary: {
                            ..._itineraryData,
                            'savedPlaces': _savedPlaces,
                            'details': _details,
                          },
                        ),
                      ),
                    ).then((_) {
                      _fetchExplorePosts();
                    });
                  },
                );
              }, childCount: filteredPosts.length),
            ),
          ),
      ],
    );
  }

  // ================= TAB 4: CHI PHÍ ($) =================
  IconData _getCategoryIconData(String catName, {int? iconCode}) {
    if (iconCode != null && iconCode > 0) {
      return IconData(iconCode, fontFamily: 'MaterialIcons');
    }
    if (_searchCategories.isNotEmpty) {
      final String trimmedName = catName.trim().toLowerCase();
      for (var c in _searchCategories) {
        final cName = c['name']?.toString().trim().toLowerCase();
        if (cName == trimmedName) {
          final code = int.tryParse(c['iconCode']?.toString() ?? '');
          if (code != null && code > 0) {
            return IconData(code, fontFamily: 'MaterialIcons');
          }
        }
      }
    }
    switch (catName) {
      case 'Chuyến bay':
        return Icons.flight_takeoff_rounded;
      case 'Chỗ ở':
        return Icons.hotel_rounded;
      case 'Xe thuê':
        return Icons.directions_car_rounded;
      case 'Phương tiện công cộng':
        return Icons.directions_bus_rounded;
      case 'Ẩm thực':
        return Icons.restaurant_rounded;
      case 'Đồ uống':
        return Icons.local_bar_rounded;
      case 'Tham quan':
        return Icons.account_balance_rounded;
      case 'Hoạt động':
        return Icons.local_activity_rounded;
      case 'Mua sắm':
        return Icons.shopping_bag_rounded;
      case 'Xăng':
        return Icons.local_gas_station_rounded;
      case 'Hàng tạp hóa':
        return Icons.shopping_cart_rounded;
      default:
        return Icons.receipt_long_rounded;
    }
  }

  Color _getCategoryColor(String catName) {
    final name = catName.toLowerCase().trim();
    if (name.contains('bay') || name.contains('flight')) {
      return const Color(0xFF0284C7); // Sky Blue
    } else if (name.contains('ở') ||
        name.contains('khách') ||
        name.contains('chỗ') ||
        name.contains('hotel')) {
      return const Color(0xFF7C3AED); // Purple
    } else if (name.contains('xe') ||
        name.contains('tiện') ||
        name.contains('transit') ||
        name.contains('car')) {
      return const Color(0xFF2563EB); // Royal Blue
    } else if (name.contains('thực') ||
        name.contains('ăn') ||
        name.contains('food') ||
        name.contains('restaurant')) {
      return const Color(0xFFF59E0B); // Amber / Warm Orange
    } else if (name.contains('uống') ||
        name.contains('bar') ||
        name.contains('cafe') ||
        name.contains('đồ uống')) {
      return const Color(0xFFD97706); // Dark Amber
    } else if (name.contains('quan') ||
        name.contains('tham') ||
        name.contains('sights')) {
      return const Color(0xFFEC4899); // Pink
    } else if (name.contains('động') ||
        name.contains('hoạt') ||
        name.contains('activity')) {
      return const Color(0xFF10B981); // Emerald
    } else if (name.contains('sắm') ||
        name.contains('mua') ||
        name.contains('shop')) {
      return const Color(0xFF8B5CF6); // Violet
    } else if (name.contains('xăng') || name.contains('gas')) {
      return const Color(0xFFEF4444); // Red
    } else if (name.contains('hóa') || name.contains('tạp')) {
      return const Color(0xFF059669); // Green
    }
    return const Color(0xFF6366F1); // Indigo default
  }

  String? _getPayerAvatarUrl(String payer) {
    if (_itineraryMembers.isNotEmpty) {
      final firstPayer = payer.split(',').first.trim();
      for (var m in _itineraryMembers) {
        final userObj = (m['user'] as Map<String, dynamic>?) ?? m;
        final String nameCandidate =
            (userObj['fullName'] ??
                    userObj['name'] ??
                    userObj['username'] ??
                    m['fullName'] ??
                    m['name'] ??
                    '')
                .toString()
                .trim();
        final bool isOwner =
            m['role'] == 'OWNER' ||
            (m['userId'] != null &&
                _itineraryData['userId'] != null &&
                m['userId'].toString() == _itineraryData['userId'].toString());
        final String displayName = isOwner
            ? 'Bạn ($nameCandidate)'
            : nameCandidate;

        if (firstPayer == displayName ||
            firstPayer == nameCandidate ||
            (nameCandidate.isNotEmpty && firstPayer.contains(nameCandidate))) {
          final String? rawAvatar = userObj['avatarUrl'] ?? userObj['avatar'];
          if (rawAvatar != null &&
              rawAvatar.trim().isNotEmpty &&
              !rawAvatar.contains('default-avatar')) {
            final trimmed = rawAvatar.trim();
            if (trimmed.startsWith('http')) return trimmed;
            if (trimmed.startsWith('/')) return '${ApiClient.baseUrl}$trimmed';
            return '${ApiClient.baseUrl}/$trimmed';
          }
        }
      }
    }
    final currentUser = AuthService().currentUser.value;
    if (currentUser != null &&
        currentUser.avatar != null &&
        currentUser.avatar!.isNotEmpty) {
      final raw = currentUser.avatar!.trim();
      if (raw.startsWith('http')) return raw;
      if (raw.startsWith('/')) return '${ApiClient.baseUrl}$raw';
      return '${ApiClient.baseUrl}/$raw';
    }
    return null;
  }

  String _getSortOptionLabel(String opt) {
    switch (opt) {
      case 'OLDEST':
        return 'Ngày (cũ nhất trước)';
      case 'PRICE_HIGH':
        return 'Giá (cao đến thấp)';
      case 'PRICE_LOW':
        return 'Giá (thấp đến cao)';
      default:
        return 'Ngày (mới nhất trước)';
    }
  }

  num _convertExpenseToItineraryCurrency(Map<String, dynamic> exp) {
    final num amt = (exp['amount'] as num?) ?? 0;
    if (amt <= 0) return 0;

    String expCode = (exp['currencyCode'] ?? exp['currency'] ?? '')
        .toString()
        .trim()
        .toUpperCase();
    String expSymbol = (exp['currencySymbol'] ?? '').toString().trim();

    if (expCode.isEmpty) {
      if (expSymbol == r'$' || expSymbol == 'USD') {
        expCode = 'USD';
      } else if (expSymbol == '€' || expSymbol == 'EUR') {
        expCode = 'EUR';
      } else if (expSymbol == '¥' || expSymbol == 'JPY' || expSymbol == 'CNY') {
        expCode = 'JPY';
      } else if (expSymbol == '₩' || expSymbol == 'KRW') {
        expCode = 'KRW';
      } else if (expSymbol == '£' || expSymbol == 'GBP') {
        expCode = 'GBP';
      } else if (expSymbol == '฿' || expSymbol == 'THB') {
        expCode = 'THB';
      } else {
        expCode = 'VND';
      }
    }

    final String targetCode = (_itineraryData['currencyCode'] ?? 'VND')
        .toString()
        .trim()
        .toUpperCase();

    if (expCode == targetCode) return amt;

    final double expRate = _currencyRates[expCode] ?? 1.0;
    final double targetRate = _currencyRates[targetCode] ?? 1.0;

    final double valueInTarget = (amt * expRate) / targetRate;
    return valueInTarget;
  }

  String _formatExpenseAmount(
    num amount, {
    String? currencySymbol,
    String? currencyCode,
  }) {
    String symbol = (currencySymbol != null && currencySymbol.trim().isNotEmpty)
        ? currencySymbol.trim()
        : '';
    String code = (currencyCode != null && currencyCode.trim().isNotEmpty)
        ? currencyCode.trim().toUpperCase()
        : '';

    if (symbol.isEmpty) {
      symbol = _itineraryData['currencySymbol']?.toString().trim() ?? '';
    }
    if (code.isEmpty) {
      code =
          _itineraryData['currencyCode']?.toString().trim().toUpperCase() ?? '';
    }

    if ((symbol.isEmpty || symbol == 'đ') && code.isNotEmpty && code != 'VND') {
      switch (code) {
        case 'USD':
        case 'AUD':
        case 'CAD':
        case 'SGD':
          symbol = r'$';
          break;
        case 'EUR':
          symbol = '€';
          break;
        case 'JPY':
        case 'CNY':
          symbol = '¥';
          break;
        case 'KRW':
          symbol = '₩';
          break;
        case 'GBP':
          symbol = '£';
          break;
        case 'THB':
          symbol = '฿';
          break;
      }
    }

    if (symbol == 'USD' || code == 'USD') {
      symbol = r'$';
    } else if (symbol == 'EUR' || code == 'EUR') {
      symbol = '€';
    } else if (symbol == 'JPY' ||
        code == 'JPY' ||
        symbol == 'CNY' ||
        code == 'CNY') {
      symbol = '¥';
    } else if (symbol == 'KRW' || code == 'KRW') {
      symbol = '₩';
    } else if (symbol == 'GBP' || code == 'GBP') {
      symbol = '£';
    } else if (symbol == 'THB' || code == 'THB') {
      symbol = '฿';
    } else if (symbol == 'SGD' || code == 'SGD') {
      symbol = r'S$';
    } else if (symbol == 'AUD' || code == 'AUD') {
      symbol = r'A$';
    } else if (symbol == 'CAD' || code == 'CAD') {
      symbol = r'CA$';
    } else if (symbol == 'TWD' || code == 'TWD') {
      symbol = r'NT$';
    }

    if (symbol.isEmpty) symbol = 'đ';

    final bool isSuffix = symbol == 'đ' || symbol == 'VNĐ' || symbol == 'VND';

    String formatted;
    if (isSuffix || symbol == '¥' || symbol == '₩') {
      final intVal = amount.round();
      formatted = intVal.toString().replaceAllMapped(
        RegExp(r'(\d{1,3})(?=(\d{3})+(?!\d))'),
        (Match m) => '${m[1]}.',
      );
    } else {
      final double doubleVal = amount.toDouble();
      if ((doubleVal - doubleVal.roundToDouble()).abs() < 0.01) {
        formatted = doubleVal.round().toString().replaceAllMapped(
          RegExp(r'(\d{1,3})(?=(\d{3})+(?!\d))'),
          (Match m) => '${m[1]}.',
        );
      } else {
        final String fixedStr = doubleVal.toStringAsFixed(2);
        final parts = fixedStr.split('.');
        final whole = parts[0].replaceAllMapped(
          RegExp(r'(\d{1,3})(?=(\d{3})+(?!\d))'),
          (Match m) => '${m[1]}.',
        );
        formatted = '$whole.${parts[1]}';
      }
    }

    if (isSuffix) {
      return '$formatted đ';
    } else {
      return '$symbol$formatted';
    }
  }

  String _formatShareDisplay(String? shareStr, [List? members]) {
    if (shareStr == null || shareStr.isEmpty) return 'Không chia sẻ';
    if (!shareStr.startsWith('Cá nhân')) return shareStr;
    if (!shareStr.contains(':')) return 'Cá nhân';

    final rawPart = shareStr.split(':')[1].trim();
    if (rawPart.isEmpty) return 'Cá nhân';

    final idsOrNames = rawPart
        .split(',')
        .map((s) => s.trim())
        .where((s) => s.isNotEmpty)
        .toList();
    final List memList = (members != null && members.isNotEmpty)
        ? members
        : (_itineraryData['members'] as List? ?? []);

    List<String> formatted = [];
    for (var item in idsOrNames) {
      dynamic found;
      for (var mem in memList) {
        if (mem is Map) {
          final userObj = (mem['user'] as Map<String, dynamic>?) ?? mem;
          final idStr = (userObj['id'] ?? mem['userId'] ?? mem['id'] ?? '')
              .toString();
          final nameStr =
              (userObj['fullName'] ??
                      userObj['name'] ??
                      mem['fullName'] ??
                      mem['name'] ??
                      '')
                  .toString()
                  .trim();
          if (idStr == item || nameStr == item) {
            found = mem;
            break;
          }
        }
      }

      if (found != null && found is Map) {
        final userObj = (found['user'] as Map<String, dynamic>?) ?? found;
        final nameCandidate =
            (userObj['fullName'] ??
                    userObj['name'] ??
                    userObj['username'] ??
                    found['fullName'] ??
                    found['name'] ??
                    item)
                .toString()
                .trim();
        formatted.add(nameCandidate.isNotEmpty ? nameCandidate : item);
      } else {
        formatted.add(item);
      }
    }

    return 'Cá nhân: ${formatted.join(', ')}';
  }

