                          onPressed: () {
                            final int parsedAmt =
                                int.tryParse(amountController.text.trim()) ?? 0;
                            if (parsedAmt <= 0) {
                              ScaffoldMessenger.of(context).showSnackBar(
                                const SnackBar(
                                  content: Text(
                                    'Vui lòng nhập số tiền thanh toán hợp lệ',
                                  ),
                                ),
                              );
                              return;
