                                  'isReverted': false,
                                };

                                setState(() {
                                  _settlements.insert(0, newSt);
                                });

                                if (itineraryId > 0) {
                                  DatabaseService()
                                      .addSettlement(itineraryId, newSt)
                                      .then((res) {
                                        if (res != null && res['id'] != null) {
                                          setState(() {
                                            newSt['id'] = res['id'].toString();
                                          });
                                          _saveSettlementsToPrefs();
                                        }
                                      });
                                }
                              }
                              _saveSettlementsToPrefs();

                              Navigator.pop(context);
