                      child: Row(
                        children: [
                          Icon(Icons.search, color: Colors.grey[500], size: 20),
                          const SizedBox(width: 10),
                          Expanded(
                            child: TextField(
                              controller: searchController,
                              onChanged: (val) {
                                setModalState(() {
                                  searchQuery = val;
