                          ),
                          if (searchQuery.isNotEmpty)
                            GestureDetector(
                              onTap: () {
                                setModalState(() {
                                  searchController.clear();
                                  searchQuery = '';
                                });
                              },
                              child: Icon(
                                Icons.cancel,
                                color: Colors.grey[400],
                                size: 18,
                              ),
