  void _showAllTripItemsSheet(
    Function({
      required String categoryName,
      required IconData categoryIcon,
      String? placeName,
    })
    onSelect,
  ) {
    String searchQuery = '';
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (context) {
        final List<Map<String, dynamic>> validPlaces = [];
        for (var item in [...?_savedPlaces, ...?_details]) {
          final placeObj =
              (item['place'] as Map<String, dynamic>?) ??
              (item['itemType'] == 'PLACE' ? item : null);
          final realName =
              placeObj?['name'] ?? item['place_name'] ?? item['name'];
          if (realName != null &&
              realName.toString().trim().isNotEmpty &&
              realName != 'Địa điểm') {
            if (!validPlaces.any((existing) {
              final eObj =
                  (existing['place'] as Map<String, dynamic>?) ?? existing;
              final eName = eObj['name'] ?? existing['name'];
              return eName == realName;
            })) {
              validPlaces.add(item);
            }
          }
        }

        return StatefulBuilder(
          builder: (context, setModalState) {
            final allItems = validPlaces.where((p) {
              final placeObj = (p['place'] as Map<String, dynamic>?) ?? p;
              final name = (placeObj['name'] ?? p['name'] ?? p['title'] ?? '')
                  .toString()
                  .toLowerCase();
              return name.contains(searchQuery.toLowerCase());
            }).toList();

            return SafeArea(
              child: Container(
                height: MediaQuery.of(context).size.height * 0.85,
                padding: const EdgeInsets.symmetric(
                  horizontal: 20,
                  vertical: 16,
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        GestureDetector(
                          onTap: () => Navigator.pop(context),
                          child: Icon(
                            Icons.arrow_back,
                            color: AppTheme.darkText,
                          ),
                        ),
                        const SizedBox(width: 16),
                        Expanded(
                          child: Text(
                            'Tất cả các mục chuyến đi',
                            style: TextStyle(
                              fontSize: 18,
                              fontWeight: FontWeight.bold,
                              color: AppTheme.darkText,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 16),

                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 14),
                      decoration: BoxDecoration(
                        color: const Color(0xFFF1F5F9),
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: TextField(
                        onChanged: (val) {
                          setModalState(() {
                            searchQuery = val;
                          });
                        },
                        decoration: const InputDecoration(
                          hintText: 'Tìm kiếm',
                          prefixIcon: Icon(Icons.search, color: Colors.grey),
                          border: InputBorder.none,
                          contentPadding: EdgeInsets.symmetric(vertical: 12),
                        ),
                      ),
                    ),
                    const SizedBox(height: 20),

                    Text(
                      'Chọn nhanh từ các danh sách của bạn',
                      style: TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.bold,
                        color: AppTheme.darkText,
                      ),
                    ),
                    const SizedBox(height: 12),

                    Expanded(
                      child: allItems.isEmpty
                          ? Center(
                              child: Text(
                                'Không tìm thấy mục nào',
                                style: TextStyle(color: Colors.grey[500]),
                              ),
                            )
                          : ListView.separated(
                              itemCount: allItems.length,
                              separatorBuilder: (_, _) =>
                                  const Divider(height: 1),
                              itemBuilder: (context, idx) {
                                final p = allItems[idx];
                                final placeObj =
                                    (p['place'] as Map<String, dynamic>?) ?? p;
                                final name =
                                    placeObj['name'] ??
                                    p['name'] ??
                                    p['title'] ??
                                    'Mục chuyến đi';

                                IconData itemIcon = Icons.location_on_outlined;
                                final catObj =
                                    (placeObj['category']
                                        as Map<String, dynamic>?) ??
                                    (p['category'] as Map<String, dynamic>?);
                                if (catObj != null) {
                                  final code = int.tryParse(
                                    catObj['iconCode']?.toString() ?? '',
                                  );
                                  if (code != null) {
                                    itemIcon = IconData(
                                      code,
                                      fontFamily: 'MaterialIcons',
                                    );
                                  } else if (catObj['name'] != null) {
                                    itemIcon = _getCategoryIconData(
                                      catObj['name'].toString(),
                                    );
                                  }
                                }

                                final catName =
                                    catObj?['name']?.toString() ?? 'Tham quan';
                                final section = p['section_name'] ?? catName;

                                return ListTile(
                                  contentPadding: EdgeInsets.zero,
                                  leading: Container(
                                    padding: const EdgeInsets.all(8),
                                    decoration: BoxDecoration(
                                      color: AppTheme.surfaceVariant,
                                      shape: BoxShape.circle,
                                    ),
                                    child: Icon(
                                      itemIcon,
                                      size: 20,
                                      color: AppTheme.darkText,
                                    ),
                                  ),
                                  title: Text(
                                    name,
                                    style: const TextStyle(
                                      fontSize: 14,
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                                  trailing: Text(
                                    section,
                                    style: TextStyle(
                                      fontSize: 12,
                                      color: Colors.grey[500],
                                    ),
                                  ),
                                  onTap: () {
                                    onSelect(
                                      categoryName: catName,
                                      categoryIcon: itemIcon,
                                      placeName: name,
                                    );
                                    Navigator.pop(context);
                                  },
                                );
                              },
                            ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

  void _showCategoryPickerSheet(
    Function({
      required String categoryName,
      required IconData categoryIcon,
      String? placeName,
    })
    onSelect,
  ) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (context) {
        final List<Map<String, dynamic>> validPlaces = [];
        for (var item in [...?_savedPlaces, ...?_details]) {
          final placeObj =
              (item['place'] as Map<String, dynamic>?) ??
              (item['itemType'] == 'PLACE' ? item : null);
          final realName =
