  Widget _buildExpensesTab() {
    int totalSpent = 0;
    for (var exp in _customExpenses) {
      totalSpent += _convertExpenseToItineraryCurrency(exp).round();
    }

    List<Map<String, dynamic>> sortedExpenses = List.from(_customExpenses);
    if (_sortExpensesOption == 'NEWEST') {
      sortedExpenses = sortedExpenses.reversed.toList();
    } else if (_sortExpensesOption == 'OLDEST') {
      // original order
    } else if (_sortExpensesOption == 'PRICE_HIGH') {
      sortedExpenses.sort(
        (a, b) =>
            ((b['amount'] as num?) ?? 0).compareTo((a['amount'] as num?) ?? 0),
      );
    } else if (_sortExpensesOption == 'PRICE_LOW') {
      sortedExpenses.sort(
        (a, b) =>
            ((a['amount'] as num?) ?? 0).compareTo((b['amount'] as num?) ?? 0),
      );
    }

    final bool isOverBudget = _tripBudget > 0 && totalSpent > _tripBudget;

    return Container(
      color: AppTheme.background,
      child: Stack(
        children: [
          ListView.builder(
            padding: EdgeInsets.fromLTRB(
              16,
              8,
              16,
              80 + MediaQuery.of(context).padding.bottom,
            ),
            itemCount: sortedExpenses.isEmpty ? 2 : sortedExpenses.length + 1,
            itemBuilder: (context, idx) {
              if (idx == 0) {
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    // Sleek Light Brand Hero Card
                    Container(
                      margin: const EdgeInsets.only(bottom: 12),
                      padding: const EdgeInsets.all(20),
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                          colors: isOverBudget
                              ? [
                                  const Color(0xFFFFF1F2),
                                  const Color(0xFFFFE4E6),
                                ]
                              : [
                                  const Color(0xFFEFF6FF),
                                  const Color(0xFFE0F2FE),
                                ],
                        ),
                        borderRadius: BorderRadius.circular(24),
                        border: Border.all(
                          color: isOverBudget
                              ? const Color(0xFFFECDD3)
                              : const Color(0xFFBAE6FD),
                        ),
                        boxShadow: [
                          BoxShadow(
                            color:
                                (isOverBudget
                                        ? Colors.redAccent
                                        : AppTheme.primary)
                                    .withValues(alpha: 0.06),
                            blurRadius: 16,
                            offset: const Offset(0, 4),
                          ),
                        ],
                      ),
                      child: Column(
                        children: [
                          Row(
                            mainAxisAlignment: MainAxisAlignment.center,
                            children: [
                              Container(
                                padding: const EdgeInsets.all(8),
                                decoration: BoxDecoration(
                                  color:
                                      (isOverBudget
                                              ? Colors.redAccent
                                              : AppTheme.primary)
                                          .withValues(alpha: 0.12),
                                  shape: BoxShape.circle,
                                ),
                                child: Icon(
                                  Icons.account_balance_wallet_rounded,
                                  color: isOverBudget
                                      ? Colors.redAccent
                                      : AppTheme.primary,
                                  size: 20,
                                ),
                              ),
                              const SizedBox(width: 10),
                              Text(
                                _formatExpenseAmount(totalSpent),
                                style: TextStyle(
                                  color: isOverBudget
                                      ? Colors.red[900]
                                      : AppTheme.darkText,
                                  fontSize: 34,
                                  fontWeight: FontWeight.bold,
                                  letterSpacing: -0.5,
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 8),
                          if (_tripBudget <= 0) ...[
                            GestureDetector(
                              onTap: _showSetBudgetSheet,
                              child: Container(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 14,
                                  vertical: 6,
                                ),
                                decoration: BoxDecoration(
                                  color: Colors.white,
                                  borderRadius: BorderRadius.circular(16),
                                  border: Border.all(
                                    color: const Color(0xFFCBD5E1),
