                                const SizedBox(width: 8),
                                GestureDetector(
                                  onTap: _showGroupBalanceSheet,
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(
                                      horizontal: 14,
                                      vertical: 8,
                                    ),
                                    decoration: BoxDecoration(
                                      color: Colors.white,
                                      borderRadius: BorderRadius.circular(20),
                                      border: Border.all(
                                        color: const Color(0xFFCBD5E1),
                                      ),
                                    ),
                                    child: Row(
                                      children: [
                                        Icon(
                                          Icons.monetization_on_outlined,
                                          color: AppTheme.primary,
                                          size: 18,
                                        ),
                                        const SizedBox(width: 6),
                                        Text(
                                          'Số dư nhóm',
                                          style: TextStyle(
                                            color: AppTheme.darkText,
                                            fontSize: 13,
                                            fontWeight: FontWeight.bold,
                                          ),
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                GestureDetector(
                                  onTap: _showExpenseAnalyticsSheet,
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(
                                      horizontal: 14,
                                      vertical: 8,
                                    ),
                                    decoration: BoxDecoration(
                                      color: Colors.white,
                                      borderRadius: BorderRadius.circular(20),
                                      border: Border.all(
                                        color: const Color(0xFFCBD5E1),
                                      ),
                                    ),
                                    child: Row(
                                      children: [
                                        Icon(
                                          Icons.equalizer_rounded,
                                          color: AppTheme.primary,
                                          size: 18,
                                        ),
                                        const SizedBox(width: 6),
                                        Text(
                                          'Xem phân tích chi tiêu',
                                          style: TextStyle(
                                            color: AppTheme.darkText,
                                            fontSize: 13,
                                            fontWeight: FontWeight.bold,
                                          ),
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),

                    // Title & Sort Row
                    Padding(
                      padding: const EdgeInsets.fromLTRB(4, 12, 4, 12),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Text(
                            'Chi phí',
                            style: TextStyle(
                              fontSize: 22,
                              fontWeight: FontWeight.bold,
                              color: AppTheme.darkText,
                            ),
                          ),
                          PopupMenuButton<String>(
                            onSelected: (val) {
                              setState(() {
                                _sortExpensesOption = val;
                              });
                            },
                            child: Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 6,
                              ),
                              decoration: BoxDecoration(
                                color: const Color(0xFFF1F5F9),
                                borderRadius: BorderRadius.circular(16),
                              ),
                              child: Row(
                                children: [
                                  Text(
                                    'Sắp xếp: ${_getSortOptionLabel(_sortExpensesOption)}',
                                    style: TextStyle(
                                      fontSize: 12,
                                      color: AppTheme.darkText,
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                                  Icon(
                                    Icons.arrow_drop_down_rounded,
                                    color: AppTheme.darkText,
                                    size: 18,
                                  ),
                                ],
                              ),
                            ),
                            itemBuilder: (context) => [
                              const PopupMenuItem(
                                value: 'NEWEST',
                                child: Text('Ngày (mới nhất trước)'),
                              ),
                              const PopupMenuItem(
                                value: 'OLDEST',
                                child: Text('Ngày (cũ nhất trước)'),
                              ),
                              const PopupMenuItem(
                                value: 'PRICE_HIGH',
                                child: Text('Giá (cao đến thấp)'),
                              ),
                              const PopupMenuItem(
                                value: 'PRICE_LOW',
                                child: Text('Giá (thấp đến cao)'),
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  ],
                );
              }

              if (sortedExpenses.isEmpty) {
                return Padding(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 16,
                  ),
                  child: Text(
                    'Bạn chưa thêm chi phí nào. Theo dõi chi phí của bạn và chia sẻ chi phí bằng cách thêm một chi phí.',
                    style: TextStyle(
                      fontSize: 14,
                      color: Colors.grey[600],
                      height: 1.5,
                    ),
                  ),
                );
              }

              final itemIndex = idx - 1;
              final item = sortedExpenses[itemIndex];
              final title = item['title'] ?? 'Chi phí';
              final amt = (item['amount'] as num?)?.toInt() ?? 0;
              final payer = (item['payer'] ?? 'Bạn').toString();
              final date = item['date'] ?? '';
              final categoryName = item['category'] ?? 'Khác';

              final firstPayer = payer.split(',').first.trim();
              final payerInitial = firstPayer.isNotEmpty
                  ? firstPayer[0].toUpperCase()
                  : '?';
              final Color payerColor =
                  Colors.primaries[firstPayer.hashCode.abs() %
                      Colors.primaries.length];
              final String? payerAvatarUrl = _getPayerAvatarUrl(payer);
              final Color catColor = _getCategoryColor(categoryName);

              final tileWidget = Material(
                color: Colors.transparent,
                child: ListTile(
                  onTap: () {
                    if (!_isViewer) {
                      _showAddExpenseBottomSheet(expenseToEdit: item);
                    }
                  },
                  contentPadding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 4,
                  ),
                  leading: Container(
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: catColor.withValues(alpha: 0.12),
                      borderRadius: BorderRadius.circular(14),
                    ),
                    child: Icon(
                      _getCategoryIconData(
                        categoryName,
                        iconCode: (item['iconCode'] as num?)?.toInt(),
                      ),
                      color: catColor,
                      size: 22,
                    ),
                  ),
                  title: Text(
                    title,
                    style: const TextStyle(
                      fontWeight: FontWeight.bold,
                      fontSize: 15,
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                  subtitle: Text(
                    '$date • $categoryName',
                    style: TextStyle(fontSize: 12, color: Colors.grey[600]),
                  ),
                  trailing: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    crossAxisAlignment: CrossAxisAlignment.end,
                    children: [
                      Text(
                        _formatExpenseAmount(
                          amt,
                          currencySymbol: item['currencySymbol']?.toString(),
                          currencyCode: item['currencyCode']?.toString(),
                        ),
                        style: TextStyle(
                          fontWeight: FontWeight.bold,
                          fontSize: 15,
                          color: AppTheme.darkText,
                        ),
                      ),
                      const SizedBox(height: 2),
                      CircleAvatar(
                        radius: 11,
                        backgroundColor: payerColor,
                        foregroundImage: payerAvatarUrl != null
                            ? NetworkImage(payerAvatarUrl)
                            : null,
                        child: Text(
                          payerInitial,
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 10,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              );

              if (_isViewer) return tileWidget;

              return Slidable(
                key: ValueKey('expense_${item['id'] ?? itemIndex}'),
                endActionPane: ActionPane(
                  motion: const ScrollMotion(),
                  extentRatio: 0.22,
                  children: [
                    CustomSlidableAction(
                      onPressed: (context) async {
                        final expId = item['id'];
                        final effSavedPlaceId = item['savedPlaceId'];
                        final effDetailId = item['detailId'];

                        setState(() {
                          _syncExpenseAmountToPlace(
                            effSavedPlaceId,
                            effDetailId,
                            0,
                          );
                          if (effSavedPlaceId != null) {
                            final idx = _savedPlaces.indexWhere(
                              (sp) =>
                                  sp['id']?.toString() ==
                                  effSavedPlaceId.toString(),
                            );
                            if (idx != -1) _savedPlaces[idx]['expense'] = null;
                          }
                          if (effDetailId != null) {
                            final idx = _details.indexWhere(
                              (d) =>
                                  d['id']?.toString() == effDetailId.toString(),
                            );
                            if (idx != -1) _details[idx]['expense'] = null;
                          }
                          _customExpenses.remove(item);
                          if (_customExpenses.isEmpty) {
                            _settlements.clear();
                            _saveSettlementsToPrefs();
                          } else if (expId != null) {
                            _settlements.removeWhere(
                              (st) =>
                                  st['expenseId']?.toString() ==
                                  expId.toString(),
                            );
                            _saveSettlementsToPrefs();
                          }
                        });
                        _saveExpensesToPrefs();

                        if (expId != null) {
                          await DatabaseService().deleteExpense(expId);
                        }
                        if (mounted) {
                          final itinId =
                              (_itineraryData['id'] as num?)?.toInt() ?? 0;
                          if (itinId > 0) {
                            DatabaseService().getExpenses(itinId).then((
                              serverExp,
                            ) {
                              if (mounted)
                                setState(() => _customExpenses = serverExp);
                              _saveExpensesToPrefs();
                            });
                            DatabaseService().getSettlements(itinId).then((
                              serverSt,
                            ) {
                              if (mounted)
                                setState(() => _settlements = serverSt);
                              _saveSettlementsToPrefs();
                            });
                          }
                        }
                      },
                      backgroundColor: const Color(0xFFFF5252),
                      foregroundColor: Colors.white,
                      borderRadius: BorderRadius.circular(16),
                      child: const Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          Icon(Icons.delete, color: Colors.white, size: 22),
                          SizedBox(height: 4),
                          Text(
                            'Xóa',
                            style: TextStyle(
                              color: Colors.white,
                              fontSize: 13,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
                child: tileWidget,
              );
            },
          ),
          if (!_isViewer)
            Positioned(
              bottom: 20,
              left: 0,
              right: 0,
              child: Center(
                child: ElevatedButton.icon(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: AppTheme.primary,
                    foregroundColor: Colors.white,
                    padding: const EdgeInsets.symmetric(
                      horizontal: 28,
                      vertical: 14,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(30),
                    ),
                    elevation: 4,
                  ),
                  icon: const Icon(Icons.add, size: 20),
                  label: const Text(
                    'Thêm chi phí',
                    style: TextStyle(fontSize: 15, fontWeight: FontWeight.bold),
                  ),
                  onPressed: _showAddExpenseBottomSheet,
                ),
              ),
            ),
        ],
      ),
    );
  }
}

/// Bottom sheet widget for picking from pre-made checklist templates
class _ChecklistTemplateSheet extends StatefulWidget {
  final int checklistId;
  final List<dynamic> currentItems;
  final void Function(List<String> newItems) onAddItems;

  const _ChecklistTemplateSheet({
    required this.checklistId,
    required this.currentItems,
    required this.onAddItems,
  });

  @override
  State<_ChecklistTemplateSheet> createState() =>
      _ChecklistTemplateSheetState();
}

class _ChecklistTemplateSheetState extends State<_ChecklistTemplateSheet>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  List<Map<String, dynamic>> _templates = [];
  // Selected item names
  final Set<String> _selectedItems = {};
  // Expanded category ids
  final Set<int> _expandedCategories = {};
  bool _loading = true;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 2, vsync: this);
    _loadTemplates();
  }

  Future<void> _loadTemplates() async {
    final data = await DatabaseService().fetchChecklistTemplates();
    if (mounted) {
      setState(() {
        _templates = data;
        _loading = false;
      });
    }
  }

  List<Map<String, dynamic>> _getForTab(String tabType) {
    return _templates
        .where((t) => t['tabType'] == tabType || t['tabtype'] == tabType)
        .toList();
  }

  void _addSelected() {
    widget.onAddItems(_selectedItems.toList());
    Navigator.pop(context);
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      height: MediaQuery.of(context).size.height * 0.82,
      decoration: const BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      child: Column(
        children: [
          // Handle bar
          Container(
            margin: const EdgeInsets.only(top: 12, bottom: 4),
            width: 40,
            height: 4,
            decoration: BoxDecoration(
              color: Colors.grey[300],
              borderRadius: BorderRadius.circular(4),
            ),
          ),
          // Header
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
            child: Row(
              children: [
                GestureDetector(
                  onTap: () => Navigator.pop(context),
                  child: const Text(
                    'Hủy',
                    style: TextStyle(color: Colors.grey, fontSize: 14),
                  ),
                ),
                const Expanded(
                  child: Text(
                    'Thêm từ một mẫu',
                    textAlign: TextAlign.center,
                    style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
                  ),
                ),
                GestureDetector(
                  onTap: _addSelected,
                  child: Text(
                    'Thêm',
                    style: TextStyle(
                      color: AppTheme.primary,
                      fontWeight: FontWeight.bold,
                      fontSize: 14,
                    ),
                  ),
                ),
              ],
            ),
          ),
          const Padding(
            padding: EdgeInsets.symmetric(horizontal: 16, vertical: 4),
            child: Text(
              'Chọn các mục để thêm vào danh sách kiểm tra của bạn',
              textAlign: TextAlign.center,
              style: TextStyle(color: Colors.grey, fontSize: 13),
            ),
          ),
          // Tab bar
          Container(
            margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
            decoration: BoxDecoration(
              color: const Color(0xFFF1F5F9),
              borderRadius: BorderRadius.circular(12),
            ),
            child: TabBar(
              controller: _tabController,
              labelColor: Colors.white,
              unselectedLabelColor: Colors.grey,
              indicator: BoxDecoration(
                color: AppTheme.primary,
                borderRadius: BorderRadius.circular(10),
              ),
              indicatorSize: TabBarIndicatorSize.tab,
              dividerColor: Colors.transparent,
              tabs: const [
                Tab(text: 'Danh sách đóng gói'),
                Tab(text: 'Nhiệm vụ trước'),
              ],
            ),
          ),
          const Divider(height: 1),
          Expanded(
            child: _loading
                ? const Center(child: CircularProgressIndicator())
                : TabBarView(
                    controller: _tabController,
                    children: [
                      _buildCategoryList('packing'),
                      _buildCategoryList('todo'),
                    ],
                  ),
          ),
        ],
      ),
    );
  }

  Widget _buildCategoryList(String tabType) {
    final cats = _getForTab(tabType);
    if (cats.isEmpty) {
      return const Center(
        child: Text('Không có mẫu nào', style: TextStyle(color: Colors.grey)),
      );
    }
    return ListView.builder(
      padding: const EdgeInsets.symmetric(vertical: 8),
      itemCount: cats.length,
      itemBuilder: (context, idx) {
        final cat = cats[idx];
        final catId = cat['id'] as int;
        final catName = cat['name'] as String;
        final items = cat['items'] as List? ?? [];
        final allItemNames = items.map((it) => it['name'] as String).toList();
        final bool isSelected =
            allItemNames.isNotEmpty &&
            allItemNames.every((name) => _selectedItems.contains(name));
        final isExpanded = _expandedCategories.contains(catId);

        return Column(
          children: [
            InkWell(
              onTap: () {
                setState(() {
                  if (isExpanded) {
                    _expandedCategories.remove(catId);
                  } else {
                    _expandedCategories.add(catId);
                  }
                });
              },
              child: Padding(
                padding: const EdgeInsets.symmetric(
                  horizontal: 20,
                  vertical: 14,
                ),
                child: Row(
                  children: [
                    Icon(
                      isExpanded
                          ? Icons.keyboard_arrow_down
                          : Icons.keyboard_arrow_right,
                      color: Colors.black54,
                      size: 20,
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        catName,
                        style: const TextStyle(
                          fontWeight: FontWeight.bold,
                          fontSize: 15,
                        ),
                      ),
                    ),
                    GestureDetector(
                      onTap: () {
                        setState(() {
                          if (isSelected) {
                            for (var name in allItemNames) {
                              _selectedItems.remove(name);
                            }
                          } else {
                            for (var name in allItemNames) {
                              _selectedItems.add(name);
                            }
                          }
                        });
                      },
                      child: Icon(
                        isSelected
                            ? Icons.check_box_rounded
                            : Icons.check_box_outline_blank_rounded,
                        color: isSelected
                            ? AppTheme.primary
                            : const Color(0xFFCBD5E1),
                        size: 22,
                      ),
                    ),
                  ],
                ),
              ),
            ),
            if (isExpanded)
              ...items.map((item) {
                final itemName = item['name'] as String;
                final bool isItemSelfSelected = _selectedItems.contains(
                  itemName,
                );
                return InkWell(
                  onTap: () {
                    setState(() {
                      if (isItemSelfSelected) {
                        _selectedItems.remove(itemName);
                      } else {
                        _selectedItems.add(itemName);
                      }
                    });
                  },
                  child: Padding(
                    padding: const EdgeInsets.only(
                      left: 48,
                      right: 20,
                      top: 6,
                      bottom: 6,
                    ),
                    child: Row(
                      children: [
                        Icon(
                          isItemSelfSelected
                              ? Icons.check_box_rounded
                              : Icons.check_box_outline_blank_rounded,
                          color: isItemSelfSelected
                              ? AppTheme.primary
                              : const Color(0xFFCBD5E1),
                          size: 18,
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Text(
                            itemName,
                            style: const TextStyle(
                              fontSize: 13,
                              color: Colors.black87,
                            ),
                            softWrap: true,
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }),
            const Divider(height: 1, indent: 20, endIndent: 20),
          ],
        );
      },
    );
  }
}

class RedSlashPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = Colors.red
      ..strokeWidth = 2.5
      ..strokeCap = StrokeCap.round;
    // Draw diagonal line from top-right to bottom-left
    canvas.drawLine(
      Offset(size.width * 0.75, size.height * 0.25),
      Offset(size.width * 0.25, size.height * 0.75),
      paint,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}
